服务端提供网页点击下载功能，或 WebApi 接口提供软件更新下载服务
继承 Controller 接口的控制器方法下载方式使用环境：网页端按钮点击下载按钮脚本链接进入这个方法之后，服务端直接生成文件，浏览器自动下载
/// &lt;summary&gt;/// 下载文件/// &lt;/summary&gt;/// &lt;returns&gt;是否下载成功&lt;/returns&gt;public ActionResult DownLoadFile()&#123;    string filePath = &quot;服务端文件路径（程序自动获取路径或根据传入参数判断文件路径）&quot;;    FileInfo fileInfo = new FileInfo(filePath);    if (fileInfo.Exists)    &#123;        Response.Clear();        Response.ClearContent();        Response.ClearHeaders();        Response.Buffer = true;        Response.AddHeader(&quot;Content-Disposition&quot;, &quot;attachment;filename=&quot; + Server.UrlEncode(fileInfo.Name));        Response.AddHeader(&quot;Content-Length&quot;, fileInfo.Length.ToString());        Response.AddHeader(&quot;Content-Transfer-Encoding&quot;, &quot;binary&quot;);        Response.ContentType = &quot;application/x-msdownload&quot;;        Response.ContentEncoding = System.Text.Encoding.GetEncoding(&quot;gb2312&quot;);        Response.WriteFile(fileInfo.FullName);        Response.Flush();        Response.End();        return Json(true);    &#125;    else    &#123;        return Json(false);    &#125;&#125;

继承 ApiController 接口的 WebApi 方法下载方式使用环境：桌面端自动更新 提交需要更新的文件名 获取下载服务端返回文件流，桌面端接收并保存到指定目录替换
/// &lt;summary&gt;/// 下载文件/// &lt;/summary&gt;/// &lt;returns&gt;文件数据流&lt;/returns&gt;[HttpGet]public byte[] DownLoadFile()&#123;    string filePath = &quot;服务端文件路径（程序自动获取路径或根据传入参数判断文件路径）&quot;;    return File.Exists(filePath) ? File.ReadAllBytes(filePath) : null;&#125;

服务端调用打印机打印Word文件
简介工作时需要直接操作 OA系统 调用打印机打印 Word 文件。
引用库介绍需要电脑安装 Microsoft Office 并引用COM组件 Microsoft.Office.Interop.Word 才可以调用打印机。
代码及调用打印Word
using Word = Microsoft.Office.Interop.Word;/// &lt;summary&gt;/// 打印Word/// &lt;/summary&gt;/// &lt;param name=&quot;filePath&quot;&gt;需要打印的文件&lt;/param&gt;/// &lt;param name=&quot;PrintName&quot;&gt;打印机名称&lt;/param&gt;private static void PrintWord(string filePath, string PrintName)&#123;    try    &#123;        //要打印的文件路径        Object wordFile = filePath;        object oMissing = Missing.Value;        //自定义object类型的布尔值        object oTrue = true;        object oFalse = false;        object doNotSaveChanges = Word.WdSaveOptions.wdDoNotSaveChanges;        //Word.Application appWord = null;        //定义word Application相关        Word.Application appWord = new Word.Application();        //word程序不可见        appWord.Visible = false;        //不弹出警告框        appWord.DisplayAlerts = Word.WdAlertLevel.wdAlertsNone;        //先保存默认的打印机        string defaultPrinter = appWord.ActivePrinter;        //打开要打印的文件        Word.Document doc = appWord.Documents.Open(            ref wordFile,            ref oMissing,            ref oTrue,            ref oFalse,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing            );        //设置指定的打印机名字        appWord.ActivePrinter = PrintName;        //打印        doc.PrintOut(            ref oTrue,//此处为true表示后台打印            ref oFalse,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing,            ref oMissing            );        //打印完关闭word文件        doc.Close(ref doNotSaveChanges, ref oMissing, ref oMissing);        //还原原来的默认打印机        appWord.ActivePrinter = defaultPrinter;        //退出word程序        appWord.Quit(ref oMissing, ref oMissing, ref oMissing);        doc = null;        appWord = null;    &#125;    catch (Exception ex)    &#123;        //代码行数        string line = ex.StackTrace.ToString();        //返回错误发生的方法定义        string errorfunction = ex.TargetSite.ToString();        int code = ex.HResult;    &#125;&#125;

调用方法
//打印WordPrintWord(dialog.FileName, &quot;审批打印机&quot;);

简介延时摄影 是以一种将时间压缩的拍摄技术。其拍摄的通常是一组照片，后期通过将照片串联合成视频，把几分钟、几小时甚至是几天的过程压缩在一个较短的时间内以视频的方式播放。在一段延时摄影视频中，物体或者景物缓慢变化的过程被压缩到一个较短的时间内，呈现出平时用肉眼无法察觉的奇异精彩的景象。
延时设置Canon EOS 5D Mark IV 提供两种延时拍摄方式，一种为延时短片，一种为定时间隔拍照。
延时短片佳能提供以常规录像方式的延时摄影，有点是设置简单，拍摄完成直接输出视频文件，但缺点是仅支持 1080P 的分辨率。需要切换到视频模式，并且关闭 WIFI 后才可设置。




定时间隔拍照定时间隔拍照为常规延时视频制作方式，优点是每一帧的画质都可以设置为相机拍照原本的画质，测试 5d4 合成视频上传后可以显示为 8K 超高清，缺点是需要使用软件合成视频，并且拍摄时不断的触发快门，对相机产生消耗，或许微单比单反更适合这样拍摄。




Adobe Premiere 导入使用 Adobe Premiere 导入素材，导入媒体选择第一张图片，勾选：图像序列 即可，拖入时间轴即可编辑视频


演示实拍由于实拍时处于阴天，效果并不是很理想，第一次实拍在曝光的设置上有些问题，导致黑天时过暗，下次在好好调。Bilibili 外链限制清晰度，打开原视频最高可看 8K 超高清。


