FFmpeg(yuv420p、nv12) 与 OpenCV Mat 互相转换
简介OpenCV 可以使用 VideoCapture 类读取视频，虽然同样是封装了 FFmpeg，但是也屏蔽了很多接口，想做一些复杂操作就很不方便。所以改用 FFmpeg 读取视频传递给 OpenCV 使用，将视频帧 FFmpeg AVFrame 转换为 OpenCV Mat。
解码帧软解码软解码解析出的 AVFrame 格式为：(AVPixelFormat)AV_PIX_FMT_YUV420P。需要使用 SwsContext 类转换为 Mat BGR24。
部分视频解析出的格式为：(AVPixelFormat)AV_PIX_FMT_YUVJ420P，直接转换会提示警告：Convert Deprecated Format，警告不重要，但最好还是转换不推荐的格式。
/// &lt;summary&gt;/// 转换不推荐的格式/// &lt;/summary&gt;AVPixelFormat ConvertDeprecatedFormat(enum AVPixelFormat format)&#123;	switch (format)	&#123;	case AV_PIX_FMT_YUVJ420P:		return AV_PIX_FMT_YUV420P;		break;	case AV_PIX_FMT_YUVJ422P:		return AV_PIX_FMT_YUV422P;		break;	case AV_PIX_FMT_YUVJ444P:		return AV_PIX_FMT_YUV444P;		break;	case AV_PIX_FMT_YUVJ440P:		return AV_PIX_FMT_YUV440P;		break;	default:		return format;		break;	&#125;&#125;

硬解码硬解码解析出的 AVFrame 格式为：显存 NV12。硬解码类型：AV_HWDEVICE_TYPE_CUDA 解析结果为 (AVPixelFormat)AV_PIX_FMT_CUDA。硬解码类型：AV_HWDEVICE_TYPE_DXVA2 解析结果为 (AVPixelFormat)AV_PIX_FMT_FXVA2_VLD。硬解码类型：AV_HWDEVICE_TYPE_D3D11VA 解析结果为 (AVPixelFormat)AV_PIX_FMT_D3D11。
使用 av_hwframe_transfer_data 函数把显存数据统一转换为内存数据 NV12。
if (pCodecCtx-&gt;hw_device_ctx)&#123;    AVFrame* hw_frame;    hw_frame = av_frame_alloc();    av_hwframe_transfer_data(hw_frame, frame, 0);&#125;

内存数据 NV12 格式为：(AVPixelFormat)AV_PIX_FMT_NV12。同样需要使用 SwsContext 类转换为 Mat BGR24。
转换 AVFrame To Mat/// &lt;summary&gt;/// 从 FFmpeg 图片类型转换为 OpenCV 类型/// 修改尺寸/// &lt;/summary&gt;/// &lt;param name=&quot;frame&quot;&gt;FFmpeg 图像&lt;/param&gt;/// &lt;param name=&quot;dstWidth&quot;&gt;输出图像宽度&lt;/param&gt;/// &lt;param name=&quot;dstHeight&quot;&gt;输出图像高度&lt;/param&gt;/// &lt;param name=&quot;isfree&quot;&gt;是否释放内存&lt;/param&gt;/// &lt;returns&gt;Mat&lt;/returns&gt;Mat AVFrameToMat(AVFrame* frame, int dstWidth, int dstHeight, bool isfree)&#123;	Mat image(dstHeight, dstWidth, CV_8UC3);	int srcWidth = frame-&gt;width;	int srcHeight = frame-&gt;height;	int cvLinesizes[1]&#123; image.step1() &#125;;	auto srcFormat = ConvertDeprecatedFormat((AVPixelFormat)frame-&gt;format);	SwsContext* conversion = sws_getContext(srcWidth, srcHeight, srcFormat, dstWidth, dstHeight, AV_PIX_FMT_BGR24, SWS_FAST_BILINEAR, NULL, NULL, NULL);	sws_scale(conversion, frame-&gt;data, frame-&gt;linesize, 0, srcHeight, &amp;image.data, cvLinesizes);	sws_freeContext(conversion);	if (isfree)	&#123;		av_frame_free(&amp;frame);	&#125;	return image;&#125;/// &lt;summary&gt;/// 从 FFmpeg 图片类型转换为 OpenCV 类型/// &lt;/summary&gt;/// &lt;param name=&quot;frame&quot;&gt;FFmpeg 图像&lt;/param&gt;/// &lt;param name=&quot;isfree&quot;&gt;是否释放内存&lt;/param&gt;/// &lt;returns&gt;Mat&lt;/returns&gt;Mat AVFrameToMat(AVFrame* frame, bool isfree)&#123;	return AVFrameToMat(frame, frame-&gt;width, frame-&gt;height, isfree);&#125;

转换 Mat To AVFrame/// &lt;summary&gt;/// 从 OpenCV 图片类型转换为 FFmpeg 类型/// 修改尺寸/// &lt;/summary&gt;/// &lt;param name=&quot;image&quot;&gt;OpenCV 图像&lt;/param&gt;/// &lt;param name=&quot;frame&quot;&gt;FFmpeg 图像&lt;/param&gt;/// &lt;param name=&quot;dstWidth&quot;&gt;输出图像宽度&lt;/param&gt;/// &lt;param name=&quot;dstHeight&quot;&gt;输出图像高度&lt;/param&gt;/// &lt;returns&gt;AVFrame&lt;/returns&gt;AVFrame* MatToAVFrame(Mat* image, AVFrame* frame, int dstWidth, int dstHeight)&#123;	if (frame == NULL)	&#123;		frame = av_frame_alloc();		frame-&gt;format = AV_PIX_FMT_YUV420P;		frame-&gt;width = dstWidth;		frame-&gt;height = dstHeight;		av_frame_get_buffer(frame, 0);		av_frame_make_writable(frame);	&#125;	int srcWidth = image-&gt;cols;	int srcHeight = image-&gt;rows;	int cvLinesizes[1]&#123; image-&gt;step1() &#125;;	SwsContext* conversion = sws_getContext(srcWidth, srcHeight, AV_PIX_FMT_BGR24, dstWidth, dstHeight, (AVPixelFormat)frame-&gt;format, SWS_FAST_BILINEAR, NULL, NULL, NULL);	sws_scale(conversion, &amp;image-&gt;data, cvLinesizes, 0, srcHeight, frame-&gt;data, frame-&gt;linesize);	sws_freeContext(conversion);	return frame;&#125;/// &lt;summary&gt;/// 从 OpenCV 图片类型转换为 FFmpeg 类型/// &lt;/summary&gt;/// &lt;param name=&quot;image&quot;&gt;OpenCV 图像&lt;/param&gt;/// &lt;param name=&quot;frame&quot;&gt;FFmpeg 图像&lt;/param&gt;/// &lt;returns&gt;AVFrame&lt;/returns&gt;AVFrame* MatToAVFrame(Mat* image, AVFrame* frame)&#123;	return MatToAVFrame(image, frame, image-&gt;cols, image-&gt;rows);&#125;

最近邻插值法与双线性差值法缩放图像
简介通常处理图像时经常会需要缩放图像，FFmpeg 可以使用 SwsContext 方法缩放图像，OpenCV 可以使用 cv::resize 方法缩放图像，但是用这些方法缩放的同时会消耗更多时间，在选择使用 CUDA 处理图像的情况下，就直接一起缩放图像。图像缩放有多重算法，最常见的是：

最近邻插值法：速度最快，但是有时可以看到明显锯齿。
双线性差值法：使用最多的方式，使用邻近四个点来计算像素值。
双三次插值法（不实现该方法）：速度较慢，使用邻近十六个点来计算像素值。

实现代码以 YUV NV12 图片格式编写，其他图片类型带入公式即可。
最近邻插值法计算方法计算图片缩放百分比，得到一个在原图像的百分比坐标吗，用当前坐标乘以百分比获取原图像像素值，通常为小数，删除小数部分取整使用左上角像素坐标，也可以选择四舍五入的方式，或者 +0.5 或 -0.5 后取整，作为缩放图像的像素值。
int fx = outX * (inWidth / outWidth);int fy = outY * (inHeight / outHeight);

代码/// &lt;summary&gt;/// 缩放图像核函数 YUV420P/// 最近邻插值/// &lt;/summary&gt;/// &lt;param name=&quot;pInYData&quot;&gt;输入图片 YUV YUV420P Y&lt;/param&gt;/// &lt;param name=&quot;pInUData&quot;&gt;输入图片 YUV YUV420P U&lt;/param&gt;/// &lt;param name=&quot;pInVData&quot;&gt;输入图片 YUV YUV420P V&lt;/param&gt;/// &lt;param name=&quot;pInWidth&quot;&gt;输入图片宽度&lt;/param&gt;/// &lt;param name=&quot;pInHeight&quot;&gt;输入图像高度&lt;/param&gt;/// &lt;param name=&quot;pOutYData&quot;&gt;输出图片 YUV YUV420P Y&lt;/param&gt;/// &lt;param name=&quot;pOutUData&quot;&gt;输出图片 YUV YUV420P U&lt;/param&gt;/// &lt;param name=&quot;pOutVData&quot;&gt;输出图片 YUV YUV420P V&lt;/param&gt;/// &lt;param name=&quot;pOutWidth&quot;&gt;输出图片宽度&lt;/param&gt;/// &lt;param name=&quot;pOutHeight&quot;&gt;输出图像高度&lt;/param&gt;/// &lt;returns&gt;缩放后图像&lt;/returns&gt;__global__ void ReSizeKernel_Nearest_YUV420P(unsigned char* pInYData, unsigned char* pInUData, unsigned char* pInVData, int pInWidth, int pInHeight,	unsigned char* pOutYData, unsigned char* pOutUData, unsigned char* pOutVData, int pOutWidth, int pOutHeight)&#123;	int tidx = threadIdx.x + blockDim.x * blockIdx.x;	int tidy = threadIdx.y + blockDim.y * blockIdx.y;	if (tidx &lt; pOutWidth &amp;&amp; tidy &lt; pOutHeight)	&#123;		int srcX = tidx * ((float)(pInWidth - 1) / (pOutWidth - 1));		int srcY = tidy * ((float)(pInHeight - 1) / (pOutHeight - 1));		int idx_in_y = srcY * pInWidth + srcX;		int idx_in_uv = srcY / 2 * pInWidth / 2 + srcX / 2;		int idx_out_y = tidy * pOutWidth + tidx;		int idx_out_uv = tidy / 2 * pOutWidth / 2 + tidx / 2;		// Y		pOutYData[idx_out_y] = pInYData[idx_in_y];		// U		pOutUData[idx_out_uv] = pInUData[idx_in_uv];		// V		pOutVData[idx_out_uv] = pInVData[idx_in_uv];	&#125;&#125;/// &lt;summary&gt;/// 修改大小 最近邻插值 YUV420P/// &lt;/summary&gt;/// &lt;param name=&quot;frame&quot;&gt;输入图像&lt;/param&gt;/// &lt;param name=&quot;width&quot;&gt;修改宽度&lt;/param&gt;/// &lt;param name=&quot;height&quot;&gt;修改高度&lt;/param&gt;/// &lt;returns&gt;修改后图像&lt;/returns&gt;AVFrame* ReSize_Nearest_YUV420P(AVFrame* frame, int width, int height)&#123;	auto img_size_y = width * height * sizeof(unsigned char);	auto img_size_uv = (width / 2) * (height / 2) * sizeof(unsigned char);	AVFrame* dstImg;	unsigned char* outputY = nullptr;	unsigned char* outputU = nullptr;	unsigned char* outputV = nullptr;	dstImg = av_frame_alloc();	av_image_alloc(dstImg-&gt;data, dstImg-&gt;linesize, width, height, (AVPixelFormat)frame-&gt;format, 1);	dstImg-&gt;width = width;	dstImg-&gt;height = height;	dstImg-&gt;format = (AVPixelFormat)frame-&gt;format;	cudaMalloc(&amp;outputY, img_size_y);	cudaMalloc(&amp;outputU, img_size_uv);	cudaMalloc(&amp;outputV, img_size_uv);	dim3 block(32, 32);	dim3 grid((width + block.x - 1) / block.x, (height + block.y - 1) / block.y);	ReSizeKernel_Nearest_YUV420P &lt;&lt; &lt;grid, block &gt;&gt; &gt; (frame-&gt;data[0], frame-&gt;data[1], frame-&gt;data[2], frame-&gt;width, frame-&gt;height, outputY, outputU, outputV, width, height);	cudaThreadSynchronize();	// 图像从 Gpu 拷贝到 Cpu	cudaMemcpy(dstImg-&gt;data[0], outputY, img_size_y, cudaMemcpyDeviceToHost);	cudaMemcpy(dstImg-&gt;data[1], outputU, img_size_uv, cudaMemcpyDeviceToHost);	cudaMemcpy(dstImg-&gt;data[2], outputV, img_size_uv, cudaMemcpyDeviceToHost);	return dstImg;&#125;/// &lt;summary&gt;/// 缩放图像核函数 NV12/// 最近邻插值/// &lt;/summary&gt;/// &lt;param name=&quot;pInYData&quot;&gt;输入图片 YUV NV12 Y&lt;/param&gt;/// &lt;param name=&quot;pInUVData&quot;&gt;输入图片 YUV NV12 UV&lt;/param&gt;/// &lt;param name=&quot;pInWidth&quot;&gt;输入图片宽度&lt;/param&gt;/// &lt;param name=&quot;pInHeight&quot;&gt;输入图像高度&lt;/param&gt;/// &lt;param name=&quot;pOutYData&quot;&gt;输出图片 YUV NV12 Y&lt;/param&gt;/// &lt;param name=&quot;pOutUVData&quot;&gt;输出图片 YUV NV12 UV&lt;/param&gt;/// &lt;param name=&quot;pOutWidth&quot;&gt;输出图片宽度&lt;/param&gt;/// &lt;param name=&quot;pOutHeight&quot;&gt;输出图像高度&lt;/param&gt;/// &lt;returns&gt;缩放后图像&lt;/returns&gt;__global__ void ReSizeKernel_Nearest_NV12(unsigned char* pInYData, unsigned char* pInUVData, int pInWidth, int pInHeight,	unsigned char* pOutYData, unsigned char* pOutUVData, int pOutWidth, int pOutHeight)&#123;	int tidx = threadIdx.x + blockDim.x * blockIdx.x;	int tidy = threadIdx.y + blockDim.y * blockIdx.y;	if (tidx &lt; pOutWidth &amp;&amp; tidy &lt; pOutHeight)	&#123;		int srcX = tidx * ((float)(pInWidth - 1) / (pOutWidth - 1));		int srcY = tidy * ((float)(pInHeight - 1) / (pOutHeight - 1));		int idx_in_y = srcY * pInWidth + srcX;		int idx_in_uv = srcY / 2 * pInWidth + srcX;		int idx_out_y = tidy * pOutWidth + tidx;		int idx_out_uv = tidy / 2 * pOutWidth + tidx;		// Y		pOutYData[idx_out_y] = pInYData[idx_in_y];		// U		pOutUVData[tidx % 2 == 0 ? idx_out_uv : idx_out_uv - 1] = pInUVData[srcX % 2 == 0 ? idx_in_uv : idx_in_uv - 1];		// V		pOutUVData[tidx % 2 == 0 ? idx_out_uv + 1 : idx_out_uv] = pInUVData[srcX % 2 == 0 ? idx_in_uv + 1 : idx_in_uv];	&#125;&#125;/// &lt;summary&gt;/// 修改大小 最近邻插值 NV12/// &lt;/summary&gt;/// &lt;param name=&quot;frame&quot;&gt;输入图像&lt;/param&gt;/// &lt;param name=&quot;width&quot;&gt;修改宽度&lt;/param&gt;/// &lt;param name=&quot;height&quot;&gt;修改高度&lt;/param&gt;/// &lt;returns&gt;修改后图像&lt;/returns&gt;AVFrame* ReSize_Nearest_NV12(AVFrame* frame, int width, int height)&#123;	auto img_size_y = width * height * sizeof(unsigned char);	auto img_size_uv = width * (height / 2) * sizeof(unsigned char);	AVFrame* dstImg;	unsigned char* outputY = nullptr;	unsigned char* outputUV = nullptr;	dstImg = av_frame_alloc();	av_image_alloc(dstImg-&gt;data, dstImg-&gt;linesize, width, height, (AVPixelFormat)frame-&gt;format, 1);	dstImg-&gt;width = width;	dstImg-&gt;height = height;	dstImg-&gt;format = (AVPixelFormat)frame-&gt;format;	cudaMalloc(&amp;outputY, img_size_y);	cudaMalloc(&amp;outputUV, img_size_uv);	dim3 block(32, 32);	dim3 grid((width + block.x - 1) / block.x, (height + block.y - 1) / block.y);	ReSizeKernel_Nearest_NV12 &lt;&lt; &lt;grid, block &gt;&gt; &gt; (frame-&gt;data[0], frame-&gt;data[1], frame-&gt;width, frame-&gt;height, outputY, outputUV, width, height);	cudaThreadSynchronize();	// 图像从 Gpu 拷贝到 Cpu	cudaMemcpy(dstImg-&gt;data[0], outputY, img_size_y, cudaMemcpyDeviceToHost);	cudaMemcpy(dstImg-&gt;data[1], outputUV, img_size_uv, cudaMemcpyDeviceToHost);	return dstImg;&#125;

双线性差值法计算方法与最近邻插值法一样，先计算图片缩放百分比，得到一个在原图像的百分比坐标吗，用当前坐标乘以百分比获取原图像像素值，通常为小数，取小数相邻的两个像素，比如计算像素坐标为 7.5，则取删除小数的 7 和填充小数的 8 作为相邻的两个值，放在图像坐标中上下左右相邻四个像素作为计算数据。

获取在原图像的百分比像素，由于数据数组通常以 0 开始，宽度高度减 1 后计算更精准。
 float fx = outX * ((float)(inWidth - 1) / (outWidth - 1));float fy = outY * ((float)(inHeight - 1) / (outHeight - 1));

取相邻四个像素坐标，直接取整为左上角坐标，如果还有余数的情况下 +1 为右下角坐标。
 int fx0 = fx;int fy0 = fy;int fx1 = fx &gt; fx0 ? fx0 + 1 : fx0;int fy1 = fy &gt; fy0 ? fy0 + 1 : fy0;

取小数部分作为四个像素计算的分量
 float xProportion = fx - fx0;float yProportion = fy - fy0;

带入公式计算新像素值
 f(x,y) = f(0,0)(1-x)(1-y) + f(1,0)x(1-y) + f(0,1)(1-x)y + f(1,1)xy;

代码/// &lt;summary&gt;/// 缩放图像核函数 YUV420P/// 双线性差值/// f(x,y) = f(0,0)(1-x)(1-y) + f(1,0)x(1-y) + f(0,1)(1-x)y + f(1,1)xy;/// &lt;/summary&gt;/// &lt;param name=&quot;pInYData&quot;&gt;输入图片 YUV YUV420P Y&lt;/param&gt;/// &lt;param name=&quot;pInUData&quot;&gt;输入图片 YUV YUV420P U&lt;/param&gt;/// &lt;param name=&quot;pInVData&quot;&gt;输入图片 YUV YUV420P V&lt;/param&gt;/// &lt;param name=&quot;pInWidth&quot;&gt;输入图片宽度&lt;/param&gt;/// &lt;param name=&quot;pInHeight&quot;&gt;输入图像高度&lt;/param&gt;/// &lt;param name=&quot;pOutYData&quot;&gt;输出图片 YUV YUV420P Y&lt;/param&gt;/// &lt;param name=&quot;pOutUData&quot;&gt;输出图片 YUV YUV420P U&lt;/param&gt;/// &lt;param name=&quot;pOutVData&quot;&gt;输出图片 YUV YUV420P V&lt;/param&gt;/// &lt;param name=&quot;pOutWidth&quot;&gt;输出图片宽度&lt;/param&gt;/// &lt;param name=&quot;pOutHeight&quot;&gt;输出图像高度&lt;/param&gt;/// &lt;returns&gt;缩放后图像&lt;/returns&gt;__global__ void ReSizeKernel_Bilinear_YUV420P(unsigned char* pInYData, unsigned char* pInUData, unsigned char* pInVData, int pInWidth, int pInHeight,	unsigned char* pOutYData, unsigned char* pOutUData, unsigned char* pOutVData, int pOutWidth, int pOutHeight)&#123;	int tidx = threadIdx.x + blockDim.x * blockIdx.x;	int tidy = threadIdx.y + blockDim.y * blockIdx.y;	if (tidx &lt; pOutWidth&amp;&amp; tidy &lt; pOutHeight)	&#123;		float srcX = tidx * ((float)(pInWidth - 1) / (pOutWidth - 1));		float srcY = tidy * ((float)(pInHeight - 1) / (pOutHeight - 1));		// 计算取图像坐标		int fx0 = srcX;		int fy0 = srcY;		int fx1 = srcX &gt; fx0 ? fx0 + 1 : fx0;		int fy1 = srcY &gt; fy0 ? fy0 + 1 : fy0;		// 计算取像素比例		float xProportion = srcX - fx0;		float yProportion = srcY - fy0;		// 四个输入坐标		int idx_in_y_00 = fy0 * pInWidth + fx0;		int idx_in_uv_00 = fy0 / 2 * pInWidth / 2 + fx0 / 2;		int idx_in_y_10 = fy1 * pInWidth + fx0;		int idx_in_uv_10 = fy1 / 2 * pInWidth / 2 + fx0 / 2;		int idx_in_y_01 = fy0 * pInWidth + fx1;		int idx_in_uv_01 = fy0 / 2 * pInWidth / 2 + fx1 / 2;		int idx_in_y_11 = fy1 * pInWidth + fx1;		int idx_in_uv_11 = fy1 / 2 * pInWidth / 2 + fx1 / 2;		// 输出坐标		int idx_out_y = tidy * pOutWidth + tidx;		int idx_out_uv = tidy / 2 * pOutWidth / 2 + tidx / 2;		// Y		pOutYData[idx_out_y] =			pInYData[idx_in_y_00] * (1 - xProportion) * (1 - yProportion) +			pInYData[idx_in_y_10] * xProportion * (1 - yProportion) +			pInYData[idx_in_y_01] * (1 - xProportion) * yProportion +			pInYData[idx_in_y_11] * xProportion * yProportion;		// U		pOutUData[idx_out_uv] =			pInUData[idx_in_uv_00] * (1 - xProportion) * (1 - yProportion) +			pInUData[idx_in_uv_10] * xProportion * (1 - yProportion) +			pInUData[idx_in_uv_01] * (1 - xProportion) * yProportion +			pInUData[idx_in_uv_11] * xProportion * yProportion;		// V		pOutVData[idx_out_uv] =			pInVData[idx_in_uv_00] * (1 - xProportion) * (1 - yProportion) +			pInVData[idx_in_uv_10] * xProportion * (1 - yProportion) +			pInVData[idx_in_uv_01] * (1 - xProportion) * yProportion +			pInVData[idx_in_uv_11] * xProportion * yProportion;	&#125;&#125;/// &lt;summary&gt;/// 修改大小 双线性差值 YUV420P/// &lt;/summary&gt;/// &lt;param name=&quot;frame&quot;&gt;输入图像&lt;/param&gt;/// &lt;param name=&quot;width&quot;&gt;修改宽度&lt;/param&gt;/// &lt;param name=&quot;height&quot;&gt;修改高度&lt;/param&gt;/// &lt;returns&gt;修改后图像&lt;/returns&gt;AVFrame* ReSize_Bilinear_YUV420P(AVFrame* frame, int width, int height)&#123;	auto img_size_y = width * height * sizeof(unsigned char);	auto img_size_uv = (width / 2) * (height / 2) * sizeof(unsigned char);	AVFrame* dstImg;	unsigned char* outputY = nullptr;	unsigned char* outputU = nullptr;	unsigned char* outputV = nullptr;	dstImg = av_frame_alloc();	av_image_alloc(dstImg-&gt;data, dstImg-&gt;linesize, width, height, (AVPixelFormat)frame-&gt;format, 1);	dstImg-&gt;width = width;	dstImg-&gt;height = height;	dstImg-&gt;format = (AVPixelFormat)frame-&gt;format;	cudaMalloc(&amp;outputY, img_size_y);	cudaMalloc(&amp;outputU, img_size_uv);	cudaMalloc(&amp;outputV, img_size_uv);	dim3 block(32, 32);	dim3 grid((width + block.x - 1) / block.x, (height + block.y - 1) / block.y);	ReSizeKernel_Bilinear_YUV420P &lt;&lt; &lt;grid, block &gt;&gt; &gt; (frame-&gt;data[0], frame-&gt;data[1], frame-&gt;data[2], frame-&gt;width, frame-&gt;height, outputY, outputU, outputV, width, height);	cudaThreadSynchronize();	// 图像从 Gpu 拷贝到 Cpu	cudaMemcpy(dstImg-&gt;data[0], outputY, img_size_y, cudaMemcpyDeviceToHost);	cudaMemcpy(dstImg-&gt;data[1], outputU, img_size_uv, cudaMemcpyDeviceToHost);	cudaMemcpy(dstImg-&gt;data[2], outputV, img_size_uv, cudaMemcpyDeviceToHost);	return dstImg;&#125;/// &lt;summary&gt;/// 缩放图像核函数 NV12/// 双线性差值/// f(x,y) = f(0,0)(1-x)(1-y) + f(1,0)x(1-y) + f(0,1)(1-x)y + f(1,1)xy;/// &lt;/summary&gt;/// &lt;param name=&quot;pInYData&quot;&gt;输入图片 YUV NV12 Y&lt;/param&gt;/// &lt;param name=&quot;pInUVData&quot;&gt;输入图片 YUV NV12 UV&lt;/param&gt;/// &lt;param name=&quot;pInWidth&quot;&gt;输入图片宽度&lt;/param&gt;/// &lt;param name=&quot;pInHeight&quot;&gt;输入图像高度&lt;/param&gt;/// &lt;param name=&quot;pOutYData&quot;&gt;输出图片 YUV NV12 Y&lt;/param&gt;/// &lt;param name=&quot;pOutUVData&quot;&gt;输出图片 YUV NV12 UV&lt;/param&gt;/// &lt;param name=&quot;pOutWidth&quot;&gt;输出图片宽度&lt;/param&gt;/// &lt;param name=&quot;pOutHeight&quot;&gt;输出图像高度&lt;/param&gt;/// &lt;returns&gt;缩放后图像&lt;/returns&gt;__global__ void ReSizeKernel_Bilinear_NV12(unsigned char* pInYData, unsigned char* pInUVData, int pInWidth, int pInHeight,	unsigned char* pOutYData, unsigned char* pOutUVData, int pOutWidth, int pOutHeight)&#123;	int tidx = threadIdx.x + blockDim.x * blockIdx.x;	int tidy = threadIdx.y + blockDim.y * blockIdx.y;	if (tidx &lt; pOutWidth&amp;&amp; tidy &lt; pOutHeight)	&#123;		float srcX = tidx * ((float)(pInWidth - 1) / (pOutWidth - 1));		float srcY = tidy * ((float)(pInHeight - 1) / (pOutHeight - 1));		// 计算取图像坐标		int fx0 = srcX;		int fy0 = srcY;		int fx1 = srcX &gt; fx0 ? fx0 + 1 : fx0;		int fy1 = srcY &gt; fy0 ? fy0 + 1 : fy0;		// 计算取像素比例		float xProportion = srcX - fx0;		float yProportion = srcY - fy0;		// 四个输入坐标		int idx_in_y_00 = fy0 * pInWidth + fx0;		int idx_in_uv_00 = fy0 / 2 * pInWidth + fx0;		int idx_in_y_10 = fy1 * pInWidth + fx0;		int idx_in_uv_10 = fy1 / 2 * pInWidth + fx0;		int idx_in_y_01 = fy0 * pInWidth + fx1;		int idx_in_uv_01 = fy0 / 2 * pInWidth + fx1;		int idx_in_y_11 = fy1 * pInWidth + fx1;		int idx_in_uv_11 = fy1 / 2 * pInWidth + fx1;		// 输出坐标		int idx_out_y = tidy * pOutWidth + tidx;		int idx_out_uv = tidy / 2 * pOutWidth + tidx;		// Y		pOutYData[idx_out_y] =			pInYData[idx_in_y_00] * (1 - xProportion) * (1 - yProportion) +			pInYData[idx_in_y_10] * xProportion * (1 - yProportion) +			pInYData[idx_in_y_01] * (1 - xProportion) * yProportion +			pInYData[idx_in_y_11] * xProportion * yProportion;		// U		pOutUVData[tidx % 2 == 0 ? idx_out_uv : idx_out_uv - 1] =			pInUVData[fx0 % 2 == 0 ? idx_in_uv_00 : idx_in_uv_00 - 1] * (1 - xProportion) * (1 - yProportion) +			pInUVData[fx0 % 2 == 0 ? idx_in_uv_10 : idx_in_uv_10 - 1] * xProportion * (1 - yProportion) +			pInUVData[fx1 % 2 == 0 ? idx_in_uv_01 : idx_in_uv_01 - 1] * (1 - xProportion) * yProportion +			pInUVData[fx1 % 2 == 0 ? idx_in_uv_11 : idx_in_uv_11 - 1] * xProportion * yProportion;		// V		pOutUVData[tidx % 2 == 0 ? idx_out_uv + 1 : idx_out_uv] =			pInUVData[fx0 % 2 == 0 ? idx_in_uv_00 + 1 : idx_in_uv_00] * (1 - xProportion) * (1 - yProportion) +			pInUVData[fx0 % 2 == 0 ? idx_in_uv_10 + 1 : idx_in_uv_10] * xProportion * (1 - yProportion) +			pInUVData[fx1 % 2 == 0 ? idx_in_uv_01 + 1 : idx_in_uv_01] * (1 - xProportion) * yProportion +			pInUVData[fx1 % 2 == 0 ? idx_in_uv_11 + 1 : idx_in_uv_11] * xProportion * yProportion;	&#125;&#125;/// &lt;summary&gt;/// 修改大小 双线性差值 NV12/// &lt;/summary&gt;/// &lt;param name=&quot;frame&quot;&gt;输入图像&lt;/param&gt;/// &lt;param name=&quot;width&quot;&gt;修改宽度&lt;/param&gt;/// &lt;param name=&quot;height&quot;&gt;修改高度&lt;/param&gt;/// &lt;returns&gt;修改后图像&lt;/returns&gt;AVFrame* ReSize_Bilinear_NV12(AVFrame* frame, int width, int height)&#123;	auto img_size_y = width * height * sizeof(unsigned char);	auto img_size_uv = width * (height / 2) * sizeof(unsigned char);	AVFrame* dstImg;	unsigned char* outputY = nullptr;	unsigned char* outputUV = nullptr;	dstImg = av_frame_alloc();	av_image_alloc(dstImg-&gt;data, dstImg-&gt;linesize, width, height, (AVPixelFormat)frame-&gt;format, 1);	dstImg-&gt;width = width;	dstImg-&gt;height = height;	dstImg-&gt;format = (AVPixelFormat)frame-&gt;format;	cudaMalloc(&amp;outputY, img_size_y);	cudaMalloc(&amp;outputUV, img_size_uv);	dim3 block(32, 32);	dim3 grid((width + block.x - 1) / block.x, (height + block.y - 1) / block.y);	ReSizeKernel_Bilinear_NV12 &lt;&lt; &lt;grid, block &gt;&gt; &gt; (frame-&gt;data[0], frame-&gt;data[1], frame-&gt;width, frame-&gt;height, outputY, outputUV, width, height);	cudaThreadSynchronize();	// 图像从 Gpu 拷贝到 Cpu	cudaMemcpy(dstImg-&gt;data[0], outputY, img_size_y, cudaMemcpyDeviceToHost);	cudaMemcpy(dstImg-&gt;data[1], outputUV, img_size_uv, cudaMemcpyDeviceToHost);	return dstImg;&#125;

外部调用方法/// &lt;summary&gt;/// 修改图像大小/// &lt;/summary&gt;/// &lt;param name=&quot;frame&quot;&gt;输入图像&lt;/param&gt;/// &lt;param name=&quot;width&quot;&gt;修改宽度&lt;/param&gt;/// &lt;param name=&quot;height&quot;&gt;修改高度&lt;/param&gt;/// &lt;param name=&quot;type&quot;&gt;0:最近邻插值 1:双线性差值&lt;/param&gt;/// &lt;returns&gt;修改后图像&lt;/returns&gt;extern &quot;C&quot; AVFrame * ReSize(AVFrame * frame, int width, int height, int type)&#123;	AVFrame* outFrame;	switch (frame-&gt;format)	&#123;	case AV_PIX_FMT_YUV420P:		if (type == 0)		&#123;			outFrame = ReSize_Nearest_YUV420P(frame, width, height);		&#125;		else if (type == 1)		&#123;			outFrame = ReSize_Bilinear_YUV420P(frame, width, height);		&#125;		break;	case AV_PIX_FMT_NV12:		if (type == 0)		&#123;			outFrame = ReSize_Nearest_NV12(frame, width, height);		&#125;		else if (type == 1)		&#123;			outFrame = ReSize_Bilinear_NV12(frame, width, height);		&#125;		break;	default:		break;	&#125;	return outFrame;&#125;

使用 NVIDIA 管理库 NVML 获取 GPU 利用率
简介NVIDIA Management Library (NVML) 随 CUDA 一起发布，是一个基于 C 代码的 API，用于兼用和管理 NVIDIA GPU 设备的各种状态。简单的使用获取显示显卡利用率。
代码命令行:: 查询显卡使用情况信息nvidia-smi:: 查询可用设备nvidia-smi -L

C++#include &quot;nvml.h&quot;#pragma comment(lib,&quot;nvml.lib&quot;)int main()&#123;	nvmlReturn_t result;	unsigned int device_count, i;	// First initialize NVML library	result = nvmlInit();	result = nvmlDeviceGetCount(&amp;device_count);	if (NVML_SUCCESS != result)	&#123;		std::cout &lt;&lt; &quot;Failed to query device count: &quot; &lt;&lt; nvmlErrorString(result);	&#125;	std::cout &lt;&lt; &quot;Found&quot; &lt;&lt; device_count &lt;&lt; &quot; device&quot; &lt;&lt; endl;	std::cout &lt;&lt; &quot;Listing devices:&quot;;	while (true)	&#123;		for (i = 0; i &lt; device_count; i++)		&#123;			nvmlDevice_t device;			result = nvmlDeviceGetHandleByIndex(i, &amp;device);			if (NVML_SUCCESS != result) &#123;				std::cout &lt;&lt; &quot;get device failed &quot; &lt;&lt; endl;				continue;			&#125;			char name[NVML_DEVICE_NAME_BUFFER_SIZE];			result = nvmlDeviceGetName(device, name, NVML_DEVICE_NAME_BUFFER_SIZE);			if (NVML_SUCCESS == result) &#123;				std::cout &lt;&lt; &quot;GPU name： &quot; &lt;&lt; name &lt;&lt; endl;			&#125;			char uuid[NVML_DEVICE_UUID_BUFFER_SIZE];			result = nvmlDeviceGetUUID(device, uuid, NVML_DEVICE_UUID_BUFFER_SIZE);			if (NVML_SUCCESS == result) &#123;				std::cout &lt;&lt; &quot;GPU uuid： &quot; &lt;&lt; uuid &lt;&lt; endl;			&#125;			//使用率			nvmlUtilization_t utilization;			result = nvmlDeviceGetUtilizationRates(device, &amp;utilization);			if (NVML_SUCCESS == result)			&#123;				std::cout &lt;&lt; &quot;----- 使用率 ----- &quot; &lt;&lt; endl;				std::cout &lt;&lt; &quot;GPU 使用率： &quot; &lt;&lt; utilization.gpu &lt;&lt; endl;				std::cout &lt;&lt; &quot;显存使用率 &quot; &lt;&lt; utilization.memory &lt;&lt; endl;			&#125;		&#125;		Sleep(1000);	&#125;	return 0;&#125;

C#使用 C# 调用 NVML 需要额外封装 nvml.dll 库。参考 nvml-csharp 库封装一个简单的帮助类，仅用于获取 GPU 与显存使用率。
/// &lt;summary&gt;/// 显卡利用率统计/// &lt;/summary&gt;public class NvmlStateHelper&#123;    /// &lt;summary&gt;    /// NVML 库名称    /// &lt;/summary&gt;    const string NVML_SHARED_LIBRARY_STRING = &quot;nvml.dll&quot;;    /// &lt;summary&gt;    /// Buffer size guaranteed to be large enough for \ref nvmlDeviceGetName    /// &lt;/summary&gt;    const int NVML_DEVICE_NAME_BUFFER_SIZE = 64;    /// &lt;summary&gt;    /// Buffer size guaranteed to be large enough for \ref nvmlDeviceGetUUID    /// &lt;/summary&gt;    const int NVML_DEVICE_UUID_BUFFER_SIZE = 80;    /// &lt;summary&gt;    /// 初始化 NVML 库    /// &lt;/summary&gt;    /// &lt;returns&gt;&lt;/returns&gt;    [DllImport(NVML_SHARED_LIBRARY_STRING, EntryPoint = &quot;nvmlInit_v2&quot;)]    internal static extern NvmlReturn NvmlInitV2();    /// &lt;summary&gt;    /// 获取显卡数量    /// &lt;/summary&gt;    /// &lt;param name=&quot;deviceCount&quot;&gt;&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    [DllImport(NVML_SHARED_LIBRARY_STRING, CharSet = CharSet.Ansi, EntryPoint = &quot;nvmlDeviceGetCount_v2&quot;)]    internal static extern NvmlReturn NvmlDeviceGetCount_v2(out uint deviceCount);    /// &lt;summary&gt;    /// 获取显卡句柄    /// &lt;/summary&gt;    /// &lt;param name=&quot;index&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;device&quot;&gt;&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    [DllImport(NVML_SHARED_LIBRARY_STRING, EntryPoint = &quot;nvmlDeviceGetHandleByIndex&quot;)]    internal static extern NvmlReturn NvmlDeviceGetHandleByIndex(uint index, out IntPtr device);    /// &lt;summary&gt;    /// 获取显卡名称    /// &lt;/summary&gt;    /// &lt;param name=&quot;device&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;name&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;length&quot;&gt;&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    [DllImport(NVML_SHARED_LIBRARY_STRING, CharSet = CharSet.Ansi, EntryPoint = &quot;nvmlDeviceGetName&quot;)]    internal static extern NvmlReturn NvmlDeviceGetName(IntPtr device, [Out, MarshalAs(UnmanagedType.LPArray)] byte[] name, uint length);    /// &lt;summary&gt;    /// 获取显卡 UUID    /// &lt;/summary&gt;    /// &lt;param name=&quot;device&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;uuid&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;length&quot;&gt;&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    [DllImport(NVML_SHARED_LIBRARY_STRING, CharSet = CharSet.Ansi, EntryPoint = &quot;nvmlDeviceGetUUID&quot;)]    internal static extern NvmlReturn NvmlDeviceGetUUID(IntPtr device, [Out, MarshalAs(UnmanagedType.LPArray)] byte[] uuid, uint length);    /// &lt;summary&gt;    /// 获取显卡使用率信息    /// &lt;/summary&gt;    /// &lt;param name=&quot;device&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;utilization&quot;&gt;&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    [DllImport(NVML_SHARED_LIBRARY_STRING, CharSet = CharSet.Ansi, EntryPoint = &quot;nvmlDeviceGetUtilizationRates&quot;)]    internal static extern NvmlReturn NvmlDeviceGetUtilizationRates(IntPtr device, out NvmlUtilization utilization);    /// &lt;summary&gt;    /// 关闭调用    /// &lt;/summary&gt;    /// &lt;returns&gt;&lt;/returns&gt;    [DllImport(NVML_SHARED_LIBRARY_STRING, EntryPoint = &quot;nvmlShutdown&quot;)]    internal static extern NvmlReturn NvmlShutdown();    /// &lt;summary&gt;    /// 获取显卡全局使用率    /// &lt;/summary&gt;    /// &lt;param name=&quot;gpuCount&quot;&gt;&lt;/param&gt;    /// &lt;exception cref=&quot;SystemException&quot;&gt;&lt;/exception&gt;    public NvmlStateHelper(uint gpuCount = 0)    &#123;        Task.Run(() =&gt;        &#123;            NvmlReturn res = NvmlInitV2();            if (NvmlReturn.NVML_SUCCESS != res)            &#123;                //throw new SystemException(res.ToString());                return;            &#125;            var device = IntPtr.Zero;            res = NvmlDeviceGetHandleByIndex(gpuCount, out device);            if (NvmlReturn.NVML_SUCCESS != res)            &#123;                //throw new SystemException(res.ToString());                return;            &#125;            // 获取显卡名称            byte[] bufferName = new byte[NVML_DEVICE_NAME_BUFFER_SIZE];            res = NvmlDeviceGetName(device, bufferName, NVML_DEVICE_NAME_BUFFER_SIZE);            if (NvmlReturn.NVML_SUCCESS == res)            &#123;                var gpuName = Encoding.Default.GetString(bufferName).Replace(&quot;\0&quot;, &quot;&quot;);            &#125;            // 获取显卡 UUID            byte[] bufferUUID = new byte[NVML_DEVICE_UUID_BUFFER_SIZE];            res = NvmlDeviceGetUUID(device, bufferUUID, NVML_DEVICE_UUID_BUFFER_SIZE);            if (NvmlReturn.NVML_SUCCESS == res)            &#123;                var gpuUUID = Encoding.Default.GetString(bufferUUID).Replace(&quot;\0&quot;, &quot;&quot;);            &#125;            // 获取 GPU 与显存使用率            while (true)            &#123;                try                &#123;                    NvmlUtilization nvmlUtilization;                    res = NvmlDeviceGetUtilizationRates(device, out nvmlUtilization);                    if (NvmlReturn.NVML_SUCCESS != res)                    &#123;                        //throw new SystemException(res.ToString());                        return;                    &#125;                    GpuChange?.Invoke(nvmlUtilization.gpu);                    MemoryChange?.Invoke(nvmlUtilization.memory);                &#125;                catch (Exception)                &#123;                    // 获取信息失败                &#125;                Thread.Sleep(1000);            &#125;        &#125;);    &#125;    /// &lt;summary&gt;    /// Gpu 使用率    /// &lt;/summary&gt;    public event Action&lt;uint&gt; GpuChange;    /// &lt;summary&gt;    /// 显存使用率    /// &lt;/summary&gt;    public event Action&lt;uint&gt; MemoryChange;&#125;/// &lt;summary&gt;/// NVML 返回值类型/// &lt;/summary&gt;public enum NvmlReturn&#123;    NVML_SUCCESS = 0,    NVML_ERROR_UNINITIALIZED,    NVML_ERROR_INVALID_ARGUMENT,    NVML_ERROR_NOT_SUPPORTED,    NVML_ERROR_NO_PERMISSION,    NVML_ERROR_ALREADY_INITIALIZED,    NVML_ERROR_NOT_FOUND,    NVML_ERROR_INSUFFICIENT_SIZE,    NVML_ERROR_INSUFFICIENT_POWER,    NVML_ERROR_DRIVER_NOT_LOADED,    NVML_ERROR_TIMEOUT,    NVML_ERROR_IRQ_ISSUE,    NVML_ERROR_LIBRARY_NOT_FOUND,    NVML_ERROR_FUNCTION_NOT_FOUND,    NVML_ERROR_CORRUPTED_INFOROM,    NVML_ERROR_GPU_IS_LOST,    NVML_ERROR_RESET_REQUIRED,    NVML_ERROR_OPERATING_SYSTEM,    NVML_ERROR_LIB_RM_VERSION_MISMATCH,    NVML_ERROR_IN_USE,    NVML_ERROR_MEMORY,    NVML_ERROR_NO_DATA,    NVML_ERROR_VGPU_ECC_NOT_SUPPORTED,    NVML_ERROR_INSUFFICIENT_RESOURCES,    NVML_ERROR_UNKNOWN = 999&#125;/// &lt;summary&gt;/// 显卡使用率信息模型/// &lt;/summary&gt;public struct NvmlUtilization&#123;    public uint gpu &#123; get; &#125;    public uint memory &#123; get; &#125;&#125;

使用C++开发算法（全景拼接、人脸识别、超分辨率重建）&#x2F;使用C#开发服务端业务逻辑和UI
简介现工作中作由于 C++ 的 UI（MFC、QT）开发界面比较难看，定制用户控件复杂且样式一般。而 C# 又不擅长于开发算法逻辑，效率不如 C++。所以现在大部分公司都会选用 C#&#x2F;C++ 混合编程。
性能分析使用 C# 做界面要比 C++ 高效的多，但是存在算法逻辑的时候由于性能问题不得不把部分模块交给 C++ 处理，C++ 可以使用高效的栈内存对象（CCalc），而 C# 所有对象只能放在托管堆中。测试 C# 调用 C++ 类库使用托管方式性能得到了一定程度的提升，但比起单纯的 C++ 项目，还是差了很多；测试 C# 调用 C++ 类库使用 DllImport Attribute 混合方式由非托管动态链接库效率与单独运行 C++ 相差无几。
