使用 ADO.NET 二次封装ORM框架的数据库操作帮助类简介工作中大量需要多种不同数据格式互相转换，通过ADO.NET实现可视化数据转换工具，目前支持关系型数据库SqlServer、Oracle、MySql、Access、SQLite。
设计简易的ORM框架，多种数据库操作封装为一套帮助类中，后期使用不需要过多考虑数据库类型，以及减少在代码中拼写SQL语句。近乎通用的连接方式以及增删改查，支持事务处理。
帮助类、官方文档及其调用方式SQLServer：SqlServerHelper 引用 System.Data.SqlClient 库调用方式：
SqlServerHelper sqlHelper = new SqlServerHelper();sqlHelper.SqlServerConnectionString(string server, string database, string uid, string pwd);sqlHelper.Open();sqlHelper.Close();

Oracle：OracleHelper 引用 System.Data.OracleClient 库调用方式：
OracleHelper sqlHelper = new OracleHelper();sqlHelper.OracleConnectionString(string Source, string Id, string Password);sqlHelper.Open();sqlHelper.Close();

MySQL：MySqlHelper 引用 MySql.Data.MySqlClient 库调用方式：
MySqlHelper sqlHelper = new MySqlHelper();sqlHelper.MySqlConnectionString(string server, string id, string password, string database);sqlHelper.Open();sqlHelper.Close();

Access：AccessHelper 引用 System.Data.OleDb 库调用方式：
AccessHelper sqlHelper = new AccessHelper();sqlHelper.AccessConnectionPath_Office2003(string source);sqlHelper.AccessConnectionPath_Office2007(string source);sqlHelper.Open();sqlHelper.Close();

SQLite：SQLiteHelper 引用 System.Data.SQLite 库调用方式：
SQLiteHelper sqlHelper = new SQLiteHelper();sqlHelper.SQLiteConnectionPath(string source);sqlHelper.Open();sqlHelper.Close();

数据转换帮助类由于每种数据库的字段类型、字符格式长度等不一致，所以专门写了一个用于互相兼容的帮助类，用于自动识别源数据库与目标数据库差异，自动修改。数据转换帮助类
删除DataTable中的空行数据源以C#基础类型DataTable传递，在实际使用中存在空行导致异常
/// &lt;summary&gt;/// 删除DataTable中的空行/// 弱引用,可直接修改参数/// &lt;/summary&gt;/// &lt;param name=&quot;dtDataSource&quot;&gt;源数据(DataTable)&lt;/param&gt;/// &lt;returns&gt;删除空行后的DataTable&lt;/returns&gt;public static DataTable RemoveEmpty(DataTable dtDataSource)&#123;    try    &#123;        List&lt;DataRow&gt; listRemove = new List&lt;DataRow&gt;();        for (int i = 0; i &lt; dtDataSource.Rows.Count; i++)        &#123;            bool IsNull = true;            for (int j = 0; j &lt; dtDataSource.Columns.Count; j++)            &#123;                if (!string.IsNullOrEmpty(dtDataSource.Rows[i][j].ToString().Trim()))                &#123;                    IsNull = false;                &#125;            &#125;            if (IsNull)            &#123;                listRemove.Add(dtDataSource.Rows[i]);            &#125;        &#125;        for (int i = 0; i &lt; listRemove.Count; i++)        &#123;            dtDataSource.Rows.Remove(listRemove[i]);        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());    &#125;    return dtDataSource;&#125;

DataTable与List互相转换实际使用中List比DataTable更方便使用，提供互相转换方法方便开发
/// &lt;summary&gt;/// DataTable转换为List&lt;T&gt;/// &lt;/summary&gt;/// &lt;typeparam name=&quot;T&quot;&gt;数据模型&lt;/typeparam&gt;/// &lt;param name=&quot;dtDataSource&quot;&gt;源数据(DataTable)&lt;/param&gt;/// &lt;returns&gt;成功返回List&lt;T&gt;,失败返回null&lt;/returns&gt;public static List&lt;T&gt; ConvertToList&lt;T&gt;(DataTable dtDataSource) where T : class,new()&#123;    try    &#123;        List&lt;T&gt; listT = new List&lt;T&gt;();        foreach (DataRow drDataSource in dtDataSource.Rows)        &#123;            T t = new T();            PropertyInfo[] propertyInfos = t.GetType().GetProperties();            foreach (PropertyInfo propertyInfo in propertyInfos)            &#123;                string tempName = propertyInfo.Name;                if (dtDataSource.Columns.Contains(tempName))                &#123;                    if (!propertyInfo.CanWrite) continue;                    object value = drDataSource[tempName];                    if (value != DBNull.Value)                    &#123;                        if (propertyInfo.GetMethod.ReturnParameter.ParameterType.Name == &quot;Int32&quot;)                        &#123;                            value = Convert.ToInt32(value);                        &#125;                        propertyInfo.SetValue(t, value, null);                    &#125;                &#125;            &#125;            listT.Add(t);        &#125;        return listT;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());    &#125;    return null;&#125;

/// &lt;summary&gt;/// List&lt;T&gt;转换为DataTable/// &lt;/summary&gt;/// &lt;param name=&quot;listDataSource&quot;&gt;源数据&lt;/param&gt;/// &lt;returns&gt;成功返回DataTable,失败返回null&lt;/returns&gt;public static DataTable ConvertDataTable(IList listDataSource)&#123;    try    &#123;        DataTable dataTable = new DataTable();        if (listDataSource.Count &gt; 0)        &#123;            PropertyInfo[] propertyInfos = listDataSource[0].GetType().GetProperties();            foreach (PropertyInfo propertyInfo in propertyInfos)            &#123;                dataTable.Columns.Add(propertyInfo.Name, propertyInfo.PropertyType);            &#125;            foreach (var vDataSource in listDataSource)            &#123;                ArrayList arrayList = new ArrayList();                foreach (PropertyInfo propertyInfo in propertyInfos)                &#123;                    arrayList.Add(propertyInfo.GetValue(vDataSource, null));                &#125;                dataTable.LoadDataRow(arrayList.ToArray(), true);            &#125;        &#125;        return dataTable;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());    &#125;    return null;&#125;

String转Unicode,并去除’\ufeff’非法字符个别数据中存在有非法字符，避免异常，转换时批量处理
/// &lt;summary&gt;/// 去除非法字符&#x27;\\ufeff&#x27;/// &lt;/summary&gt;/// &lt;param name=&quot;strSource&quot;&gt;数据源&lt;/param&gt;/// &lt;returns&gt;修正后的字符&lt;/returns&gt;public static string RemoveIllegal(string strSource)&#123;    return UnicodeToString(StringToUnicode(strSource));&#125;/// &lt;summary&gt;/// String转Unicode,并去除&#x27;\\ufeff&#x27;非法字符/// &lt;/summary&gt;/// &lt;param name=&quot;strSource&quot;&gt;数据源&lt;/param&gt;/// &lt;returns&gt;Unicode编码字符&lt;/returns&gt;public static string StringToUnicode(string strSource)&#123;    StringBuilder stringBuilder = new StringBuilder();    //先把字符串转换成 UTF-16 的Btye数组    byte[] bytes = Encoding.Unicode.GetBytes(strSource);    for (int i = 0; i &lt; bytes.Length; i += 2)    &#123;        //根据Unicode规则，每两个byte表示一个汉字，并且后前顺序，英文前面补00        stringBuilder.AppendFormat(&quot;\\u&#123;0&#125;&#123;1&#125;&quot;, bytes[i + 1].ToString(&quot;x&quot;).PadLeft(2, &#x27;0&#x27;), bytes[i].ToString(&quot;x&quot;).PadLeft(2, &#x27;0&#x27;));    &#125;    //去掉&#x27;?&#x27;的Unicode码,?=003f,Unicode以\u开头,\\为转义\    return stringBuilder.Replace(&quot;\\ufeff&quot;, string.Empty).ToString();&#125;/// &lt;summary&gt;/// Unicode转String/// &lt;/summary&gt;/// &lt;param name=&quot;strSource&quot;&gt;数据源&lt;/param&gt;/// &lt;returns&gt;String类型编码字符&lt;/returns&gt;public static string UnicodeToString(string strSource)&#123;    return new Regex(@&quot;\\u([0-9A-F]&#123;4&#125;)&quot;, RegexOptions.IgnoreCase | RegexOptions.Compiled).Replace(strSource, x =&gt; string.Empty + Convert.ToChar(Convert.ToUInt16(x.Result(&quot;$1&quot;), 16)));&#125;

