ActiveMQ 消息队列帮助类使用介绍
简介ActiveMQ Demo 写了关于 ActiveMQ 的基础介绍与官方提供的最简生产者与消费者的 Demo，完善代码封装为帮助类。
核心代码ActiveMQHelper
/// &lt;summary&gt;/// ActiveMQ 消息队列帮助类/// 创建日期:2023年10月26日/// &lt;/summary&gt;public class ActiveMQHelper&#123;    IConnectionFactory _factory;    // 消费者    IConnection _connection_producer;    ISession _session_producer;    IMessageProducer _prod;    // 生产者    IConnection _connection_consumer;    ISession _session_consumer;    /// &lt;summary&gt;    /// 消息回调    /// &lt;/summary&gt;    public event Action&lt;string&gt; MessageCallback;    /// &lt;summary&gt;    /// 构造函数    /// &lt;/summary&gt;    /// &lt;param name=&quot;brokerUri&quot;&gt;服务地址&lt;/param&gt;    public ActiveMQHelper(string brokerUri)    &#123;        // tcp://127.0.0.1:61616/        _factory = new ConnectionFactory(brokerUri);    &#125;    /// &lt;summary&gt;    /// 注册生产者    /// &lt;/summary&gt;    /// &lt;param name=&quot;topic&quot;&gt;主题&lt;/param&gt;    public void RegisterProducer(string topic)    &#123;        _connection_producer = _factory.CreateConnection();        _session_producer = _connection_producer.CreateSession();        _prod = _session_producer.CreateProducer(new ActiveMQTopic(topic));    &#125;    /// &lt;summary&gt;    /// 注册消费者    /// &lt;/summary&gt;    /// &lt;param name=&quot;topic&quot;&gt;主题&lt;/param&gt;    /// &lt;param name=&quot;clientid&quot;&gt;客户端ID&lt;/param&gt;    public void RegisterConsumer(string topic, string clientid)    &#123;        _connection_consumer = _factory.CreateConnection();        _connection_consumer.ClientId = clientid;        _connection_consumer.Start();        //Create the Session        _session_consumer = _connection_consumer.CreateSession();        //Create the Consumer        IMessageConsumer consumer = _session_consumer.CreateDurableConsumer(new ActiveMQTopic(topic), clientid, null, false);        consumer.Listener += new MessageListener(consumer_Listener);    &#125;    /// &lt;summary&gt;    /// 消费者回调    /// &lt;/summary&gt;    /// &lt;param name=&quot;message&quot;&gt;&lt;/param&gt;    private void consumer_Listener(IMessage message)    &#123;        try        &#123;            ITextMessage msg = (ITextMessage)message;            MessageCallback?.Invoke(msg.Text);        &#125;        catch (Exception)        &#123; &#125;    &#125;    /// &lt;summary&gt;    /// 发送消息    /// &lt;/summary&gt;    public void SendMessage(string message)    &#123;        ITextMessage msg = _prod.CreateTextMessage();        msg.Text = message;        _prod.Send(msg, MsgDeliveryMode.NonPersistent, MsgPriority.Normal, TimeSpan.MinValue);    &#125;    /// &lt;summary&gt;    /// 关闭连接    /// &lt;/summary&gt;    public void Close()    &#123;        // 释放生产者        _prod?.Close();        _prod?.Dispose();        _session_producer?.Close();        _session_producer?.Dispose();        _connection_producer?.Stop();        _connection_producer?.Close();        _connection_producer?.Dispose();        // 释放消费者        _session_consumer?.Close();        _session_consumer?.Dispose();        _connection_consumer?.Stop();        _connection_consumer?.Close();        _connection_consumer?.Dispose();    &#125;&#125;

调用测试生产者static void Main(string[] args)&#123;    // 服务地址    string brokerUri = &quot;127.0.0.1:9092&quot;;    // 主题    string topic;    ActiveMQHelper activeMQHelper = new ActiveMQHelper(brokerUri);    activeMQHelper.RegisterProducer(topic);        while (true)    &#123;        activeMQHelper.SendMessage($&quot;&#123;DateTime.Now&#125;&quot;);        Task.Delay(TimeSpan.FromMilliseconds(500)).Wait();    &#125;&#125;

消费者static void Main(string[] args)&#123;    // 服务地址    string brokerUri = &quot;127.0.0.1:9092&quot;;    // 主题    string topic;    // 客户端 ID    string clientid;    ActiveMQHelper activeMQHelper = new ActiveMQHelper(brokerUri);    activeMQHelper.MessageCallback += ActiveMQHelper_MessageCallback;    activeMQHelper.RegisterConsumer(topic, clientid);&#125;/// &lt;summary&gt;/// 队列消息回调/// &lt;/summary&gt;/// &lt;param name=&quot;message&quot;&gt;&lt;/param&gt;private static void ActiveMQHelper_MessageCallback(string obj)&#123;    Console.WriteLine(obj);&#125;

