oid SetBubbleCallback(DependencyObject d, DependencyPropertyChangedEventArgs e)    &#123;        if (d is Bubble bubble)        &#123;            var vTriangleWidth = 32;            var vTriangleHeight = 25;            switch (bubble.PointingDirection)            &#123;                case BubbleAlignment.Left:                    // 矩形                    bubble.RectangleRect = new Rect(                        bubble.BubbleThickness + bubble.TriangleSize,                        bubble.BubbleThickness,                        bubble.Width - (bubble.BubbleThickness * 2) - bubble.TriangleSize,                        bubble.Height - (bubble.BubbleThickness * 2));                    // 三角                    bubble.TriangleAngle = 90;                    bubble.TriangleX = vTriangleHeight + bubble.BubbleThickness;                    bubble.TriangleY = bubble.Height / 2 - vTriangleWidth / 2;                    // Content                    bubble.ContentHorizontal = HorizontalAlignment.Right;                    bubble.ContentVertical = VerticalAlignment.Stretch;                    bubble.ContentWidth = bubble.Width - bubble.TriangleSize;                    bubble.ContentHeight = bubble.Height;                    break;                case BubbleAlignment.Right:                    // 矩形                    bubble.RectangleRect = new Rect(                        bubble.BubbleThickness,                        bubble.BubbleThickness,                        bubble.Width - (bubble.BubbleThickness * 2) - bubble.TriangleSize,                        bubble.Height - (bubble.BubbleThickness * 2));                    // 三角                    bubble.TriangleAngle = -90;                    bubble.TriangleX = bubble.Width - vTriangleHeight - bubble.BubbleThickness;                    bubble.TriangleY = bubble.Height / 2 + vTriangleWidth / 2;                    // Content                    bubble.ContentHorizontal = HorizontalAlignment.Left;                    bubble.ContentVertical = VerticalAlignment.Stretch;                    bubble.ContentWidth = bubble.Width - bubble.TriangleSize;                    bubble.ContentHeight = bubble.Height;                    break;                case BubbleAlignment.Top:                    // 矩形                    bubble.RectangleRect = new Rect(                        bubble.BubbleThickness,                        bubble.TriangleSize + bubble.BubbleThickness,                        bubble.Width - (bubble.BubbleThickness * 2),                        bubble.Height - bubble.TriangleSize - (bubble.BubbleThickness * 2));                    // Content                    bubble.ContentHorizontal = HorizontalAlignment.Stretch;                    bubble.ContentVertical = VerticalAlignment.Bottom;                    bubble.ContentWidth = bubble.Width;                    bubble.ContentHeight = bubble.Height - bubble.TriangleSize;                    // 三角                    bubble.TriangleAngle = 180;                    bubble.TriangleX = (bubble.Width - vTriangleWidth) / 2 + vTriangleWidth;                    bubble.TriangleY = vTriangleHeight + bubble.BubbleThickness;                    break;                case BubbleAlignment.Bottom:                    // 矩形                    bubble.RectangleRect = new Rect(                        bubble.BubbleThickness,                        bubble.BubbleThickness,                        bubble.Width - (bubble.BubbleThickness * 2),                        bubble.Height - bubble.TriangleSize - (bubble.BubbleThickness * 2));                    // Content                    bubble.ContentHorizontal = HorizontalAlignment.Stretch;                    bubble.ContentVertical = VerticalAlignment.Top;                    bubble.ContentWidth = bubble.Width;                    bubble.ContentHeight = bubble.Height - bubble.TriangleSize;                    // 三角                    bubble.TriangleAngle = 0;                    bubble.TriangleX = (bubble.Width - vTriangleWidth) / 2;                    b