使用 CallerMemberNameAttribute 类获取堆栈信息
简介在项目中需要在打印日志同时打印堆栈信息，通常使用 StackTrace 来捕获堆栈信息，并跟随日志一同打印，但是生产环境部署通常使用 Release 方式打包，这会导致 StackTrace 方法失效。测试改用 CallerMemberNameAttribute 方式可以解决。
代码StackTrace 方式获取堆栈信息public static void SaveError(string message)&#123;    var stackTrace = new StackTrace(true);    var stackFrame = stackTrace.GetFrame(1);    if (stackFrame != null)    &#123;        logger.Error($&quot;[&#123;stackFrame?.GetMethod()?.DeclaringType?.Name&#125;][&#123;stackFrame?.GetMethod()?.Name&#125;] &#123;message&#125;&quot;);    &#125;&#125;

CallerMemberNameAttribute 改用方式获取堆栈信息public static void SaveError(string message,[System.Runtime.CompilerServices.CallerMemberName] string memberName = &quot;&quot;,[System.Runtime.CompilerServices.CallerFilePath] string sourceFilePath = &quot;&quot;,[System.Runtime.CompilerServices.CallerLineNumber] int sourceLineNumber = 0)&#123;    logger.Error($&quot;[&#123;System.IO.Path.GetFileName(sourceFilePath)&#125;][&#123;memberName&#125;] &#123;message&#125;&quot;);&#125;

操作 CSV 文件帮助类
简介工作中用户提供 CSV 文件作为参考数据使用，需要读取到系统中进行相关计算CSV（逗号分隔值文件格式）其文件以纯文本形式存储表格数据，分隔字符也可以不是逗号，可用Excel编辑的表格文件。CSVHelper 帮助类主要提供内存表格DataTable互相转换，以正则表达式与截取拼接。
CSV文件操作/// &lt;summary&gt;/// DataTable转换为CSV/// &lt;/summary&gt;/// &lt;param name=&quot;strSource&quot;&gt;CSV文件路径&lt;/param&gt;/// &lt;param name=&quot;dtSourceData&quot;&gt;DataTable数据&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool DataTableConversionCSV(string strSource, DataTable dtSourceData)&#123;    try    &#123;        if (string.IsNullOrEmpty(strSource) || dtSourceData.Rows.Count &lt; 1)        &#123;            return false;        &#125;        FileStream fileStream = new FileStream(Path.ChangeExtension(strSource, &quot;csv&quot;), FileMode.Create);        StreamWriter streamWriter = new StreamWriter(fileStream);        //记录当前读取到的一行数据        string strRowOfData = string.Empty;        //循环保存列名        for (int iColumnsName = 0; iColumnsName &lt; dtSourceData.Columns.Count; iColumnsName++)        &#123;            strRowOfData += string.Format(&quot;&#123;0&#125;&#123;1&#125;&#123;0&#125;&quot;, &quot;\&quot;&quot;, dtSourceData.Columns[iColumnsName].ColumnName.ToString());            if (iColumnsName &lt; dtSourceData.Columns.Count - 1)            &#123;                strRowOfData += &quot;,&quot;;            &#125;        &#125;        streamWriter.WriteLine(strRowOfData);        //循环保存数据        for (int iRow = 0; iRow &lt; dtSourceData.Rows.Count; iRow++)        &#123;            strRowOfData = string.Empty;            for (int iColumns = 0; iColumns &lt; dtSourceData.Columns.Count; iColumns++)            &#123;                strRowOfData += string.Format(&quot;&#123;0&#125;&#123;1&#125;&#123;0&#125;&quot;, &quot;\&quot;&quot;, dtSourceData.Rows[iRow][iColumns].ToString());                if (iColumns &lt; dtSourceData.Columns.Count - 1)                &#123;                    strRowOfData += &quot;,&quot;;                &#125;            &#125;            streamWriter.WriteLine(strRowOfData);        &#125;        streamWriter.Close();        fileStream.Close();        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// CSV转换为DataTable(默认 UTF8 编码)/// &lt;/summary&gt;/// &lt;param name=&quot;strSource&quot;&gt;CSV文件路径&lt;/param&gt;/// &lt;returns&gt;成功返回CSV的DataTable,失败返回NULL&lt;/returns&gt;public static DataTable CSVConversionDataTable(string strSource)&#123;    try    &#123;        if (string.IsNullOrEmpty(strSource) || !File.Exists(strSource))        &#123;            return null;        &#125;        DataTable dtTargetData = new DataTable();        //初始化 System.IO.FileStream 类的新实例        FileStream fileStreamOpen = new FileStream(strSource, FileMode.Open, FileAccess.Read);        //从当前流中读取一行字符并将数据作为字符串返回        StreamReader streamReader = new StreamReader(fileStreamOpen, Encoding.UTF8);        //记录当前读取到的一行数据        string strRowOfData;        //记录当前是否为标题行        bool boolIsFirst = true;        //循环获得CSV文件数据        while ((strRowOfData = streamReader.ReadLine()) != null)        &#123;            //从当前 System.String 对象中移除所有前导和尾随空白字符            strRowOfData.Trim();            //替换两遍连续两个 ,, 为 ,&quot;&quot;,(希望数据里不存在两个逗号相连的情况)            strRowOfData = strRowOfData.Replace(&quot;,,&quot;, &quot;,\&quot;\&quot;,&quot;);            strRowOfData = strRowOfData.Replace(&quot;,,&quot;, &quot;,\&quot;\&quot;,&quot;);            //如果截取第一个字符是 &#x27;,&#x27; 则在最前面加双引号            if (strRowOfData.Substring(0, 1) == &quot;,&quot;)            &#123;                strRowOfData = string.Format(&quot;\&quot;\&quot;&#123;0&#125;&quot;, strRowOfData);            &#125;            //根据CSV规则分割字符串            string strRegexCSV = string.Format(&quot;[^\&quot;,]+|\&quot;(?:[^\&quot;]|\&quot;\&quot;)*\&quot;&quot;);            Regex regexCSV = new Regex(strRegexCSV);            MatchCollection matchCollection = regexCSV.Matches(strRowOfData);            //判断是否为标题行            if (boolIsFirst)            &#123;                foreach (Match mColumnValue in matchCollection)                &#123;                    dtTargetData.Columns.Add(InterceptionQuotes(mColumnValue.Value));                &#125;                boolIsFirst = false;            &#125;            else            &#123;                DataRow drTargetData = dtTargetData.NewRow();                for (int iColumn = 0; iColumn &lt; dtTargetData.Columns.Count &amp;&amp; iColumn &lt; matchCollection.Count; iColumn++)                &#123;                    drTargetData[iColumn] = InterceptionQuotes(matchCollection[iColumn].Value);                &#125;                dtTargetData.Rows.Add(drTargetData);            &#125;        &#125;        streamReader.Close();        fileStreamOpen.Close();        return dtTargetData;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// CSV转换为DataTable/// &lt;/summary&gt;/// &lt;param name=&quot;strSource&quot;&gt;CSV文件路径&lt;/param&gt;/// &lt;param name=&quot;encoding&quot;&gt;The character encoding to use.&lt;/param&gt;/// &lt;returns&gt;成功返回CSV的DataTable,失败返回NULL&lt;/returns&gt;public static DataTable CSVConversionDataTable(string strSource, Encoding encoding)&#123;    try    &#123;        if (string.IsNullOrEmpty(strSource) || !File.Exists(strSource))        &#123;            return null;        &#125;        DataTable dtTargetData = new DataTable();        //初始化 System.IO.FileStream 类的新实例        FileStream fileStreamOpen = new FileStream(strSource, FileMode.Open, FileAccess.Read);        //从当前流中读取一行字符并将数据作为字符串返回        StreamReader streamReader = new StreamReader(fileStreamOpen, encoding);        //记录当前读取到的一行数据        string strRowOfData;        //记录当前是否为标题行        bool boolIsFirst = true;        //循环获得CSV文件数据        while ((strRowOfData = streamReader.ReadLine()) != null)        &#123;            //从当前 System.String 对象中移除所有前导和尾随空白字符            strRowOfData.Trim();            //替换两遍连续两个 ,, 为 ,&quot;&quot;,(希望数据里不存在两个逗号相连的情况)            strRowOfData = strRowOfData.Replace(&quot;,,&quot;, &quot;,\&quot;\&quot;,&quot;);            strRowOfData = strRowOfData.Replace(&quot;,,&quot;, &quot;,\&quot;\&quot;,&quot;);            //如果截取第一个字符是 &#x27;,&#x27; 则在最前面加双引号            if (strRowOfData.Substring(0, 1) == &quot;,&quot;)            &#123;                strRowOfData = string.Format(&quot;\&quot;\&quot;&#123;0&#125;&quot;, strRowOfData);            &#125;            //根据CSV规则分割字符串            string strRegexCSV = string.Format(&quot;[^\&quot;,]+|\&quot;(?:[^\&quot;]|\&quot;\&quot;)*\&quot;&quot;);            Regex regexCSV = new Regex(strRegexCSV);            MatchCollection matchCollection = regexCSV.Matches(strRowOfData);            //判断是否为标题行            if (boolIsFirst)            &#123;                foreach (Match mColumnValue in matchCollection)                &#123;                    dtTargetData.Columns.Add(InterceptionQuotes(mColumnValue.Value));                &#125;                boolIsFirst = false;            &#125;            else            &#123;                DataRow drTargetData = dtTargetData.NewRow();                for (int iColumn = 0; iColumn &lt; dtTargetData.Columns.Count &amp;&amp; iColumn &lt; matchCollection.Count; iColumn++)                &#123;                    drTargetData[iColumn] = InterceptionQuotes(matchCollection[iColumn].Value);                &#125;                dtTargetData.Rows.Add(drTargetData);            &#125;        &#125;        streamReader.Close();        fileStreamOpen.Close();        return dtTargetData;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 截取字符串前后双引号/// &lt;/summary&gt;/// &lt;param name=&quot;strSource&quot;&gt;源字符串&lt;/param&gt;/// &lt;returns&gt;截取后字符串&lt;/returns&gt;private static string InterceptionQuotes(string strSource)&#123;    try    &#123;        if (strSource[0] == &#x27;\&quot;&#x27; &amp;&amp; strSource[strSource.Length - 1] == &#x27;\&quot;&#x27;)        &#123;            return strSource.Substring(1, strSource.Length - 2);        &#125;        else        &#123;            return strSource;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;

