 /// &lt;param name=&quot;channel&quot;&gt;通道号&lt;/param&gt;    /// &lt;param name=&quot;ptzValue&quot;&gt;PTZ 参数&lt;/param&gt;    /// &lt;returns&gt;是否设置成功&lt;/returns&gt;    bool SetPTZValue(int channel, PTZValue ptzValue);    /// &lt;summary&gt;    /// 获取云台预置位列表    /// &lt;/summary&gt;    /// &lt;param name=&quot;channel&quot;&gt;通道号&lt;/param&gt;    /// &lt;param name=&quot;ptzPresets&quot;&gt;预置位列表&lt;/param&gt;    /// &lt;returns&gt;是否调用成功&lt;/returns&gt;    bool GetPTZPreset(int channel, out List&lt;PTZPreset&gt; ptzPresets);    /// &lt;summary&gt;    /// 云台预置位控制    /// &lt;/summary&gt;    /// &lt;param name=&quot;channel&quot;&gt;通道号&lt;/param&gt;    /// &lt;param name=&quot;ptzCommand&quot;&gt;控制命令&lt;/param&gt;    /// &lt;param name=&quot;presetIndex&quot;&gt;预置位序号&lt;/param&gt;    /// &lt;param name=&quot;presetName&quot;&gt;预置位名称，设置预置位时使用&lt;/param&gt;    /// &lt;returns&gt;是否调用成功&lt;/returns&gt;    bool PTZPresetControl(int channel, PTZCommand ptzCommand, int presetIndex, string presetName);&#125;

