/// &lt;summary&gt;/// 海康相机控制/// &lt;/summary&gt;public class HikvisionControl : ICameraControl&#123;    // 用户 ID 值    private Int32 m_lUserID = -1;    // 预览句柄    private Int32 m_lRealHandle = -1;    public CHCNetSDK.NET_DVR_USER_LOGIN_INFO struLogInfo;    public CHCNetSDK.NET_DVR_DEVICEINFO_V40 DeviceInfo;    public CHCNetSDK.NET_DVR_PRESET_NAME[] m_struPreSetCfg = new CHCNetSDK.NET_DVR_PRESET_NAME[300];    /// &lt;summary&gt;    /// 海康相机控制构造函数    /// &lt;/summary&gt;    /// &lt;param name=&quot;ip&quot;&gt;IP&lt;/param&gt;    /// &lt;param name=&quot;userName&quot;&gt;用户名&lt;/param&gt;    /// &lt;param name=&quot;password&quot;&gt;密码&lt;/param&gt;    /// &lt;param name=&quot;port&quot;&gt;端口&lt;/param&gt;    public HikvisionControl(string ip, string userName, string password, string port = &quot;8000&quot;)    &#123;        struLogInfo = new CHCNetSDK.NET_DVR_USER_LOGIN_INFO();        // 设备IP地址或者域名        byte[] byIP = Encoding.Default.GetBytes(ip);        struLogInfo.sDeviceAddress = new byte[129];        byIP.CopyTo(struLogInfo.sDeviceAddress, 0);        // 设备用户名        byte[] byUserName = Encoding.Default.GetBytes(userName);        struLogInfo.sUserName = new byte[64];        byUserName.CopyTo(struLogInfo.sUserName, 0);        // 设备密码        byte[] byPassword = Encoding.Default.GetBytes(password);        struLogInfo.sPassword = new byte[64];        byPassword.CopyTo(struLogInfo.sPassword, 0);        // 设备服务端口号        struLogInfo.wPort = ushort.Parse(port);        // 是否异步登录：0- 否，1- 是        struLogInfo.bUseAsynLogin = false;        // 初始化        CHCNetSDK.NET_DVR_Init();        // 保存SDK日志 To save the SDK log        //CHCNetSDK.NET_DVR_SetLogToFile(3, &quot;C:\\SdkLog\\&quot;, true);    &#125;    /// &lt;summary&gt;    /// 登录    /// &lt;/summary&gt;    /// &lt;param name=&quot;channels&quot;&gt;通道号集合&lt;/param&gt;    /// &lt;returns&gt;是否登录成功&lt;/returns&gt;    public bool Login(out List&lt;CameraChannel&gt; channels)    &#123;        channels = new List&lt;CameraChannel&gt;();        DeviceInfo = new CHCNetSDK.NET_DVR_DEVICEINFO_V40();        // 登录设备 Login the device        m_lUserID = CHCNetSDK.NET_DVR_Login_V40(ref struLogInfo, ref DeviceInfo);        if (m_lUserID &lt; 0)        &#123;            var iLastErr = CHCNetSDK.NET_DVR_GetLastError();            return false;        &#125;        else        &#123;            // 模拟通道号            var vChanNum = DeviceInfo.struDeviceV30.byChanNum;            // 模拟通道起始通道号            var vStartChan = DeviceInfo.struDeviceV30.byStartChan;            // 添加模拟通道号            for (int i = 0; i &lt; vChanNum; i++)            &#123;                channels.Add(new CameraChannel()                &#123;                    ChannelID = vStartChan + i,                    ChannelName = $&quot;Channel &#123;vStartChan + i&#125;&quot;                &#125;);            &#125;            return true;        &#125;    &#125;    /// &lt;summary&gt;    /// 退出登录    /// &lt;/summary&gt;    /// &lt;returns&gt;是否退出成功&lt;/returns&gt;    public bool Logout()    &#123;        // 注销用户与释放 SDK 资源        return CHCNetSDK.NET_DVR_Logout(m_lUserID) &amp;&amp; CHCNetSDK.NET_DVR_Cleanup();    &#125;    /// &lt;summary&gt;    /// 获取流 RTSP 地址    /// &lt;/summary&gt;    /// &lt;param name=&quot;channel&quot;&gt;通道号&lt;/param&gt;    /// &lt;param name=&quot;streamUris&quot;&gt;流地址集合&lt;/param&gt;    /// &lt;returns&gt;是否获取成功&lt;/returns&gt;    public bool GetStreamUri(int channel, out List&lt;string&gt; streamUris)    &#123;        streamUris = new List&lt;string&gt;();        return false;    &#125;    /// &lt;summary&gt;    /// 实时预览    /// &lt;/summary&gt;    /// &lt;param name=&quot;channel&quot;&gt;通道号&lt;/param&gt;    /// &lt;param name=&quot;hPlayWnd&quot;&gt;渲染句柄&lt;/param&gt;    /// &lt;returns&gt;是否成功&lt;/returns&gt;    public bool RealPlay(int channel, IntPtr hPlayWnd)    &#123;        if (m_lRealHandle &gt;= 0)        &#123;            // 已经开启预览            return false;        &#125;        CHCNetSDK.NET_DVR