/ &lt;summary&gt;    /// 获取云台 PTZ 值    /// &lt;/summary&gt;    /// &lt;param name=&quot;channel&quot;&gt;通道号&lt;/param&gt;    /// &lt;param name=&quot;ptzValue&quot;&gt;PTZ 参数&lt;/param&gt;    /// &lt;returns&gt;是否调用成功&lt;/returns&gt;    public bool GetPTZValue(int channel, out PTZValue ptzValue)    &#123;        ptzValue = new PTZValue();        var token = profiles[channel].token;        var vGetStatusTask = Task.Run(async () =&gt; await onvifCamera.Ptz.GetStatusAsync(token));        var vGetStatus = vGetStatusTask.Result;        if (vGetStatus != null &amp;&amp; vGetStatus.Position != null)        &#123;            ptzValue.P = vGetStatus.Position.PanTilt.x;            ptzValue.T = vGetStatus.Position.PanTilt.y;            ptzValue.Z = vGetStatus.Position.Zoom.x;        &#125;        return true;    &#125;    /// &lt;summary&gt;    /// 设置云台 PTZ 值    /// &lt;/summary&gt;    /// &lt;param name=&quot;channel&quot;&gt;通道号&lt;/param&gt;    /// &lt;param name=&quot;ptzValue&quot;&gt;PTZ 参数&lt;/param&gt;    /// &lt;returns&gt;是否设置成功&lt;/returns&gt;    public bool SetPTZValue(int channel, PTZValue ptzValue)    &#123;        // 获取球机绝对移动范围        var vGetNodesTask = Task.Run(async () =&gt; await onvifCamera.Ptz.GetNodesAsync());        var vGetNodes = vGetNodesTask.Result;        if (vGetNodes != null &amp;&amp; vGetNodes.PTZNode != null &amp;&amp; vGetNodes.PTZNode.Count() &gt;= 1)        &#123;            var vPanTilt = vGetNodes.PTZNode[0].SupportedPTZSpaces.AbsolutePanTiltPositionSpace;            var vZoom = vGetNodes.PTZNode[0].SupportedPTZSpaces.AbsoluteZoomPositionSpace;        &#125;        // 调用球机绝对移动        var token = profiles[channel].token;        var vectorPT = new CameraControl.Onvif.Client.Common.PTZVector &#123; PanTilt = new CameraControl.Onvif.Client.Common.Vector2D &#123; x = ptzValue.P, y = ptzValue.T &#125; &#125;;        var speedPT = new CameraControl.Onvif.Client.Common.PTZSpeed &#123; PanTilt = new CameraControl.Onvif.Client.Common.Vector2D &#123