1021&#x2F;130/// &lt;summary&gt;/// 计算位置坐标(WGS-84中)项(I021/130)对应的值/// &lt;/summary&gt;/// &lt;param name=&quot;byteData&quot;&gt;二进制数据&lt;/param&gt;/// &lt;returns&gt;&lt;/returns&gt;public static double[] I021_130(byte[] byteData)&#123;    if (byteData.Length == 6)    &#123;        return I021_131(byteData);    &#125;    else if (byteData.Length == 8)    &#123;        double[] res = &#123; 0, 0 &#125;;        int value1;        //将容器中前4个字节合并为一个字节，用以计算纬度。        value1 = (byteData[0] &lt;&lt; 24) + (byteData[1] &lt;&lt; 16) + (byteData[2] &lt;&lt; 8) + byteData[3];        double temp1 = value1 * (5.364418e-6);        //Console.WriteLine($&quot;坐标值:纬度值&#123;temp1&#125;&quot;);        res[1] = temp1;        int value0;        //将容器中后4个字节合并为一个字节，用以计算经度。        value0 = (byteData[4] &lt;&lt; 24) + (byteData[5] &lt;&lt; 16) + (byteData[6] &lt;&lt; 8) + byteData[7];        double temp0 = value0 * (5.364418e-6);        //Console.WriteLine($&quot;经度值&#123;temp0&#125;&quot;);        res[0] = temp0;        return res;    &#125;    return null;&#125;


1021&#x2F;131/// &lt;summary&gt;/// 计算位置坐标(WGS-84中)项(I021/131)对应的值/// &lt;/summary&gt;/// &lt;param name=&quot;byteData&quot;&gt;二进制数据&lt;/param&gt;/// &lt;returns&gt;&lt;/returns&gt;public static double[] I021_131(byte[] byteData)&#123;    var len = byteData.Length;    var startIndex = 0;    var Len6Ruler = 180 / Math.Pow(2, 23);    var Len8Ruler = 180 / Math.Pow(2, 30);    //根据长度确定转换标尺    var ruler = len == 6 ? Len6Ruler : Len8Ruler;    var res = new double[] &#123; 0, 0 &#125;;    int startValue = 0;    byte lshBit = 0;    //将容器中前一半字节合并为一个字节，用以计算纬度。    for (int i = startIndex + len / 2 - 1; i &gt;= startIndex; i--)    &#123;        startValue += (int)byteData[i] &lt;&lt; lshBit;        lshBit += 8;    &#125;    res[1] = startValue * ruler;    int endValue = 0;    lshBit = 0;    //将容器中后一半字节合并为一个字节，用以计算经度。    for (int i = startIndex + len - 1; i &gt;= startIndex + len / 2; i--)    &#123;        endValue += (int)byteData[i] &lt;&lt; lshBit;        lshBit += 8;    &#125;    res[0] = endValue * ruler;    return res;&#125;

