&lt;html&gt;&lt;head&gt;    &lt;script type=&quot;text/javascript&quot; src=&quot;https://code.jquery.com/jquery-3.6.0.min.js&quot;&gt;&lt;/script&gt;    &lt;script type=&quot;text/javascript&quot; src=&quot;https://api.map.baidu.com/api?v=3.0&amp;您的ak&quot;&gt;&lt;/script&gt;    &lt;style type=&quot;text/css&quot;&gt;        body &#123;            margin: 0;        &#125;                #allmap &#123;            width: 100%;            height: 100%;            overflow: hidden;            margin: 0;        &#125;    &lt;/style&gt;&lt;/head&gt;&lt;body&gt;    &lt;div id=&quot;allmap&quot;&gt;&lt;/div&gt;&lt;/body&gt;&lt;script&gt;    //获取经纬度参数    function getUrlParam(name) &#123;        var reg = new RegExp(&quot;(^|&amp;)&quot; + name + &quot;=([^&amp;]*)(&amp;|$)&quot;);        var r = window.location.search.substr(1).match(reg);        if (r != null) &#123;            return unescape(r[2]);        &#125; else &#123;            return null;        &#125;    &#125;    var vLon = getUrlParam(&#x27;Lon&#x27;);    var vLat = getUrlParam(&#x27;Lat&#x27;);    //加载百度地图    //创建Map实例    var map = new BMap.Map(&quot;allmap&quot;);    //创建点坐标    var point = new BMap.Point(vLon, vLat);    map.centerAndZoom(point, 17);    //启用滚轮放大缩小    map.enableScrollWheelZoom();    //创建标注    var marker = new BMap.Marker(point);    //将标注添加到地图中    map.addOverlay(marker);&lt;/script&gt;&lt;/html&gt;

