提供几种对称加密与非对称加密算法，以及单项加密与文件夹加密简介工作中需要各种方式的加密（传输文本加密，文件加密，图片Base64编码，文件MD5与SHA1值计算），既有对称式加密与非对称式加密，也有单向加密，应用于各种使用环境。
警告由于2017年5月12日的比特币勒索病毒 WannaCry 爆发，100多个国家和地区超过10万台电脑遭到了勒索病毒攻击、感染。其原理就是加密电脑中的文件，以用秘钥勒索比特币。技术本质并无好坏之分，多行善事。
帮助类、介绍对称式加密对称加密算法 解密使用相同密钥及相同算法的逆算法对密文进行解密。
AESAES 一种区块加密标准，替代原先的DES，对称密钥加密中最流行的算法之一。AESHelper
/// &lt;summary&gt;/// AES加密/// &lt;/summary&gt;/// &lt;param name=&quot;strPlaintext&quot;&gt;明文&lt;/param&gt;/// &lt;param name=&quot;strKey&quot;&gt;秘钥&lt;/param&gt;/// &lt;returns&gt;AES密文&lt;/returns&gt;public static string AESEncrypt(string strPlaintext, string strKey)&#123;    try    &#123;        if (string.IsNullOrEmpty(strPlaintext))        &#123;            return string.Empty;        &#125;        strKey = strKey.Length &lt; 32 ? strKey.PadRight(32, &#x27;0&#x27;) : strKey.Substring(0, 32);        Byte[] toEncryptArray = Encoding.UTF8.GetBytes(strPlaintext);        RijndaelManaged rijndaelManaged = new RijndaelManaged        &#123;            Key = Encoding.UTF8.GetBytes(strKey),            Mode = CipherMode.ECB,            Padding = PaddingMode.PKCS7        &#125;;        ICryptoTransform pCryptoTransform = rijndaelManaged.CreateEncryptor();        Byte[] resultArray = pCryptoTransform.TransformFinalBlock(toEncryptArray, 0, toEncryptArray.Length);        return Convert.ToBase64String(resultArray, 0, resultArray.Length);    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// AES解密/// &lt;/summary&gt;/// &lt;param name=&quot;strCiphertext&quot;&gt;AES密文&lt;/param&gt;/// &lt;param name=&quot;strKey&quot;&gt;秘钥&lt;/param&gt;/// &lt;returns&gt;明文&lt;/returns&gt;public static string AESDecrypt(string strCiphertext, string strKey)&#123;    try    &#123;        if (string.IsNullOrEmpty(strCiphertext))        &#123;            return string.Empty;        &#125;        strKey = strKey.Length &lt; 32 ? strKey.PadRight(32, &#x27;0&#x27;) : strKey.Substring(0, 32);        Byte[] toEncryptArray = Convert.FromBase64String(strCiphertext);        RijndaelManaged rijndaelManaged = new RijndaelManaged        &#123;            Key = Encoding.UTF8.GetBytes(strKey),            Mode = CipherMode.ECB,            Padding = PaddingMode.PKCS7        &#125;;        ICryptoTransform pCryptoTransform = rijndaelManaged.CreateDecryptor();        Byte[] resultArray = pCryptoTransform.TransformFinalBlock(toEncryptArray, 0, toEncryptArray.Length);        return Encoding.UTF8.GetString(resultArray);    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// 文件AES加密/// &lt;/summary&gt;/// &lt;param name=&quot;strFilePath&quot;&gt;文件路径&lt;/param&gt;/// &lt;param name=&quot;strSaveFilePath&quot;&gt;加密文件目录&lt;/param&gt;/// &lt;param name=&quot;strKey&quot;&gt;秘钥&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool FileAESEncrypt(string strFilePath, string strSaveFilePath, string strKey)&#123;    try    &#123;        //设置Aes秘钥和格式        strKey = strKey.Length &lt; 32 ? strKey.PadRight(32, &#x27;0&#x27;) : strKey.Substring(0, 32);        RijndaelManaged rijndaelManaged = new RijndaelManaged        &#123;            Key = Encoding.UTF8.GetBytes(strKey),            Mode = CipherMode.ECB,            Padding = PaddingMode.PKCS7        &#125;;        //读取文本加密数据        FileStream fileStream = File.OpenRead(strFilePath);        byte[] byteFileStream = new byte[fileStream.Length];        fileStream.Read(byteFileStream, 0, (int)fileStream.Length);        fileStream.Close();        using (var memoryStream = new MemoryStream())        &#123;            using (var cryptoStream = new CryptoStream(memoryStream, rijndaelManaged.CreateEncryptor(), CryptoStreamMode.Write))            &#123;                cryptoStream.Write(byteFileStream, 0, byteFileStream.Length);                cryptoStream.FlushFinalBlock();                fileStream = File.OpenWrite(strSaveFilePath);                foreach (byte byteMemoryStream in memoryStream.ToArray())                &#123;                    fileStream.WriteByte(byteMemoryStream);                &#125;                fileStream.Close();                cryptoStream.Close();                memoryStream.Close();                return true;            &#125;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 文件AES解密/// &lt;/summary&gt;/// &lt;param name=&quot;strFilePath&quot;&gt;被加密的文件路径&lt;/param&gt;/// &lt;param name=&quot;strSaveFilePath&quot;&gt;解密文件目录&lt;/param&gt;/// &lt;param name=&quot;strKey&quot;&gt;秘钥&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool FileAESDecrypt(string strFilePath, string strSaveFilePath, string strKey)&#123;    try    &#123;        strKey = strKey.Length &lt; 32 ? strKey.PadRight(32, &#x27;0&#x27;) : strKey.Substring(0, 32);        RijndaelManaged rijndaelManaged = new RijndaelManaged        &#123;            Key = Encoding.UTF8.GetBytes(strKey),            Mode = CipherMode.ECB,            Padding = PaddingMode.PKCS7        &#125;;        FileStream fileStream = File.OpenRead(strFilePath);        byte[] byteFileStream = new byte[fileStream.Length];        fileStream.Read(byteFileStream, 0, (int)fileStream.Length);        fileStream.Close();        using (var memoryStream = new MemoryStream())        &#123;            using (var cryptoStream = new CryptoStream(memoryStream, rijndaelManaged.CreateDecryptor(), CryptoStreamMode.Write))            &#123;                cryptoStream.Write(byteFileStream, 0, byteFileStream.Length);                cryptoStream.FlushFinalBlock();                fileStream = File.OpenWrite(strSaveFilePath);                foreach (byte byteMemoryStream in memoryStream.ToArray())                &#123;                    fileStream.WriteByte(byteMemoryStream);                &#125;                fileStream.Close();                cryptoStream.Close();                memoryStream.Close();                return true;            &#125;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;

