byte[] byteBase64 = Convert.FromBase64String(strCiphertext);            using (var memoryStream = new MemoryStream())            &#123;                using (var cryptoStream = new CryptoStream(memoryStream, cryptoTransform, CryptoStreamMode.Write))                &#123;                    cryptoStream.Write(byteBase64, 0, byteBase64.Length);                    cryptoStream.FlushFinalBlock();                &#125;                return Encoding.UTF8.GetString(memoryStream.ToArray());            &#125;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// 文件DES加密/// &lt;/summary&gt;/// &lt;param name=&quot;strFilePath&quot;&gt;文件路径&lt;/param&gt;/// &lt;param name=&quot;strSaveFilePath&quot;&gt;加密文件目录&lt;/param&gt;/// &lt;param name=&quot;strKey&quot;&gt;秘钥(8位)&lt;/param&gt;/// &lt;param name=&quot;strIV&quot;&gt;向量(8位)&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool FileDESEncrypt(string strFilePath, string strSaveFilePath, string strKey, string strIV)&#123;    try    &#123;        DESCryptoServiceProvider desCrypto = new DESCryptoServiceProvider();        desCrypto.Key = UTF8Encoding.Default.GetBytes(strKey);        desCrypto.IV = UTF8Encoding.UTF8.GetBytes(strIV);        FileStream fileStream = File.OpenRead(strFilePath);        byte[] byteFileStream = new byte[fileStream.Length];        fileStream.Read(byteFileStream, 0, (int)fileStream.Length);        fileStream.Close();        using (var memoryStream = new MemoryStream())        &#123;            using (var cryptoStream = new CryptoStream(memoryStream, desCrypto.CreateEncryptor(), CryptoStreamMode.Write))            &#123;                cryptoStream.Write(byteFileStream, 0, byteFileStream.Length);                cryptoStream.FlushFinalBlock();                fileStream = File.OpenWrite(strSaveFilePath);                foreach (byte byteMemoryStream in memoryStream.ToArray())                &#123;                    fileStream.WriteByte(byteMemoryStream);                &#125;                fileStream.Close();                cryptoStream.Close();                memoryStream.Close();                return true;            &#125;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 文件DES解密/// &lt;/summary&gt;/// &lt;param name=&quot;strFilePath&quot;&gt;被加密的文件路径&lt;/param&gt;/// &lt;param name=&quot;strSaveFilePath&quot;&gt;解密文件目录&lt;/param&gt;/// &lt;param name=&quot;strKey&quot;&gt;秘钥(8位)&lt;/param&gt;/// &lt;param name=&quot;strIV&quot;&gt;向量(8位)&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool FileDESDecrypt(string strFilePath, string strSaveFilePath, string strKey, string strIV)&#123;    try    &#123;        DESCryptoServiceProvider desCrypto = new DESCryptoServiceProvider();        desCrypto.Key = UTF8Encoding.Default.GetBytes(strKey);        desCrypto.IV = UTF8Encoding.UTF8.GetBytes(strIV);        FileStream fileStream = File.OpenRead(strFilePath);        byte[] byteFileStream = new byte[fileStream.Length];        fileStream.Read(byteFileStream, 0, (int)fileStream.Length);        fileStream.Close();        using (var memoryStream = new MemoryStream())        &#123;            using (var cryptoStream = new CryptoStream(memoryStream, desCrypto.CreateDecryptor(), CryptoStreamMode.Write))            &#123;                cryptoStream.Write(byteFileStream, 0, byteFileStream.Length);                cryptoStream.FlushFinalBlock();                fileStream = File.OpenWrite(strSaveFilePath);                foreach (byte byteMemoryStream in memoryStream.ToArray())                &#123;                    fileStream.WriteByte(byteMemoryStream);                &#125;                fileStream.Close();                cryptoStream.Close();                memoryStream.Close();                return true