非对称式加密非对称加密算法 需要两个密钥：公开密钥（publickey:简称公钥）和私有密钥（privatekey:简称私钥）。公钥与私钥是一对，如果用公钥对数据进行加密，只有用对应的私钥才能解密。
RSARSA 一种非对称加密算法。在公开密钥加密和电子商业中RSA被广泛使用。RSAHelper 只能使用产生出的密钥，且加密更加复杂所以只能加密短文本（测试加密长度上限为58字节）。
/// &lt;summary&gt;/// RSA产生秘钥/// &lt;/summary&gt;/// &lt;param name=&quot;xmlPublicKey&quot;&gt;公钥&lt;/param&gt;/// &lt;param name=&quot;xmlPrivateKey&quot;&gt;私钥&lt;/param&gt;public static void RSAKey(out string xmlPublicKey, out string xmlPrivateKey)&#123;    try    &#123;        RSACryptoServiceProvider rsaCrypto = new RSACryptoServiceProvider();        xmlPublicKey = rsaCrypto.ToXmlString(false);        xmlPrivateKey = rsaCrypto.ToXmlString(true);    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        xmlPublicKey = string.Empty;        xmlPrivateKey = string.Empty;    &#125;&#125;/// &lt;summary&gt;/// RSA加密/// &lt;/summary&gt;/// &lt;param name=&quot;strPlaintext&quot;&gt;明文&lt;/param&gt;/// &lt;param name=&quot;xmlPublicKey&quot;&gt;公钥&lt;/param&gt;/// &lt;returns&gt;RSA密文&lt;/returns&gt;public static string RSAEncrypt(string strPlaintext, string xmlPublicKey)&#123;    try    &#123;        RSACryptoServiceProvider rsaCrypto = new RSACryptoServiceProvider();        rsaCrypto.FromXmlString(xmlPublicKey);        UnicodeEncoding unicodeEncoding = new UnicodeEncoding();        byte[] byteBaseUnicode = unicodeEncoding.GetBytes(strPlaintext);        byte[] byteBaseEncrypt = rsaCrypto.Encrypt(byteBaseUnicode, false);        string strRSAEncrypt = Convert.ToBase64String(byteBaseEncrypt);        return strRSAEncrypt;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// RSA解密/// &lt;/summary&gt;/// &lt;param name=&quot;strCiphertext&quot;&gt;RSA密文&lt;/param&gt;/// &lt;param name=&quot;xmlPrivateKey&quot;&gt;私钥&lt;/param&gt;/// &lt;returns&gt;明文&lt;/returns&gt;public static string RSADecrypt(string strCiphertext, string xmlPrivateKey)&#123;    try    &#123;        RSACryptoServiceProvider rsaCrypto = new RSACryptoServiceProvider();        rsaCrypto.FromXmlString(xmlPrivateKey);        byte[] byteBase64 = Convert.FromBase64String(strCiphertext);        byte[] byteBaseDecrypt = rsaCrypto.Decrypt(byteBase64, false);        string strRSADecrypt = (new UnicodeEncoding()).GetString(byteBaseDecrypt);        return strRSADecrypt;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;

单项加密密码散列函数 一种单向函数，也就是说极其难以由散列函数输出的结果，回推输入的数据是什么。多用于文件效验完整性。
MD5MD5 一种被广泛使用的密码散列函数，可以产生出一个128位（16字节）的散列值（hash value），用于确保信息传输完整一致。MD5Helper
