= strCiphertext.ToLower();        return strCiphertext;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// MD5加密(32位大写)/// &lt;/summary&gt;/// &lt;param name=&quot;strPlaintext&quot;&gt;明文&lt;/param&gt;/// &lt;returns&gt;MD5密文(32位小写)&lt;/returns&gt;public static string MD5Encrypt_32Upper(string strPlaintext)&#123;    try    &#123;        MD5CryptoServiceProvider md5Crypto = new MD5CryptoServiceProvider();        string strCiphertext = BitConverter.ToString(md5Crypto.ComputeHash(UTF8Encoding.Default.GetBytes(strPlaintext)));        strCiphertext = strCiphertext.Replace(&quot;-&quot;, &quot;&quot;);        strCiphertext = strCiphertext.ToUpper();        return strCiphertext;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// 获取文件MD5值(32位小写)/// &lt;/summary&gt;/// &lt;param name=&quot;strFilePath&quot;&gt;文件路径&lt;/param&gt;/// &lt;returns&gt;文件MD5值(32位小写)&lt;/returns&gt;public static string FileMD5Encrypt_32Lower(string strFilePath)&#123;    try    &#123;        FileStream fileStream = new FileStream(strFilePath, FileMode.Open, FileAccess.Read);        System.Security.Cryptography.MD5 md5 = new System.Security.Cryptography.MD5CryptoServiceProvider();        byte[] byteHash = md5.ComputeHash(fileStream);        fileStream.Close();        StringBuilder stringBuilder = new StringBuilder();        for (int i = 0; i &lt; byteHash.Length; i++)        &#123;            stringBuilder.Append(byteHash[i].ToString(&quot;x2&quot;));        &#125;        return stringBuilder.ToString();    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// 获取文件MD5值(32位大写)/// &lt;/summary&gt;/// &lt;param name=&quot;strFilePath&quot;&gt;文件路径&lt;/param&gt;/// &lt;returns&gt;文件MD5值(32位大写)&lt;/returns&gt;public static string FileMD5Encrypt_32Upper(string strFilePath)&#123;    try    &#123;        FileStream fileStream = new FileStream(strFilePath, FileMode.Open, FileAccess.Read);        System.Security.Cryptography.MD5 md5 = new System.Security.Cryptography.MD5CryptoServiceProvider();        byte[] byteHash = md5.ComputeHash(fileStream);        fileStream.Close();        StringBuilder stringBuilder = new StringBuilder();        for (int i = 0; i &lt; byteHash.Length; i++)        &#123;            stringBuilder.Append(byteHash[i].ToString(&quot;X2&quot;));        &#125;        return stringBuilder.ToString();    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;

