/// &lt;summary&gt;/// CRC32加密(8位小写)/// &lt;/summary&gt;/// &lt;param name=&quot;strPlaintext&quot;&gt;明文&lt;/param&gt;/// &lt;returns&gt;CRC32密文(8位小写)&lt;/returns&gt;public static string CRC32Encrypt_8Lower(string strPlaintext)&#123;    try    &#123;        Crc32 crc32Crypto = new Crc32();        byte[] bytes_crc32_in = UTF8Encoding.Default.GetBytes(strPlaintext);        byte[] bytes_crc32_out = crc32Crypto.ComputeHash(bytes_crc32_in);        string str_crc32_out = BitConverter.ToString(bytes_crc32_out);        str_crc32_out = str_crc32_out.Replace(&quot;-&quot;, &quot;&quot;);        str_crc32_out = str_crc32_out.ToLower();        return str_crc32_out;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// CRC32加密(8位大写)/// &lt;/summary&gt;/// &lt;param name=&quot;strPlaintext&quot;&gt;明文&lt;/param&gt;/// &lt;returns&gt;CRC32密文(8位大写)&lt;/returns&gt;public static string CRC32Encrypt_8Upper(string strPlaintext)&#123;    try    &#123;        Crc32 crc32Crypto = new Crc32();        byte[] bytes_crc32_in = UTF8Encoding.Default.GetBytes(strPlaintext);        byte[] bytes_crc32_out = crc32Crypto.ComputeHash(bytes_crc32_in);        string str_crc32_out = BitConverter.ToString(bytes_crc32_out);        str_crc32_out = str_crc32_out.Replace(&quot;-&quot;, &quot;&quot;);        str_crc32_out = str_crc32_out.ToUpper();        return str_crc32_out;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// 获取文件CRC32值(8位小写)/// &lt;/summary&gt;/// &lt;param name=&quot;strFilePath&quot;&gt;文件路径&lt;/param&gt;/// &lt;returns&gt;文件CRC32值(8位小写)&lt;/returns&gt;public static string FileCRC32Encrypt_8Lower(string strFilePath)&#123;    try    &#123;        String hashCRC32 = String.Empty;        //检查文件是否存在,如果文件存在则进行计算,否则返回空值        if (System.IO.File.Exists(strFilePath))        &#123;            using (System.I