        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// 提供 CRC32 算法的实现/// &lt;/summary&gt;public class Crc32 : System.Security.Cryptography.HashAlgorithm&#123;    /// &lt;summary&gt;    /// Default Polynomial    /// &lt;/summary&gt;    public const UInt32 DefaultPolynomial = 0xedb88320;    /// &lt;summary&gt;    /// Default Seed    /// &lt;/summary&gt;    public const UInt32 DefaultSeed = 0xffffffff;    private UInt32 hash;    private UInt32 seed;    private UInt32[] table;    private static UInt32[] defaultTable;    /// &lt;summary&gt;    /// Crc32    /// &lt;/summary&gt;    public Crc32()    &#123;        table = InitializeTable(DefaultPolynomial);        seed = DefaultSeed;        Initialize();    &#125;    /// &lt;summary&gt;    /// Crc32    /// &lt;/summary&gt;    /// &lt;param name=&quot;polynomial&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;seed&quot;&gt;&lt;/param&gt;    public Crc32(UInt32 polynomial, UInt32 seed)    &#123;        table = InitializeTable(polynomial);        this.seed = seed;        Initialize();    &#125;    /// &lt;summary&gt;    /// 初始化    /// &lt;/summary&gt;    public override void Initialize()    &#123;        hash = seed;    &#125;    /// &lt;summary&gt;    /// Hash Core    /// &lt;/summary&gt;    /// &lt;param name=&quot;buffer&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;start&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;length&quot;&gt;&lt;/param&gt;    protected override void HashCore(byte[] buffer, int start, int length)    &#123;        hash = CalculateHash(table, hash, buffer, start, length);    &#125;    /// &lt;summary&gt;    /// Hash Final    /// &lt;/summary&gt;    /// &lt;returns&gt;&lt;/returns&gt;    protected override byte[] HashFinal()    &#123;        byte[] hashBuffer = UInt32ToBigEndianBytes(~hash);        this.HashValue = hashBuffer;        return hashBuffer;    &#125;    /// &lt;summary&gt;    /// Compute    /// &lt;/summary&gt;    /// &lt;param name=&quot;buffer&quot;&gt;&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public static UInt32 Compute(byte[] buffer)    &#123;        return ~CalculateHash(InitializeTable(DefaultPolynomial), DefaultSeed, buffer, 0, buffer.Length);    &#125;    /// &lt;summary&gt;    /// Compute    /// &lt;/summary&gt;    /// &lt;param name=&quot;seed&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;buffer&quot;&gt;&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public static UInt32 Compute(UInt32 seed, byte[] buffer)    &#123;        return ~CalculateHash(InitializeTable(DefaultPolynomial), seed, buffer, 0, buffer.Length);    &#125;    /// &lt;summary&gt;    /// Compute    /// &lt;/summary&gt;    /// &lt;param name=&quot;polynomial&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;seed&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;buffer&quot;&gt;&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public static UInt32 Compute(UInt32 polynomial, UInt32 seed, byte[] buffer)    &#123;        return ~CalculateHash(InitializeTable(polynomial), seed, buffer, 0, buffer.Length);    &#125;    private static UInt32[] InitializeTable(UInt32 polynomial)    &#123;        if (polynomial == DefaultPolynomial &amp;&amp; defaultTable != null)        &#123;            return defaultTable;        &#125;        UInt32[] createTable = new UInt32[256];        for (int i = 0; i &lt; 256; i++)        &#123;            UInt32 entry = (UInt32)i;            for (int j = 0; j &lt; 8; j++)            &#123;                if ((entry &amp; 1) == 1)                    entry = (entry &gt;&gt; 1) ^ polynomial;                else                    entry = entry &gt;&gt; 1;            &#125;            createTable[i] = entry;        &#125;        if (polynomial == DefaultPolynomial)        &#123;            defaultTable = createTable;        &#125;        return createTable;    &#125;    private static UInt32 CalculateHash(UInt32[] table, UInt32 seed, byte[] buffer, int start, int size)    &#123;        UInt32 crc = seed;        for (int i = start; i &lt; size; i++)        &#123;            unchecked            &#123;                crc = (crc &gt;&gt; 8) ^ table[buffer[i] ^ crc &amp; 0xff];            &#125;        &#125;        return crc;    &#125;    private byte[] UInt32ToBigEndianBytes(UInt32 x)    &#123;        return new byte[] &#123; (byte)((x &gt;&gt; 24) &amp; 0xff), (byte)((x &gt;&gt; 16) &amp; 0xff), (byte)((x &gt;&gt; 8) &amp; 0xff), (byte)(x &amp; 0xff) &#125;;    &#125;&#125;

其它方式（Base64）Base64Base64 网络上最常见的用于传输8Bit字节码的编码方式之一，准确的来说Base64不属于加密范围，仅是一种基于64个可打印字符来表示二进制数据的方法。多用于图片传输使用。Base64Helper
/// &lt;summary&gt;/// Base64加密/// &lt;/summary&gt;/// &lt;param name=&quot;strPlaintext&quot;&gt;明文&lt;/param&gt;/// &lt;returns&gt;Base64密文&lt;/returns&gt;public static string Base64Encrypt(string strPlaintext)&#123;    try    &#123;        byte[] bytes = Encoding.UTF8.GetBytes(strPlaintext);        return Convert.ToBase64String(bytes);    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// Base64解密/// &lt;/summary&gt;/// &lt;param name=&quot;strCiphertext&quot;&gt;Base64密文&lt;/param&gt;/// &lt;returns&gt;明文&lt;/returns&gt;public static string Base64Decrypt(string strCiphertext)&#123;    try    &#123;        byte[] bytes = Convert.FromBase64String(strCiphertext);        return Encoding.UTF8.GetString(bytes);    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// 图片Base64加密/// &lt;/summary&gt;/// &lt;param name=&quot;strImagePath&quot;&gt;图片路径&lt;/param&gt;/// &lt;param name=&quot;imageFormat&quot;&gt;指定图像格式&lt;/param&gt;/// &lt;returns&gt;Base64密文&lt;/returns&gt;public static string ImageBase64Encrypt(string strImagePath, ImageFormat imageFormat)&#123;    try    &#123;        MemoryStream memoryStream = new MemoryStream();        Bitmap bitmap = new Bitmap(strImagePath);        if (imageFormat == null)        &#123;            imageFormat = GetImageFormatFromPath(strImagePath);        &#125;        bitmap.Save(memoryStream, imageFormat);        byte[] bytes = memoryStream.GetBuffer();        return Convert.ToBase64String(bytes);    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return string.Empty;    &#125;&#125;/// &lt;summary&gt;/// 图片Base64解密/// &lt;/summary&gt;/// &lt;param name=&quot;strCiphertext&quot;&gt;Base64密文&lt;/param&gt;/// &lt;param name=&quot;strSaveFilePath&quot;&gt;解密图片目录&lt;/param&gt;/// &lt;param name=&quot;imageFormat&quot;&gt;指定图像格式&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool ImageBase64Decrypt(string strCiphertext, string strSaveFilePath, ImageFormat imageFormat)&#123;    try    &#123;        byte[] bytes = Convert.FromBase64String(strCiphertext);        MemoryStream memoryStream = new MemoryStream(bytes);        Bitmap bitmap = new Bitmap(memoryStream);        if (imageFormat == null)        &#123;            imageFormat = GetImageFormatFromPath(strSaveFilePath);        &#125;        bitmap.Save(strSaveFilePath, imageFormat);        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 根据图片路径获得图片格式(缺少MemoryBmp)/// &lt;/summary&gt;/// &lt;param name=&quot;strImagePath&quot;&gt;图片路径&lt;/param&gt;/// &lt;returns&gt;图片格式&lt;/returns&gt;public static ImageFormat GetImageFormatFromPath(string strImagePath)&#123;    try    &#123;        string strImageExtension = Path.GetExtension(strImagePath).ToLower();        if (string.IsNullOrEmpty(strImageExtension))        &#123;            return null;        &#125;        else        &#123;            if (strImageExtension.Equals(&quot;.bmp&quot;) || strImageExtension.Equals(&quot;.rle&quot;) || strImageExtension.Equals(&quot;.dlb&quot;))            &#123;                return ImageFormat.Bmp;            &#125;            else if (strImageExtension.Equals(&quot;.emf&quot;))            &#123;                return ImageFormat.Emf;            &#125;            else if (strImageExtension.Equals(&quot;.exif&quot;))            &#123;                return ImageFormat.Exif;            &#125;            else if (strImageExtension.Equals(&quot;.gif&quot;))            &#123;                return ImageFormat.Gif;            &#125;            else if (strImageExtension.Equals(&quot;.ico&quot;))            &#123;                return ImageFormat.Icon;            &#125;            else if (strImageExtension.Equals(&quot;.jpg&quot;) || strImageExtension.Equals(&quot;.jpeg&quot;) || strImageExtension.Equals(&quot;.jpe&quot;))            &#123;                return ImageFormat.Jpeg;            &#125;            else if (strImageExtension.Equals(&quot;.png&quot;) || strImageExtension.Equals(&quot;.pns&quot;))            &#123;                return ImageFormat.Png;            &#125;            else if (strImageExtension.Equals(&quot;.tif&quot;) || strImageExtension.Equals(&quot;.tiff&quot;))            &#123;                return ImageFormat.Tiff;            &#125;            else if (strImageExtension.Equals(&quot;.wmf&quot;))            &#123;                return ImageFormat.Wmf;            &#125;            else            &#123;                return null;            &#125;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;

