per.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 文件夹加密(带密码)(可破解)/// &lt;/summary&gt;/// &lt;param name=&quot;strFolderPath&quot;&gt;文件夹路径&lt;/param&gt;/// &lt;param name=&quot;strClsid&quot;&gt;Clsid类型&lt;/param&gt;/// &lt;param name=&quot;strPassword&quot;&gt;加密密码&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool FolderEncrypt(string strFolderPath, string strClsid, string strPassword)&#123;    try    &#123;        DirectoryInfo directoryInfo = new DirectoryInfo(strFolderPath);        XmlDocument xmlDocument = new XmlDocument();        XmlNode xmlNode = xmlDocument.CreateNode(XmlNodeType.XmlDeclaration, &quot;&quot;, &quot;&quot;);        xmlDocument.AppendChild(xmlNode);        XmlElement xmlElement = xmlDocument.CreateElement(&quot;&quot;, &quot;ROOT&quot;, &quot;&quot;);        XmlText xmlText = xmlDocument.CreateTextNode(strPassword);        xmlElement.AppendChild(xmlText);        xmlDocument.AppendChild(xmlElement);        xmlDocument.Save(strFolderPath + &quot;\\Lock.xml&quot;);        directoryInfo.MoveTo(directoryInfo.Parent.FullName + &quot;\\&quot; + directoryInfo.Name + strClsid);        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 文件夹解密(带密码)/// &lt;/summary&gt;/// &lt;param name=&quot;strFolderPath&quot;&gt;文件夹路径&lt;/param&gt;/// &lt;param name=&quot;strPassword&quot;&gt;加密密码&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool FolderDecrypt(string strFolderPath, string strPassword)&#123;    try    &#123;        DirectoryInfo directoryInfo = new DirectoryInfo(strFolderPath);        bool bIsPassword = false;        XmlTextReader xmlTextReader = new XmlTextReader(strFolderPath + &quot;\\Lock.xml&quot;);        while (xmlTextReader.Read())        &#123;            if (xmlTextReader.NodeType == XmlNodeType.Text)            &#123;                if (xmlTextReader.Value == strPassword)                &#123;                    bIsPassword = true;                    break;                &#125;            &#125;        &#125;        xmlTextReader.Close();        if (bIsPassword)        &#123;            File.Delete(strFolderPath + &quot;\\Lock.xml&quot;);            directoryInfo.MoveTo(strFolderPath.Substring(0, strFolderPath.LastIndexOf(&quot;.&quot;)));            return true;        &#125;        else        &#123;            return false;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;

