/// &lt;summary&gt;/// FTP服务器URL(统一资源定位符)/// &lt;/summary&gt;public static string strFTPServerURL &#123; get; set; &#125;/// &lt;summary&gt;/// FTP服务器IP地址/// &lt;/summary&gt;public static string strFTPServerIP &#123; get; set; &#125;/// &lt;summary&gt;/// FTP服务器端口号/// &lt;/summary&gt;public static string strFTPServerPort &#123; get; set; &#125;/// &lt;summary&gt;/// FTP服务器路径/// &lt;/summary&gt;public static string strFTPServerPath &#123; get; set; &#125;/// &lt;summary&gt;/// FTP服务器用户名/// &lt;/summary&gt;public static string strFTPServerUserID &#123; get; set; &#125;/// &lt;summary&gt;/// FTP服务器用户密码/// &lt;/summary&gt;public static string strFTPServerPassword &#123; get; set; &#125;/// &lt;summary&gt;  /// 实现了文件传输协议(FTP)客户端/// &lt;/summary&gt;  FtpWebRequest Request = null;/// &lt;summary&gt;/// FTP连接URL/// &lt;/summary&gt;/// &lt;param name=&quot;FTPServerURL&quot;&gt;FTP服务器URL(统一资源定位符)&lt;/param&gt;/// &lt;param name=&quot;FTPServerUserID&quot;&gt;FTP服务器用户名&lt;/param&gt;/// &lt;param name=&quot;FTPServerPassword&quot;&gt;FTP服务器用户密码&lt;/param&gt;public void FTPConnectionURL(string FTPServerURL, string FTPServerUserID, string FTPServerPassword)&#123;    strFTPServerURL = FTPServerURL;    strFTPServerUserID = FTPServerUserID;    strFTPServerPassword = FTPServerPassword;&#125;/// &lt;summary&gt;/// FTP连接URL/// &lt;/summary&gt;/// &lt;param name=&quot;FTPServerIP&quot;&gt;FTP服务器IP地址&lt;/param&gt;/// &lt;param name=&quot;FTPServerPort&quot;&gt;FTP服务器端口号&lt;/param&gt;/// &lt;param name=&quot;FTPServerPath&quot;&gt;FTP服务器路径&lt;/param&gt;/// &lt;param name=&quot;FTPServerUserID&quot;&gt;FTP服务器用户名&lt;/param&gt;/// &lt;param name=&quot;FTPServerPassword&quot;&gt;FTP服务器用户密码&lt;/param&gt;public void FTPConnectionURL(string FTPServerIP, string FTPServerPort, string FTPServerPath, string FTPServerUserID, string FTPServerPassword)&#123;    strFTPServerIP = FTPServerIP;    strFTPServerPort = FTPServerPort;    strFTPServerPath = FTPServerPath;    strFTPServerUserID = FTPServerUserID;    strFTPServerPassword = FTPServerPassword;    strFTPServerURL = &quot;ftp://&quot; + strFTPServerIP + &quot;:&quot; + strFTPServerPort + &quot;/&quot; + strFTPServerPath + &quot;/&quot;;&#125;/// &lt;summary&gt;/// 获得URL路径下文件列表/// &lt;/summary&gt;/// &lt;returns&gt;文件列表List&lt;/returns&gt;public List&lt;string&gt; GetFilesDetailList()&#123;    try    &#123;        List&lt;string&gt; listAllFiles = new List&lt;string&gt;();        Request = (FtpWebRequest)FtpWebRequest.Create(new Uri(strFTPServerURL));        Request.Credentials = new NetworkCredential(strFTPServerUserID, strFTPServerPassword);        Request.Method = WebRequestMethods.Ftp.ListDirectoryDetails;        WebResponse Response = Request.GetResponse();        StreamReader Reader = new StreamReader(Response.GetResponseStream());        string strLine = Reader.ReadLine();        while (strLine != null)        &#123;            if (AnalysisLISTCommand(strLine).FileType == &quot;-&quot;)            &#123;                listAllFiles.Add(AnalysisLISTCommand(strLine).FileName);            &#125;            strLine = Reader.ReadLine();        &#125;        Reader.Close();        Response.Close();        return listAllFiles;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 获得URL路径下文件夹列表/// &lt;/summary&gt;/// &lt;returns&gt;文件列表List&lt;/returns&gt;public List&lt;string&gt; GetFoldersDetailList()&#123;    try    &#123;        List&lt;string&gt; listAllFiles = new List&lt;string&gt;();        Request = (FtpWebRequest)FtpWebRequest.Create(new Uri(strFTPServerURL));        Request.Credentials = new NetworkCredential(strFTPServerUserID, strFTPServerPassword);        Request.Method = WebRequestMethods.Ftp.ListDirectoryDetails;        WebResponse Response = Request.GetResponse();        StreamReader Reader = new StreamReader(Response.GetResponseStream());        string strLine = Reader.ReadLine();        while (strLine != null)        &#123;            if (AnalysisLISTCommand(strLine).FileType == &quot;d&quot;)            &#123;                listAllFiles.Add(AnalysisLISTCommand(strLine).FileName);            &#125;            strLine = Reader.ReadLine();        &#125;        Reader.Close();        Response.Close();        return listAllFiles;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 获得指定URL路径下指定文件属性/// &lt;/summary&gt;/// &lt;param name=&quot;strFileName&quot;&gt;URL中指定文件名&lt;/param&gt;/// &lt;returns&gt;FTP-FTP-LIST命令返回参数数据模型,失败返回NULL&lt;/returns&gt;public FTPListTypeModel GetFolderOrFileType(string strFileName)&#123;    try    &#123;        FtpWebRequest fRequest = (FtpWebRequest)FtpWebRequest.Create(new Uri(strFTPServerURL + strFileName));        fRequest.Credentials = new NetworkCredential(strFTPServerUserID, strFTPServerPassword);        fRequest.Method = WebRequestMethods.Ftp.ListDirectoryDetails;        FtpWebResponse Response = (FtpWebResponse)fRequest.GetResponse();        Stream ftpStream = Response.GetResponseStream();        StreamReader Reader = new StreamReader(ftpStream);        string strLine = Reader.ReadLine();        Reader.Close();        Response.Close();        return AnalysisLISTCommand(strLine);    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 新建URL路径下文件夹/// &lt;/summary&gt;/// &lt;param name=&quot;strFolderName&quot;&gt;文件夹名称&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public bool CreateFolder(string strFolderName)&#123;    try    &#123;        Request = (FtpWebRequest)FtpWebRequest.Create(new Uri(strFTPServerURL + strFolderName));        Request.Method = WebRequestMethods.Ftp.MakeDirectory;        Request.UseBinary = true;        Request.Credentials = new NetworkCredential(strFTPServerUserID, strFTPServerPassword);        FtpWebResponse response = (FtpWebResponse)Request.GetResponse();        Stream ftpStream = response.GetResponseStream();        ftpStream.Close();        response.Close();        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 删除URL路径下指定文件/// &lt;/summary&gt;/// &lt;param name=&quot;strFileName&quot;&gt;URL中指定文件名&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public bool DeleteFile(string strFileName)&#123;    try    &#123;        Request = (FtpWebRequest)FtpWebRequest.Create(new Uri(strFTPServerURL + strFileName));        Request.Credentials = new NetworkCredential(strFTPServerUserID, strFTPServerPassword);        Request.Method = WebRequestMethods.Ftp.DeleteFile;        Request.KeepAlive = false;        FtpWebResponse Response = (FtpWebResponse)Request.GetResponse();        Stream ftpStream = Response.GetResponseStream();        ftpStream.Close();        Response.Close();        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 删除URL路径下指定文件夹/// &lt;/summary&gt;/// &lt;param name=&quot;strFolderName&quot;&gt;文件夹名&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public bool DeleteFolder(string strFolderName)&#123;    try    &#123;        Request = (FtpWebRequest)FtpWebRequest.Create(new Uri(strFTPServerURL + strFolderName));        Request.Credentials = new NetworkCredential(strFTPServerUserID, strFTPServerPassword);        Request.Method = WebRequestMethods.Ftp.RemoveDirectory;        Request.KeepAlive = false;        FtpWebResponse Response = (FtpWebResponse)Request.GetResponse();        Stream ftpStream = Response.GetResponseStream();        ftpStream.Close();        Response.Close();        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 上传文件到指定URL路径/// &lt;/summary&gt;/// &lt;param name=&quot;strFilePath&quot;&gt;需要上传的文件路径&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public bool UploadFile(string strFilePath)&#123;    try    &#123;        FileInfo fileInfo = new FileInfo(strFilePath);        Request = (FtpWebRequest)FtpWebRequest.Create(new Uri(strFTPServerURL + fileInfo.Name));        Request.Credentials = new NetworkCredential(strFTPServerUserID, strFTPServerPassword);        Request.Method = WebRequestMethods.Ftp.UploadFile;        Request.KeepAlive = false;        Request.UseBinary = true;        Request.ContentLength = fileInfo.Length;        int buffLength = 2048;        byte[] buff = new byte[buffLength];        int contentLen;        FileStream fileFtpStream = fileInfo.OpenRead();        Stream ftpStream = Request.GetRequestStream();        contentLen = fileFtpStream.Read(buff, 0, buffLength);        while (contentLen != 0)        &#123;            ftpStream.Write(buff, 0, contentLen);            contentLen = fileFtpStream.Read(buff, 0, buffLength);        &#125;        ftpStream.Close();        fileFtpStream.Close();        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 下载指定URL中的文件到指定路径/// &lt;/summary&gt;/// &lt;param name=&quot;strFilePath&quot;&gt;文件下载到的路径&lt;/param&gt;/// &lt;param name=&quot;strFileName&quot;&gt;URL中指定文件名&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public bool DownloadFile(string strFilePath, string strFileName)&#123;    try    &#123;        if (!Directory.Exists(strFilePath))        &#123;            Directory.CreateDirectory(strFilePath);        &#125;        FileStream fileStream = new FileStream(strFilePath + &quot;\\&quot; + strFileName, FileMode.Create);        Request = (FtpWebRequest)FtpWebRequest.Create(new Uri(strFTPServerURL + strFileName));        Request.Credentials = new NetworkCredential(strFTPServerUserID, strFTPServerPassword);        Request.Method = WebRequestMethods.Ftp.DownloadFile;        Request.UseBinary = true;        FtpWebResponse response = (FtpWebResponse)Request.GetResponse();        Stream ftpStream = response.GetResponseStream();        int bufferSize = 2048;        int readCount;        byte[] buffer = new byte[bufferSize];        readCount = ftpStream.Read(buffer, 0, bufferSize);        while (readCount &gt; 0)        &#123;            fileStream.Write(buffer, 0, readCount);            readCount = ftpStream.Read(buffer, 0, bufferSize);        &#125;        ftpStream.Close();        fileStream.Close();        response.Close();        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 解析FTP-LIST命令/// &lt;/summary&gt;/// &lt;param name=&quot;strListCommand&quot;&gt;FTP-LIST命令&lt;/param&gt;private FTPListTypeModel AnalysisLISTCommand(string strListCommand)&#123;    FTPListTypeModel ListType = new FTPListTypeModel();    //根据空格拆分成 9 部分    string[] strListCommandSplit = strListCommand.Split(new char[] &#123; &#x27; &#x27;, &#x27;\t&#x27; &#125;, StringSplitOptions.RemoveEmptyEntries);    //文件类型 位数(1)    ListType.FileType = strListCommandSplit[0].Substring(0, 1);    //文件属主拥有权限 位数(2-4)    ListType.UserOwnership = strListCommandSplit[0].Substring(1, 3);    //文件属主同一组用户拥有权限 位数(5-7)    ListType.GroupUserOwnership = strListCommandSplit[0].Substring(4, 3);    //其他用户拥有权限 位数(8-10)    ListType.OtherUserOwnership = strListCommandSplit[0].Substring(7, 3);    //未知参数1 (1)    ListType.UnknownParameter1 = strListCommandSplit[1];    //未知参数2 (user)    ListType.UnknownParameter2 = strListCommandSplit[2];    //未知参数3 (group)    ListType.UnknownParameter3 = strListCommandSplit[3];    //文件大小(文件夹为0)    ListType.FileSize = strListCommandSplit[4];    //文件月份    ListType.FileMonth = strListCommandSplit[5];    //文件日期    ListType.FileDay = strListCommandSplit[6];    //文件年份或时间    ListType.FileYearOrTime = strListCommandSplit[7];    //文件名称    ListType.FileName = strListCommandSplit[8];    return ListType;&#125;

应用一个同学的需求：公司是做三维模型模具的，领导要求每个人每次修改上传至FTP，然后领导每天会定时完整下载（虽然我也不理解为什么他们不用SVN或者GIT，需求是什么样的就做成什么样嘛！）。功能需求是制作一个控制台程序，通过任务计划中每天下班定时执行即可。FTP参数调用本地INI配置文件。
static void Main(string[] args)&#123;    string strPath = System.AppDomain.CurrentDomain.SetupInformation.ApplicationBase + &quot;Config.ini&quot;;    string strFTP = INIHelper.INIGetStringValue(strPath, &quot;System&quot;, &quot;FTP&quot;, &quot;&quot;);    string strUser = INIHelper.INIGetStringValue(strPath, &quot;System&quot;, &quot;User&quot;, &quot;&quot;);    string strPassword = INIHelper.INIGetStringValue(strPath, &quot;System&quot;, &quot;Password&quot;, &quot;&quot;);    string strSavePath = INIHelper.INIGetStringValue(strPath, &quot;System&quot;, &quot;SavePath&quot;, &quot;&quot;);    FTPSharingHelper ftp = new FTPSharingHelper();    ftp.FTPConnectionURL(strFTP, strUser, strPassword);    DownloadFile(ftp, strFTP, strUser, strPassword, strSavePath);&#125;/// &lt;summary&gt;/// 下载目录所有文件/// &lt;/summary&gt;/// &lt;param name=&quot;ftp&quot;&gt;FTP链接&lt;/param&gt;/// &lt;param name=&quot;strFTP&quot;&gt;链接地址&lt;/param&gt;/// &lt;param name=&quot;strUser&quot;&gt;用户名&lt;/param&gt;/// &lt;param name=&quot;strPassword&quot;&gt;密码&lt;/param&gt;/// &lt;param name=&quot;strSavePath&quot;&gt;保存路径&lt;/param&gt;public static void DownloadFile(FTPSharingHelper ftp, string strFTP, string strUser, string strPassword, string strSavePath)&#123;    try    &#123;        ftp.FTPConnectionURL(strFTP, strUser, strPassword);        //下载当前目录文件        List&lt;string&gt; list1 = ftp.GetFilesDetailList();        if (list1 != null)        &#123;            foreach (var item in list1)            &#123;                ftp.DownloadFile(strSavePath, item);            &#125;        &#125;        //下载文件夹文件        List&lt;string&gt; list2 = ftp.GetFoldersDetailList();        if (list2 != null)        &#123;            foreach (var item in list2)            &#123;                if (item.Substring(0, 1).Equals(&quot;.&quot;))                &#123;                    continue;                &#125;                string strNewFTP = strFTP + item + &quot;/&quot;;                string strNewSavePath = strSavePath + &quot;\\&quot; + item;                if (!Directory.Exists(strNewSavePath))                &#123;                    Directory.CreateDirectory(strNewSavePath);                &#125;                DownloadFile(ftp, strNewFTP, strUser, strPassword, strNewSavePath);            &#125;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());    &#125;&#125;

基于 Win32 API 与 CMD 命令制作可视化文件共享工具简介不论是工作使用或是平时经常会出现两台电脑网线直连拷贝文件的情况（通过外网传输速度会受带宽限制，飞秋这种局域网聊天软件需要两台电脑同时安装，硬件存储设备需要拷贝两次，Ftp需要搭建环境，所以大部分情况下文件共享还是最好的解决方案），但是就像我这种对系统比较熟悉的人，每次操作也要找一会，与其记住命令不如做出一个可视化界面。
核心代码FileSharingHelper
/// &lt;summary&gt;/// 读取共享文件信息/// &lt;/summary&gt;/// &lt;returns&gt;共享信息DataTable(&#x27;name&#x27;:&#x27;共享文件名称&#x27;,&#x27;path&#x27;:&#x27;共享文件路径&#x27;,&#x27;permissions&#x27;:&#x27;访问控制权限&#x27;,&#x27;type&#x27;:&#x27;共享文件属性&#x27;)&lt;/returns&gt;public static DataTable InquireShareFile()&#123;    try    &#123;        ManagementObjectSearcher searcher = new ManagementObjectSearcher(&quot;select * from win32_share&quot;);        DataTable ShareFile = new DataTable();        ShareFile.Columns.Add(&quot;name&quot;);        ShareFile.Columns.Add(&quot;path&quot;);        ShareFile.Columns.Add(&quot;permissions&quot;);        ShareFile.Columns.Add(&quot;type&quot;);        foreach (ManagementObject share in searcher.Get())        &#123;            try            &#123;                //获取共享文件信息                string name = share[&quot;Name&quot;].ToString();                string path = share[&quot;Path&quot;].ToString();                string type = share[&quot;Type&quot;].ToString();                if (type == &quot;0&quot;)                &#123; type = &quot;磁盘驱动器&quot;; &#125;                else if (type == &quot;1&quot;)                &#123; type = &quot;打印队列&quot;; &#125;                else if (type == &quot;2&quot;)                &#123; type = &quot;设备&quot;; &#125;                else if (type == &quot;3&quot;)                &#123; type = &quot;IPC&quot;; &#125;                else if (type == &quot;2147483648&quot;)                &#123; type = &quot;磁盘驱动器管理&quot;; &#125;                else if (type == &quot;2147483649&quot;)                &#123; type = &quot;打印队列管理&quot;; &#125;                else if (type == &quot;2147483650&quot;)                &#123; type = &quot;设备管理&quot;; &#125;                else if (type == &quot;2147483651&quot;)                &#123; type = &quot;IPC 管理员&quot;; &#125;                //获得共享文件访问权限(通过cmd搜索)                string Permissions = &quot;&quot;;                string cmd = string.Format(&quot;net share &#123;0&#125;&quot;, name);                string strOutput = ImplementationCMD(cmd);                if (strOutput.IndexOf(&quot;FULL&quot;) &gt; -1)                &#123; Permissions = &quot;完全控制&quot;; &#125;                else if (strOutput.IndexOf(&quot;READ&quot;) &gt; -1)                &#123; Permissions = &quot;只读&quot;; &#125;                else if (strOutput.IndexOf(&quot;CHANGE&quot;) &gt; -1)                &#123; Permissions = &quot;读取/写入&quot;; &#125;                //数据写入DataTable                DataRow dr = ShareFile.NewRow();                dr[&quot;name&quot;] = name;                dr[&quot;path&quot;] = path;                dr[&quot;permissions&quot;] = Permissions;                dr[&quot;type&quot;] = type;                ShareFile.Rows.Add(dr);            &#125;            catch (Exception ex)            &#123;                TXTHelper.Logs(ex.ToString());                return null;            &#125;        &#125;        return ShareFile;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 新增共享/// &lt;/summary&gt;/// &lt;param name=&quot;FolderPath&quot;&gt;共享文件路径&lt;/param&gt;/// &lt;param name=&quot;ShareName&quot;&gt;共享文件名称&lt;/param&gt;/// &lt;param name=&quot;Permissions&quot;&gt;访问控制权限(&#x27;完全控制&#x27;:&#x27;FULL&#x27;,&#x27;只读&#x27;:&#x27;READ&#x27;,&#x27;读取/写入&#x27;:&#x27;CHANGE&#x27;)&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool AddShareFolder(string FolderPath, string ShareName, string Permissions)&#123;    try    &#123;        //输入命令NET SHARE sharename=drive:path [/GRANT:user,[READ | CHANGE | FULL]        string cmd = string.Format(@&quot;net share &#123;0&#125;=&#123;1&#125; /grant:&#123;2&#125;,&#123;3&#125;&quot;, ShareName, FolderPath, System.Environment.UserName, Permissions);        string strOutput = ImplementationCMD(cmd);        return strOutput.IndexOf(&quot;共享成功&quot;) &gt; -1 ? true : false;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 新增共享/// &lt;/summary&gt;/// &lt;param name=&quot;FolderPath&quot;&gt;共享文件路径&lt;/param&gt;/// &lt;param name=&quot;ShareName&quot;&gt;共享文件名称&lt;/param&gt;/// &lt;param name=&quot;PermissionsType&quot;&gt;访问控制权限(枚举)&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool AddShareFolder(string FolderPath, string ShareName, SharingPermissions.PermissionsType PermissionsType)&#123;    try    &#123;        //输入命令NET SHARE sharename=drive:path [/GRANT:user,[READ | CHANGE | FULL]        string cmd = string.Format(@&quot;net share &#123;0&#125;=&#123;1&#125; /grant:&#123;2&#125;,&#123;3&#125;&quot;, ShareName, FolderPath, System.Environment.UserName, PermissionsType);        string strOutput = ImplementationCMD(cmd);        return strOutput.IndexOf(&quot;共享成功&quot;) &gt; -1 ? true : false;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 删除共享/// &lt;/summary&gt;/// &lt;param name=&quot;FolderPath&quot;&gt;共享文件夹路径&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool DeleteShareFolder(string FolderPath)&#123;    try    &#123;        //输入命令NET SHARE sharename \\computername /DELETE        string cmd = string.Format(@&quot;net share &#123;0&#125; /delete /y&quot;, FolderPath);        string strOutput = ImplementationCMD(cmd);        return strOutput.IndexOf(&quot;已经删除&quot;) &gt; -1 ? true : false;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 执行CMD命令/// &lt;/summary&gt;/// &lt;param name=&quot;cmd&quot;&gt;cmd命令&lt;/param&gt;/// &lt;returns&gt;cmd窗口的输出信息&lt;/returns&gt;private static string ImplementationCMD(string cmd)&#123;    try    &#123;        //使用cmd命令对文件共享进行操作        System.Diagnostics.Process p = new System.Diagnostics.Process();        p.StartInfo.FileName = &quot;cmd.exe&quot;;        //是否使用操作系统shell启动        p.StartInfo.UseShellExecute = false;        //接受来自调用程序的输入信息        p.StartInfo.RedirectStandardInput = true;        //由调用程序获取输出信息        p.StartInfo.RedirectStandardOutput = true;        //重定向标准错误输出        p.StartInfo.RedirectStandardError = true;        //不显示程序窗口        p.StartInfo.CreateNoWindow = true;        //启动程序        p.Start();        //执行CMD命令        p.StandardInput.WriteLine(cmd);        p.StandardInput.AutoFlush = true;        p.StandardInput.WriteLine(&quot;exit&quot;);        //获取cmd窗口的输出信息        string strOutput = p.StandardOutput.ReadToEnd();        p.WaitForExit();//等待程序执行完退出进程        p.Close();        return strOutput;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;

WPF 多国语言开发与配置
简介配置 WPF 客户端多国语言，并在设置中允许切换语言。WPF 的标准做法为创建专门用于语言切换的资源字典，使用 &lt;System:String &#x2F;&gt; 标签创建。
代码创建 Language 文件夹做为语言存放目录，资源字典命名以语言缩写命名。英文：&#x2F;Language&#x2F;en-US.xaml中文：&#x2F;Language&#x2F;zh-CN.xaml
资源字典&lt;ResourceDictionary xmlns=&quot;http://schemas.microsoft.com/winfx/2006/xaml/presentation&quot;                    xmlns:x=&quot;http://schemas.microsoft.com/winfx/2006/xaml&quot;                    xmlns:System =&quot;clr-namespace:System;assembly=mscorlib&quot;&gt;    &lt;System:String x:Key=&quot;Save&quot;&gt;Save&lt;/System:String&gt;    &lt;System:String x:Key=&quot;Close&quot;&gt;Close&lt;/System:String&gt;    &lt;System:String x:Key=&quot;Exit&quot;&gt;Exit&lt;/System:String&gt;    &lt;System:String x:Key=&quot;OK&quot;&gt;OK&lt;/System:String&gt;    &lt;System:String x:Key=&quot;Yes&quot;&gt;Yes&lt;/System:String&gt;    &lt;System:String x:Key=&quot;No&quot;&gt;No&lt;/System:String&gt;    &lt;System:String x:Key=&quot;Cancel&quot;&gt;Cancel&lt;/System:String&gt;&lt;/ResourceDictionary&gt;

&lt;ResourceDictionary xmlns=&quot;http://schemas.microsoft.com/winfx/2006/xaml/presentation&quot;                    xmlns:x=&quot;http://schemas.microsoft.com/winfx/2006/xaml&quot;                    xmlns:System =&quot;clr-namespace:System;assembly=mscorlib&quot;&gt;    &lt;System:String x:Key=&quot;Save&quot;&gt;保存&lt;/System:String&gt;    &lt;System:String x:Key=&quot;Close&quot;&gt;取消&lt;/System:String&gt;    &lt;System:String x:Key=&quot;Exit&quot;&gt;退出&lt;/System:String&gt;    &lt;System:String x:Key=&quot;OK&quot;&gt;确定&lt;/System:String&gt;    &lt;System:String x:Key=&quot;Yes&quot;&gt;是&lt;/System:String&gt;    &lt;System:String x:Key=&quot;No&quot;&gt;否&lt;/System:String&gt;    &lt;System:String x:Key=&quot;Cancel&quot;&gt;取消&lt;/System:String&gt;&lt;/ResourceDictionary&gt;

引用资源在全局资源(App.xaml)中引用语言配置文件资源样式按顺序加载，标签重复的后加载覆盖先加载的，所以可以移除样式后新增，达到运行中修改语言的目的。
&lt;Application&gt;    &lt;Application.Resources&gt;                &lt;ResourceDictionary Source=&quot;/Window;component/Language/en-US.xaml&quot;/&gt;        &lt;ResourceDictionary Source=&quot;/Window;component/Language/zh-CN.xaml&quot;/&gt;    &lt;/Application.Resources&gt;&lt;/Application&gt;

切换语言private static List&lt;LanguageModel&gt; _listLanguage;/// &lt;summary&gt;/// 语言资源集合/// &lt;/summary&gt;public static List&lt;LanguageModel&gt; ListLanguage&#123;    get    &#123;        if (_listLanguage == null)        &#123;            _listLanguage = new List&lt;LanguageModel&gt;();            _listLanguage.Add(new LanguageModel() &#123; FileName = &quot;en-US&quot;, Language = &quot;English&quot;, Resource = new ResourceDictionary() &#123; Source = new Uri(&quot;/Window;component/Language/en-US.xaml&quot;, UriKind.RelativeOrAbsolute) &#125; &#125;);            _listLanguage.Add(new LanguageModel() &#123; FileName = &quot;zh-CN&quot;, Language = &quot;简体中文&quot;, Resource = new ResourceDictionary() &#123; Source = new Uri(&quot;/Window;component/Language/zh-CN.xaml&quot;, UriKind.RelativeOrAbsolute) &#125; &#125;);        &#125;        return _listLanguage;    &#125;    set    &#123;        _listLanguage = value;    &#125;&#125;/// &lt;summary&gt;/// 设置语言/// &lt;/summary&gt;/// &lt;param name=&quot;language&quot;&gt;&lt;/param&gt;public static void SetLanguage(string language = null)&#123;    // 把要修改的语言放置资源最后    List&lt;ResourceDictionary&gt; dictionaryList = new List&lt;ResourceDictionary&gt;();    foreach (ResourceDictionary dictionary in Application.Current.Resources.MergedDictionaries)    &#123;        dictionaryList.Add(dictionary);    &#125;    if (string.IsNullOrEmpty(language))    &#123;        var vSystemConfigInfo_Language = GetSystemConfigInfo(SECTION_SYSTEM, SYSTEM_LANGUAGE);        foreach (var item in ListLanguage)        &#123;            if (item.FileName.Equals(vSystemConfigInfo_Language))            &#123;                language = item.Resource.Source.OriginalString;                break;            &#125;        &#125;    &#125;    if (!string.IsNullOrEmpty(language))    &#123;        var resourceDictionary = dictionaryList.FirstOrDefault(o =&gt; o.Source.OriginalString.Equals(language));        if (resourceDictionary != null)        &#123;            Application.Current.Resources.BeginInit();            Application.Current.Resources.MergedDictionaries.Remove(resourceDictionary);            Application.Current.Resources.MergedDictionaries.Add(resourceDictionary);            Application.Current.Resources.EndInit();        &#125;    &#125;&#125;

调用// 初始化SetLanguage();// 切换英文SetLanguage(&quot;/Window;component/Language/en-US.xaml&quot;);// 切换简体中文SetLanguage(&quot;/Window;component/Language/zh-CN.xaml&quot;);

Kafka 消息队列帮助类使用介绍
简介Kafka Demo 写了关于 Kafka 的基础介绍与官方提供的最简生产者与消费者的 Demo，完善代码封装为帮助类。
核心代码KafkaHelper
/// &lt;summary&gt;/// Kafka 消息队列帮助类/// 创建日期:2023年10月25日/// &lt;/summary&gt;public class KafkaHelper&#123;    private string _bootstrapServers;    Action&lt;DeliveryReport&lt;Null, string&gt;&gt; _handler;    private IProducer&lt;Null, string&gt; _producerBuilder;    /// &lt;summary&gt;    /// 消息回调    /// &lt;/summary&gt;    public event Action&lt;string&gt; MessageCallback;    /// &lt;summary&gt;    /// 构造函数    /// &lt;/summary&gt;    /// &lt;param name=&quot;bootstrapServers&quot;&gt;服务地址&lt;/param&gt;    public KafkaHelper(string bootstrapServers)    &#123;        // 127.0.0.1:9092        _bootstrapServers = bootstrapServers;    &#125;    /// &lt;summary&gt;    /// 注册生产者    /// &lt;/summary&gt;    public void RegisterProducer()    &#123;        var conf = new ProducerConfig &#123; BootstrapServers = _bootstrapServers &#125;;        _handler = r =&gt; Console.WriteLine(!r.Error.IsError            ? $&quot;Delivered message to &#123;r.TopicPartitionOffset&#125;&quot;            : $&quot;Delivery Error: &#123;r.Error.Reason&#125;&quot;);        _producerBuilder = new ProducerBuilder&lt;Null, string&gt;(conf).Build();    &#125;    /// &lt;summary&gt;    /// 注册消费者    /// &lt;/summary&gt;    /// &lt;param name=&quot;groupId&quot;&gt;消费组&lt;/param&gt;    /// &lt;param name=&quot;topic&quot;&gt;主题&lt;/param&gt;    /// &lt;param name=&quot;autoOffsetReset&quot;&gt;消费偏移量&lt;/param&gt;    /// &lt;param name=&quot;kafkaSSL&quot;&gt;SSL 验证&lt;/param&gt;    public void RegisterConsumer(string groupId, string topic, AutoOffsetReset autoOffsetReset = AutoOffsetReset.Earliest, KafkaSSL kafkaSSL = null)    &#123;        var conf = new ConsumerConfig        &#123;            GroupId = groupId,            BootstrapServers = _bootstrapServers,            // Note: The AutoOffsetReset property determines the start offset in the event            // there are not yet any committed offsets for the consumer group for the            // topic/partitions of interest. By default, offsets are committed            // automatically, so in this example, consumption will only start from the            // earliest message in the topic &#x27;my-topic&#x27; the first time you run the program.            AutoOffsetReset = autoOffsetReset        &#125;;        // 如果 Kafka 开启了 SSL 验证，则需要填写以下信息，否则删除        if (kafkaSSL != null)        &#123;            conf.SecurityProtocol = kafkaSSL.SecurityProtocol;            conf.SaslMechanism = kafkaSSL.SaslMechanism;            conf.SaslUsername = kafkaSSL.SaslUsername;            conf.SaslPassword = kafkaSSL.SaslPassword;            conf.SslCaLocation = kafkaSSL.SslCaLocation;            conf.SslKeystorePassword = kafkaSSL.SslKeystorePassword;            conf.SslEndpointIdentificationAlgorithm = kafkaSSL.SslEndpointIdentificationAlgorithm;        &#125;        using (var c = new ConsumerBuilder&lt;Ignore, string&gt;(conf).Build())        &#123;            c.Subscribe(topic);            CancellationTokenSource cts = new CancellationTokenSource();            Console.CancelKeyPress += (_, e) =&gt;            &#123;                e.Cancel = true; // prevent the process from terminating.                cts.Cancel();            &#125;;            try            &#123;                while (true)                &#123;                    try                    &#123;                        var cr = c.Consume(cts.Token);                        //Console.WriteLine($&quot;Consumed message &#x27;&#123;cr.Value&#125;&#x27; at: &#x27;&#123;cr.TopicPartitionOffset&#125;&#x27;.&quot;);                        MessageCallback?.Invoke(cr.Value);                    &#125;                    catch (ConsumeException e)                    &#123;                        Console.WriteLine($&quot;Error occured: &#123;e.Error.Reason&#125;&quot;);                    &#125;                &#125;            &#125;            catch (OperationCanceledException)            &#123;                // Ensure the consumer leaves the group cleanly and final offsets are committed.                c.Close();            &#125;        &#125;    &#125;    /// &lt;summary&gt;    /// 发送消息    /// &lt;/summary&gt;    public void SendMessage(string topic, string message)    &#123;        _producerBuilder.Produce(topic, new Message&lt;Null, string&gt; &#123; Value = message &#125;, _handler);        // wait for up to 10 seconds for any inflight messages to be delivered.        _producerBuilder.Flush(TimeSpan.FromSeconds(10));    &#125;    /// &lt;summary&gt;    /// 关闭连接    /// &lt;/summary&gt;    public void Close()    &#123;        _producerBuilder.Dispose();    &#125;&#125;/// &lt;summary&gt;/// Kafka SSL 验证/// &lt;/summary&gt;public class KafkaSSL&#123;    /// &lt;summary&gt;    /// Protocol used to communicate with brokers. default: plaintext importance: high    /// &lt;/summary&gt;    public SecurityProtocol? SecurityProtocol &#123; get; set; &#125; = Confluent.Kafka.SecurityProtocol.SaslSsl;    /// &lt;summary&gt;    /// SASL mechanism to use for authentication. Supported: GSSAPI, PLAIN, SCRAM-SHA-256,    /// SCRAM-SHA-512. **NOTE**: Despite the name, you may not configure more than one    /// mechanism.    /// &lt;/summary&gt;    public SaslMechanism? SaslMechanism &#123; get; set; &#125; = Confluent.Kafka.SaslMechanism.Plain;    /// &lt;summary&gt;    /// SASL username for use with the PLAIN and SASL-SCRAM-.. mechanisms default: &#x27;&#x27;    /// importance: high    /// &lt;/summary&gt;    public string SaslUsername &#123; get; set; &#125;    /// &lt;summary&gt;    /// SASL password for use with the PLAIN and SASL-SCRAM-.. mechanism default: &#x27;&#x27;    /// importance: high    /// &lt;/summary&gt;    public string SaslPassword &#123; get; set; &#125;    /// &lt;summary&gt;    /// File or directory path to CA certificate(s) for verifying the broker&#x27;s key. Defaults:    /// On Windows the system&#x27;s CA certificates are automatically looked up in the Windows    /// Root certificate store. On Mac OSX this configuration defaults to `probe`. It    /// is recommended to install openssl using Homebrew, to provide CA certificates.    /// On Linux install the distribution&#x27;s ca-certificates package. If OpenSSL is statically    /// linked or `ssl.ca.location` is set to `probe` a list of standard paths will be    /// probed and the first one found will be used as the default CA certificate location    /// path. If OpenSSL is dynamically linked the OpenSSL library&#x27;s default path will    /// be used (see `OPENSSLDIR` in `openssl version -a`). default: &#x27;&#x27; importance: low    /// &lt;/summary&gt;    public string SslCaLocation &#123; get; set; &#125;    /// &lt;summary&gt;    /// Client&#x27;s keystore (PKCS#12) password. default: &#x27;&#x27; importance: low    /// &lt;/summary&gt;    public string SslKeystorePassword &#123; get; set; &#125;    /// &lt;summary&gt;    /// Endpoint identification algorithm to validate broker hostname using broker certificate.    /// https - Server (broker) hostname verification as specified in RFC2818. none -    /// No endpoint verification. OpenSSL &gt;= 1.0.2 required. default: https importance:    /// low    /// &lt;/summary&gt;    public SslEndpointIdentificationAlgorithm? SslEndpointIdentificationAlgorithm &#123; get; set; &#125;&#125;

调用测试生产者static void Main(string[] args)&#123;    // 服务地址    string bootstrapServers = &quot;127.0.0.1:9092&quot;;    // 主题    string topic;    KafkaHelper kafkaHelper = new KafkaHelper(bootstrapServers);    kafkaHelper.RegisterProducer();        while (true)    &#123;        kafkaHelper.SendMessage(topic, $&quot;&#123;DateTime.Now&#125;&quot;);        Task.Delay(TimeSpan.FromMilliseconds(500)).Wait();    &#125;&#125;

消费者static void Main(string[] args)&#123;    // 服务地址    string bootstrapServers = &quot;127.0.0.1:9092&quot;;    // 主题    string topic;    // 消费组    string group;    KafkaHelper kafkaHelper = new KafkaHelper(bootstrapServers);    kafkaHelper.MessageCallback += KafkaHelper_MessageCallback;    Task.Run(() =&gt;    &#123;        kafkaHelper.RegisterConsumer(group, topic);    &#125;);&#125;/// &lt;summary&gt;/// 队列消息回调/// &lt;/summary&gt;/// &lt;param name=&quot;message&quot;&gt;&lt;/param&gt;private static void KafkaHelper_MessageCallback(string obj)&#123;    Console.WriteLine(obj);&#125;

消费者（SSL 验证）static void Main(string[] args)&#123;    // 服务地址    string bootstrapServers = &quot;127.0.0.1:9092&quot;;    // 主题    string topic;    // 消费组    string group;    KafkaHelper kafkaHelper = new KafkaHelper(bootstrapServers);    kafkaHelper.MessageCallback += KafkaHelper_MessageCallback;    Task.Run(() =&gt;    &#123;        KafkaSSL kafkaSSL = new KafkaSSL();        kafkaSSL.SecurityProtocol = SecurityProtocol.SaslSsl;        kafkaSSL.SaslMechanism = SaslMechanism.Plain;        kafkaSSL.SaslUsername = &quot;xxx&quot;;        kafkaSSL.SaslPassword = &quot;xxx&quot;;        kafkaSSL.SslCaLocation = &quot;phy_ca.crt&quot;;        kafkaSSL.SslKeystorePassword = &quot;dms@kafka&quot;;        kafkaSSL.SslEndpointIdentificationAlgorithm = null;        kafkaHelper.RegisterConsumer(group, topic, kafkaSSL: kafkaSSL);    &#125;);&#125;/// &lt;summary&gt;/// 队列消息回调/// &lt;/summary&gt;/// &lt;param name=&quot;message&quot;&gt;&lt;/param&gt;private static void KafkaHelper_MessageCallback(string obj)&#123;    Console.WriteLine(obj);&#125;

使用 NPOI&#x2F;DocX 二次封装Office（Word、Excel）帮助类
简介工作中需要大量生成导出报表或合同证书文件，原理为使用Excel或Word模板，批量替换标签以达到效果。
设计由于原类库都属于基础方法，二次封装后具有更简易的使用方式，可直接传入生成的数据集或标签替换集合。
引用库介绍由于微软默认推荐的类库 Microsoft.Office.Interop.Word 与 Microsoft.Office.Interop.Excel 需要电脑安装 Microsoft Office 并引用COM组件才可以使用（已知调用打印机需引用COM组件），所以选用类库可独立于Office组件，在任意一台电脑也可以运行。NPOI：POI Java项目的.NET版本。可以非常轻松地读&#x2F;写Office 2003&#x2F;2007文件。DocX：DocX是一个.NET库，允许开发人员以简单直观的方式操作Word文件。
Excel文件操作ExcelHelper提供创建文件（2003&#x2F;2007）及Sheet分页创建编辑，读取Excel文件至内存DataSet及反向DataSet保存至Excel文件。仅显示最外层引用方法，详细调用请在帮助类种查看！
/// &lt;summary&gt;/// Excel所有分页转换为DataSet/// &lt;/summary&gt;/// &lt;param name=&quot;strDataSourcePath&quot;&gt;Excel文件路径&lt;/param&gt;/// &lt;returns&gt;成功返回Excel的DataSet,失败返回NULL&lt;/returns&gt;public static DataSet ExcelConversionDataSet(string strDataSourcePath)&#123;    try    &#123;        if (string.IsNullOrEmpty(strDataSourcePath) || !File.Exists(strDataSourcePath))        &#123;            return null;        &#125;        DataSet dsTargetData = new DataSet();        Dictionary&lt;int, string&gt; dicAllSheet = GetExcelAllSheet(strDataSourcePath);        foreach (var vAllSheet in dicAllSheet)        &#123;            DataTable dtTargetData = new DataTable();            dtTargetData.TableName = vAllSheet.Value;            dtTargetData = ExcelConversionDataTable(strDataSourcePath, vAllSheet.Value);            if (dtTargetData == null)            &#123;                continue;            &#125;            dsTargetData.Tables.Add(dtTargetData);        &#125;        return dsTargetData;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;

/// &lt;summary&gt;/// DataSet转换为Excel/// 存在文件则新建DataTableName的分页(如果分页名冲突则或为空则使用默认名称)/// 不存在文件则新建(Excel,名称为DataTableName,如果没有则使用默认名称)/// &lt;/summary&gt;/// &lt;param name=&quot;strDataSourcePath&quot;&gt;Excel文件路径&lt;/param&gt;/// &lt;param name=&quot;dsSourceData&quot;&gt;DataTable数据&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool DataSetConversionExcel(string strDataSourcePath, DataSet dsSourceData)&#123;    try    &#123;        if (string.IsNullOrEmpty(strDataSourcePath) || dsSourceData.Tables.Count &lt; 1)        &#123;            return false;        &#125;        foreach (DataTable dtSourceData in dsSourceData.Tables)        &#123;            Dictionary&lt;int, string&gt; dicAllSheet = GetExcelAllSheet(strDataSourcePath);            string strTableName = string.IsNullOrEmpty(dtSourceData.TableName) ? string.Format(&quot;Sheet&#123;0&#125;&quot;, dicAllSheet.Count + 1) : dtSourceData.TableName;            if (dicAllSheet.ContainsValue(dtSourceData.TableName))            &#123;                RemoveExcelSheet(strDataSourcePath, dtSourceData.TableName);            &#125;            if (!FillDataTable(strDataSourcePath, strTableName, dtSourceData, true, 0, 0))            &#123;                return false;            &#125;        &#125;        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;

根据公司项目需要，把多个Excel的Sheet页的内容及样式合并为一个文件，Microsoft.Office.Interop.Excel提供拷贝分页方法，但是需要安装Microsoft Office，所以用NPOI类库实现了一个拷贝方法。
/// &lt;summary&gt;/// 拷贝Sheet页到另一个Sheet页/// &lt;/summary&gt;/// &lt;param name=&quot;strSourceExcelPath&quot;&gt;源Excel路径&lt;/param&gt;/// &lt;param name=&quot;strFromSheetName&quot;&gt;源Excel拷贝Sheet&lt;/param&gt;/// &lt;param name=&quot;strTargetExcelPath&quot;&gt;目标Excel路径&lt;/param&gt;/// &lt;param name=&quot;strToSheetName&quot;&gt;目标Excel拷贝Sheet&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool CopySheet(string strSourceExcelPath, string strFromSheetName, string strTargetExcelPath, string strToSheetName)&#123;    try    &#123;        if (string.IsNullOrEmpty(strSourceExcelPath) || string.IsNullOrEmpty(strTargetExcelPath) || !File.Exists(strSourceExcelPath))        &#123;            TXTHelper.Logs(string.Format(&quot;源数据和目标数据参数为空或文件不存在!&quot;));            return false;        &#125;        if (string.IsNullOrEmpty(strFromSheetName) || string.IsNullOrEmpty(strToSheetName))        &#123;            TXTHelper.Logs(string.Format(&quot;源Sheet页和目标Sheet页参数为空!&quot;));            return false;        &#125;        //获得源数据和目标数据的Sheet页        IWorkbook iSourceWorkbook = null;        ISheet iSourceSheet = GetExcelSheetAt(strSourceExcelPath, strFromSheetName, out iSourceWorkbook);        IWorkbook iTargetWorkbook = null;        ISheet iTargetSheet = null;        if (iSourceSheet == null)        &#123;            TXTHelper.Logs(string.Format(&quot;指定源数据Sheet页为空!&quot;));            return false;        &#125;        if (!File.Exists(strTargetExcelPath))        &#123;            //如果文件不存在则创建Excel            if (System.IO.Path.GetExtension(strTargetExcelPath) == &quot;.xls&quot;)            &#123;                bool bCreare = CreateExcel_Office2003(strTargetExcelPath, strToSheetName);            &#125;            else if (System.IO.Path.GetExtension(strTargetExcelPath) == &quot;.xlsx&quot;)            &#123;                bool bCreare = CreateExcel_Office2007(strTargetExcelPath, strToSheetName);            &#125;            else            &#123;                TXTHelper.Logs(string.Format(&quot;指定目标Excel文件路径格式错误!&quot;));                return false;            &#125;            iTargetSheet = GetExcelSheetAt(strTargetExcelPath, strToSheetName, out iTargetWorkbook);        &#125;        else        &#123;            //如果文件存在则判断是否存在执行Sheet            Dictionary&lt;int, string&gt; dicAllSheet = GetExcelAllSheet(strTargetExcelPath);            if (dicAllSheet.ContainsValue(strToSheetName))            &#123;                iTargetSheet = GetExcelSheetAt(strTargetExcelPath, strToSheetName, out iTargetWorkbook);            &#125;            else            &#123;                iTargetSheet = CreateExcelSheetAt(strTargetExcelPath, strToSheetName, out iTargetWorkbook);            &#125;        &#125;        //调用Sheet拷贝Sheet方法        bool bCopySheet = CopySheetAt(iSourceWorkbook, iSourceSheet, iTargetWorkbook, iTargetSheet);        if (bCopySheet)        &#123;            if (System.IO.Path.GetExtension(strTargetExcelPath) == &quot;.xls&quot;)            &#123;                FileStream fileStream2003 = new FileStream(Path.ChangeExtension(strTargetExcelPath, &quot;xls&quot;), FileMode.Create);                iTargetWorkbook.Write(fileStream2003);                fileStream2003.Close();                iTargetWorkbook.Close();            &#125;            else if (System.IO.Path.GetExtension(strTargetExcelPath) == &quot;.xlsx&quot;)            &#123;                FileStream fileStream2007 = new FileStream(Path.ChangeExtension(strTargetExcelPath, &quot;xlsx&quot;), FileMode.Create);                iTargetWorkbook.Write(fileStream2007);                fileStream2007.Close();                iTargetWorkbook.Close();            &#125;            return true;        &#125;        else        &#123;            TXTHelper.Logs(string.Format(&quot;拷贝失败!&quot;));            return false;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;

// &lt;summary&gt;/// 拷贝Sheet页到另一个Sheet页(浅拷贝,不提供保存方法)/// Office2003单Sheet页仅支持4000个样式/// &lt;/summary&gt;/// &lt;param name=&quot;iSourceWorkbook&quot;&gt;源Excel工作簿&lt;/param&gt;/// &lt;param name=&quot;iFromSheet&quot;&gt;源Sheet页&lt;/param&gt;/// &lt;param name=&quot;iTargetWorkbook&quot;&gt;目标Excel工作簿&lt;/param&gt;/// &lt;param name=&quot;iToSheet&quot;&gt;目标Sheet页&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool CopySheetAt(IWorkbook iSourceWorkbook, ISheet iFromSheet, IWorkbook iTargetWorkbook, ISheet iToSheet)&#123;    try    &#123;        //拷贝数据        DataTable dtExcelFromData = GetDataTable(iFromSheet, false, 0, 0, 0, 0);        iToSheet = FillDataTable(iToSheet, dtExcelFromData, false, 0, 0);        //拷贝单元格合并        for (int iMergedRegions = 0; iMergedRegions &lt; iFromSheet.NumMergedRegions; iMergedRegions++)        &#123;            iToSheet.AddMergedRegion(iFromSheet.GetMergedRegion(iMergedRegions));        &#125;        //拷贝样式(遍历Sheet页行)        List&lt;ICellStyle&gt; listCellStyle = new List&lt;ICellStyle&gt;();        for (int iRowNum = 0; iRowNum &lt;= iFromSheet.LastRowNum; iRowNum++)        &#123;            IRow iFromRowData = iFromSheet.GetRow(iRowNum);            IRow iToRowData = iToSheet.GetRow(iRowNum);            if (iFromRowData == null || iToRowData == null)            &#123;                continue;            &#125;            //设置行高            short sFromHeight = iFromRowData.Height;            iToRowData.Height = sFromHeight;            //遍历Sheet页列            for (int iRowCell = 0; iRowCell &lt;= iFromRowData.LastCellNum; iRowCell++)            &#123;                //设置列宽                int iFromColumnWidth = iFromSheet.GetColumnWidth(iRowNum) / 256;                iToSheet.SetColumnWidth(iRowNum, iFromColumnWidth * 256);                //复制数据                ICell iFromCell = iFromRowData.GetCell(iRowCell);                if (iFromCell != null)                &#123;                    //获得源Sheet页的样式                    ICellStyle iFromCellStyle = iFromCell.CellStyle;                    //获得目标Excel指定Cell                    ICell iToCell = iToRowData.GetCell(iRowCell);                    if (iToCell == null) continue;                    #region 复制单元格样式                    //指定Cell创新目标Excel工作簿新样式                    ICellStyle iToNewCellStyle = null;                    foreach (ICellStyle vCellStyle in listCellStyle)                    &#123;                        IFont iVToFont = vCellStyle.GetFont(iTargetWorkbook);                        IFont iFromFont = iFromCellStyle.GetFont(iSourceWorkbook);                        if (vCellStyle.Alignment == iFromCellStyle.Alignment &amp;&amp;                            vCellStyle.BorderBottom == iFromCellStyle.BorderBottom &amp;&amp;                            vCellStyle.BorderLeft == iFromCellStyle.BorderLeft &amp;&amp;                            vCellStyle.BorderRight == iFromCellStyle.BorderRight &amp;&amp;                            vCellStyle.BorderTop == iFromCellStyle.BorderTop &amp;&amp;                            vCellStyle.BottomBorderColor == iFromCellStyle.BottomBorderColor &amp;&amp;                            vCellStyle.DataFormat == iFromCellStyle.DataFormat &amp;&amp;                            vCellStyle.FillBackgroundColor == iFromCellStyle.FillBackgroundColor &amp;&amp;                            vCellStyle.FillForegroundColor == iFromCellStyle.FillForegroundColor &amp;&amp;                            vCellStyle.FillPattern == iFromCellStyle.FillPattern &amp;&amp;                            vCellStyle.Indention == iFromCellStyle.Indention &amp;&amp;                            vCellStyle.IsHidden == iFromCellStyle.IsHidden &amp;&amp;                            vCellStyle.IsLocked == iFromCellStyle.IsLocked &amp;&amp;                            vCellStyle.LeftBorderColor == iFromCellStyle.LeftBorderColor &amp;&amp;                            vCellStyle.RightBorderColor == iFromCellStyle.RightBorderColor &amp;&amp;                            vCellStyle.Rotation == iFromCellStyle.Rotation &amp;&amp;                            vCellStyle.TopBorderColor == iFromCellStyle.TopBorderColor &amp;&amp;                            vCellStyle.VerticalAlignment == iFromCellStyle.VerticalAlignment &amp;&amp;                            vCellStyle.WrapText == iFromCellStyle.WrapText &amp;&amp;                            //字体比对                            iVToFont.Color == iFromFont.Color &amp;&amp;                            iVToFont.FontHeightInPoints == iFromFont.FontHeightInPoints &amp;&amp;                            iVToFont.FontName == iFromFont.FontName &amp;&amp;                            iVToFont.IsBold == iFromFont.IsBold &amp;&amp;                            iVToFont.IsItalic == iFromFont.IsItalic &amp;&amp;                            iVToFont.IsStrikeout == iFromFont.IsStrikeout &amp;&amp;                            iVToFont.Underline == iFromFont.Underline)                        &#123;                            iToNewCellStyle = vCellStyle;                            break;                        &#125;                    &#125;                    if (iToNewCellStyle == null)                    &#123;                        //创建新样式                        iToNewCellStyle = iTargetWorkbook.CreateCellStyle();                        //复制样式                        iToNewCellStyle.Alignment = iFromCellStyle.Alignment;//对齐                        iToNewCellStyle.BorderBottom = iFromCellStyle.BorderBottom;//下边框                        iToNewCellStyle.BorderLeft = iFromCellStyle.BorderLeft;//左边框                        iToNewCellStyle.BorderRight = iFromCellStyle.BorderRight;//右边框                        iToNewCellStyle.BorderTop = iFromCellStyle.BorderTop;//上边框                        iToNewCellStyle.BottomBorderColor = iFromCellStyle.BottomBorderColor;//下边框颜色                        iToNewCellStyle.DataFormat = iFromCellStyle.DataFormat;//数据格式                        iToNewCellStyle.FillBackgroundColor = iFromCellStyle.FillBackgroundColor;//填充背景色                        iToNewCellStyle.FillForegroundColor = iFromCellStyle.FillForegroundColor;//填充前景色                        iToNewCellStyle.FillPattern = iFromCellStyle.FillPattern;//填充图案                        iToNewCellStyle.Indention = iFromCellStyle.Indention;//压痕                        iToNewCellStyle.IsHidden = iFromCellStyle.IsHidden;//隐藏                        iToNewCellStyle.IsLocked = iFromCellStyle.IsLocked;//锁定                        iToNewCellStyle.LeftBorderColor = iFromCellStyle.LeftBorderColor;//左边框颜色                        iToNewCellStyle.RightBorderColor = iFromCellStyle.RightBorderColor;//右边框颜色                        iToNewCellStyle.Rotation = iFromCellStyle.Rotation;//旋转                        iToNewCellStyle.TopBorderColor = iFromCellStyle.TopBorderColor;//上边框颜色                        iToNewCellStyle.VerticalAlignment = iFromCellStyle.VerticalAlignment;//垂直对齐                        iToNewCellStyle.WrapText = iFromCellStyle.WrapText;//文字换行                        //复制字体                        IFont iFromFont = iFromCellStyle.GetFont(iSourceWorkbook);                        IFont iToFont = iTargetWorkbook.CreateFont();                        iToFont.Color = iFromFont.Color;//颜色                        iToFont.FontHeightInPoints = iFromFont.FontHeightInPoints;//字号                        iToFont.FontName = iFromFont.FontName;//字体                        iToFont.IsBold = iFromFont.IsBold;//加粗                        iToFont.IsItalic = iFromFont.IsItalic;//斜体                        iToFont.IsStrikeout = iFromFont.IsStrikeout;//删除线                        iToFont.Underline = iFromFont.Underline;//下划线                        iToNewCellStyle.SetFont(iToFont);                        //保存到缓存集合中                        listCellStyle.Add(iToNewCellStyle);                    &#125;                    //复制样式到指定表格中                    iToCell.CellStyle = iToNewCellStyle;                    #endregion                &#125;            &#125;        &#125;        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;

Word文件操作WordHelper提供创建文件（2003&#x2F;2007）及替换段落表格标签（匹配替换’{标签}’,’#标签#’），替换图片功能。仅显示最外层引用方法，详细调用请在帮助类种查看！
/// &lt;summary&gt;/// 替换文本标签/// &lt;/summary&gt;/// &lt;param name=&quot;strDataSourcePath&quot;&gt;Word文件路径&lt;/param&gt;/// &lt;param name=&quot;strLabelName&quot;&gt;标签名称(带标签符号)&lt;/param&gt;/// &lt;param name=&quot;strReplaceLabel&quot;&gt;替换标签文本&lt;/param&gt;/// &lt;returns&gt;成功返回替换数量,失败返回-1&lt;/returns&gt;public static int ReplaceTextLabel(string strDataSourcePath, string strLabelName, string strReplaceLabel)&#123;    try    &#123;        if (string.IsNullOrEmpty(strDataSourcePath) || !File.Exists(strDataSourcePath) || string.IsNullOrEmpty(strLabelName) || string.IsNullOrEmpty(strReplaceLabel))        &#123;            return -1;        &#125;        int iNumber = 0;        FileStream fileStreamOpen = new FileStream(strDataSourcePath, FileMode.Open, FileAccess.Read);        XWPFDocument wordDocument = new XWPFDocument(fileStreamOpen);        foreach (XWPFParagraph wordParagraph in wordDocument.Paragraphs)        &#123;            if (wordParagraph.ParagraphText.IndexOf(strLabelName) &gt;= 0)            &#123;                string strReplaceTextLabel = wordParagraph.ParagraphText.Replace(strLabelName, strReplaceLabel);                foreach (XWPFRun wordRun in wordParagraph.Runs)                &#123;                    wordRun.SetText(string.Empty, 0);                &#125;                wordParagraph.CreateRun().SetText(strReplaceTextLabel, 0);                iNumber++;            &#125;        &#125;        foreach (XWPFTable wordTable in wordDocument.Tables)        &#123;            foreach (XWPFTableRow wordTableRow in wordTable.Rows)            &#123;                foreach (XWPFTableCell wordTableCell in wordTableRow.GetTableCells())                &#123;                    foreach (XWPFParagraph wordParagraph in wordTableCell.Paragraphs)                    &#123;                        if (wordParagraph.ParagraphText.IndexOf(strLabelName) &gt;= 0)                        &#123;                            string strReplaceTextLabel = wordParagraph.ParagraphText.Replace(strLabelName, strReplaceLabel);                            foreach (XWPFRun wordRun in wordParagraph.Runs)                            &#123;                                wordRun.SetText(string.Empty, 0);                            &#125;                            wordParagraph.CreateRun().SetText(strReplaceTextLabel, 0);                            iNumber++;                        &#125;                    &#125;                &#125;            &#125;        &#125;        FileStream fileStreamSave = new FileStream(strDataSourcePath, FileMode.Create);        wordDocument.Write(fileStreamSave);        fileStreamSave.Close();        wordDocument.Close();        return iNumber;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return -1;    &#125;&#125;

/// &lt;summary&gt;/// 替换表格标签(DataTable替换)/// &lt;/summary&gt;/// &lt;param name=&quot;strDataSourcePath&quot;&gt;Word文件路径&lt;/param&gt;/// &lt;param name=&quot;strLabelName&quot;&gt;标签名称(带标签符号)&lt;/param&gt;/// &lt;param name=&quot;dtReplaceLabel&quot;&gt;替换标签DataTable&lt;/param&gt;/// &lt;returns&gt;成功返回1,失败返回-1&lt;/returns&gt;public static int ReplaceDataTableLabel(string strDataSourcePath, string strLabelName, DataTable dtReplaceLabel)&#123;    try    &#123;        if (string.IsNullOrEmpty(strDataSourcePath) || !File.Exists(strDataSourcePath) || string.IsNullOrEmpty(strLabelName) || dtReplaceLabel == null || dtReplaceLabel.Rows.Count &lt; 1)        &#123;            return -1;        &#125;        FileStream fileStreamOpen = new FileStream(strDataSourcePath, FileMode.Open, FileAccess.Read);        XWPFDocument wordDocument = new XWPFDocument(fileStreamOpen);        int iLableRowPosition = -1;        int iLableCellPosition = -1;        foreach (XWPFTable wordTable in wordDocument.Tables)        &#123;            for (int iTableRow = 0; iTableRow &lt; wordTable.Rows.Count; iTableRow++)            &#123;                for (int iTableCell = 0; iTableCell &lt; wordTable.Rows[iTableRow].GetTableCells().Count; iTableCell++)                &#123;                    foreach (XWPFParagraph wordParagraph in wordTable.Rows[iTableRow].GetTableCells()[iTableCell].Paragraphs)                    &#123;                        if (wordParagraph.ParagraphText.IndexOf(strLabelName) &gt;= 0)                        &#123;                            if (iLableRowPosition &lt; 0 &amp;&amp; iLableCellPosition &lt; 0)                            &#123;                                iLableRowPosition = iTableRow;                                iLableCellPosition = iTableCell;                            &#125;                        &#125;                        if (iLableRowPosition &gt;= 0 &amp;&amp; iLableCellPosition &gt;= 0)                        &#123;                            int iCurrentRow = iTableRow - iLableRowPosition;                            int iCurrentCell = iTableCell - iLableCellPosition;                            if ((iCurrentRow &lt; dtReplaceLabel.Rows.Count &amp;&amp; iCurrentRow &gt;= 0) &amp;&amp; (iCurrentCell &lt; dtReplaceLabel.Columns.Count &amp;&amp; iCurrentCell &gt;= 0))                            &#123;                                foreach (XWPFRun wordRun in wordParagraph.Runs)                                &#123;                                    wordRun.SetText(string.Empty, 0);                                &#125;                                wordParagraph.CreateRun().SetText(dtReplaceLabel.Rows[iCurrentRow][iCurrentCell].ToString(), 0);                            &#125;                        &#125;                    &#125;                &#125;            &#125;        &#125;        FileStream fileStreamSave = new FileStream(strDataSourcePath, FileMode.Create);        wordDocument.Write(fileStreamSave);        fileStreamSave.Close();        wordDocument.Close();        return 1;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return -1;    &#125;&#125;

/// &lt;summary&gt;/// 替换图片标签(使用DocX.dll类库,调用这个方法后NPOI无法读取文档)/// &lt;/summary&gt;/// &lt;param name=&quot;strDataSourcePath&quot;&gt;Word文件路径&lt;/param&gt;/// &lt;param name=&quot;strLabelName&quot;&gt;标签名称(带标签符号)&lt;/param&gt;/// &lt;param name=&quot;strImagePath&quot;&gt;替换的图片路径&lt;/param&gt;/// &lt;param name=&quot;iImageWidth&quot;&gt;替换的图片宽度(小于0则显示原图宽度)&lt;/param&gt;/// &lt;param name=&quot;iImageHeight&quot;&gt;替换的图片高度(小于0则显示原图高度)&lt;/param&gt;/// &lt;returns&gt;成功返回替换数量,失败返回-1&lt;/returns&gt;public static int ReplaceImageLabel(string strDataSourcePath, string strLabelName, string strImagePath, int iImageWidth, int iImageHeight)&#123;    try    &#123;        if (string.IsNullOrEmpty(strDataSourcePath) || !File.Exists(strDataSourcePath) || string.IsNullOrEmpty(strLabelName) || string.IsNullOrEmpty(strImagePath) || !File.Exists(strImagePath))        &#123;            return -1;        &#125;        int iNumber = 0;        //使用DocX.dll类库        DocX mDocX = DocX.Load(strDataSourcePath);        //遍历段落        foreach (Paragraph wordParagraph in mDocX.Paragraphs)        &#123;            if (wordParagraph.Text.IndexOf(strLabelName) &gt;= 0)            &#123;                //添加图片                Novacode.Image pImag = mDocX.AddImage(strImagePath);                Picture pPicture = pImag.CreatePicture();                //如果传入宽度小于0,则以原始大小插入                if (iImageWidth &gt;= 0)                &#123;                    pPicture.Width = iImageWidth;                &#125;                //如果传入高度小于0,则以原始大小插入                if (iImageHeight &gt;= 0)                &#123;                    pPicture.Height = iImageHeight;                &#125;                //将图像插入到段落后面                wordParagraph.InsertPicture(pPicture);                //清空文本(清空放在前面会导致替换失败文字消失)                wordParagraph.ReplaceText(strLabelName, string.Empty);                iNumber++;            &#125;        &#125;        mDocX.SaveAs(strDataSourcePath);        return iNumber;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return -1;    &#125;&#125;

服务端以内存方式导出 Excel 并设置自动列宽
简介基于 NPOI&#x2F;DOCX 帮助类 修改，在服务端导出 Excel 应尽量直接在内存中处理，减少磁盘写入，同时实现设置自动列宽。
代码帮助类修改基于帮助类中 FillDataTable 方法修改
/// &lt;summary&gt;/// 设置自动列宽/// &lt;/summary&gt;/// &lt;param name=&quot;sheet&quot;&gt;&lt;/param&gt;/// &lt;param name=&quot;cols&quot;&gt;&lt;/param&gt;public static void AutoColumnWidth(ISheet sheet, int cols)&#123;    for (int col = 0; col &lt;= cols; col++)    &#123;        //获取当前列宽度        int columnWidth = sheet.GetColumnWidth(col) / 256;        for (int rowIndex = 0; rowIndex &lt;= sheet.LastRowNum; rowIndex++)        &#123;            IRow row = sheet.GetRow(rowIndex);            ICell cell = row.GetCell(col);            //获取当前单元格的内容宽度            int contextLength = Encoding.UTF8.GetBytes(cell.ToString()).Length;            columnWidth = columnWidth &lt; contextLength ? contextLength : columnWidth;        &#125;        sheet.SetColumnWidth(col, columnWidth * 256);    &#125;&#125;/// &lt;summary&gt;/// 在指定Excel中指定Sheet指定位置填充DataTable/// 在内存中处理/// &lt;/summary&gt;/// &lt;param name=&quot;strSheetName&quot;&gt;需要填充的Sheet名称(如果没有则添加,如果冲突则使用冲突Sheet)&lt;/param&gt;/// &lt;param name=&quot;dtSourceData&quot;&gt;DataTable数据&lt;/param&gt;/// &lt;param name=&quot;WhetherThereFieldName&quot;&gt;是否有列名(true保留DataTable字段名)&lt;/param&gt;/// &lt;param name=&quot;iRows&quot;&gt;起始行&lt;/param&gt;/// &lt;param name=&quot;iColumn&quot;&gt;起始列&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static MemoryStream FillDataTableStream(string strSheetName, DataTable dtSourceData, bool WhetherThereFieldName, int iRows, int iColumn)&#123;    try    &#123;        if (string.IsNullOrEmpty(strSheetName) || dtSourceData.Rows.Count &lt; 1)        &#123;            return null;        &#125;        IWorkbook iWorkBook = new XSSFWorkbook();        ISheet iSheet = iWorkBook.CreateSheet(strSheetName);        if (WhetherThereFieldName)        &#123;            IRow rowDataTableField = iSheet.CreateRow(iRows);            for (int iDataTableColumns = 0; iDataTableColumns &lt; dtSourceData.Columns.Count; iDataTableColumns++)            &#123;                ICell cellErrstatist = rowDataTableField.CreateCell(iDataTableColumns + iColumn);                cellErrstatist.SetCellValue(dtSourceData.Columns[iDataTableColumns].ColumnName);            &#125;            for (int iDataTableRows = 0; iDataTableRows &lt; dtSourceData.Rows.Count; iDataTableRows++)            &#123;                IRow rowDataTable = iSheet.CreateRow(iDataTableRows + iRows + 1);                for (int iDataTableColumns = 0; iDataTableColumns &lt; dtSourceData.Columns.Count; iDataTableColumns++)                &#123;                    ICell cellErrstatist = rowDataTable.CreateCell(iDataTableColumns + iColumn);                    string strSourceData = dtSourceData.Rows[iDataTableRows][iDataTableColumns].ToString();                    Regex regexIsNumeric = new Regex(@&quot;^(-?\d+)(\.\d+)?$&quot;);                    if (regexIsNumeric.IsMatch(strSourceData))                    &#123;                        cellErrstatist.SetCellValue(double.Parse(strSourceData));                    &#125;                    else                    &#123;                        cellErrstatist.SetCellValue(strSourceData);                    &#125;                &#125;                AutoColumnWidth(iSheet, dtSourceData.Columns.Count - 1);            &#125;        &#125;        else        &#123;            for (int iDataTableRows = 0; iDataTableRows &lt; dtSourceData.Rows.Count; iDataTableRows++)            &#123;                IRow rowDataTable = iSheet.CreateRow(iDataTableRows + iRows);                for (int iDataTableColumns = 0; iDataTableColumns &lt; dtSourceData.Columns.Count; iDataTableColumns++)                &#123;                    ICell cellErrstatist = rowDataTable.CreateCell(iDataTableColumns + iColumn);                    string strSourceData = dtSourceData.Rows[iDataTableRows][iDataTableColumns].ToString();                    Regex regexIsNumeric = new Regex(@&quot;^(-?\d+)(\.\d+)?$&quot;);                    if (regexIsNumeric.IsMatch(strSourceData))                    &#123;                        cellErrstatist.SetCellValue(double.Parse(strSourceData));                    &#125;                    else                    &#123;                        cellErrstatist.SetCellValue(strSourceData);                    &#125;                &#125;            &#125;        &#125;        MemoryStream stream = new MemoryStream();        iWorkBook.Write(stream, false);        iWorkBook.Close();        return stream;    &#125;    catch (Exception ex)    &#123;        return null;    &#125;&#125;

