基于 ZXing.QrCode 库制作的横条码&#x2F;二维码生成识别工具简介二维码（QR Code码） 在现在生活中十分常见，扫一扫即可付款。原本想要学习一下二维码原理自己造轮子，后来还是决定站在巨人的肩膀上使用Google的开源库ZXing来生成和识别二维码&#x2F;横条码。
帮助类QRCodeHelper 帮助类提供二维码生成，带LOGO二维码，以及图像识别功能。
/// &lt;summary&gt;/// 注销对象方法API/// &lt;/summary&gt;[DllImport(&quot;gdi32&quot;)]private static extern int DeleteObject(IntPtr o);/// &lt;summary&gt;/// 生成二维码/// &lt;/summary&gt;/// &lt;param name=&quot;strContent&quot;&gt;二维码文本&lt;/param&gt;/// &lt;param name=&quot;iWidth&quot;&gt;二维码宽度&lt;/param&gt;/// &lt;param name=&quot;iHeigth&quot;&gt;二维码高度&lt;/param&gt;/// &lt;returns&gt;二维码位图&lt;/returns&gt;public static Bitmap GetQRCode(string strContent, int iWidth, int iHeigth)&#123;    try    &#123;        //构造二维码写码器        MultiFormatWriter writer = new MultiFormatWriter();        Dictionary&lt;EncodeHintType, object&gt; hint = new Dictionary&lt;EncodeHintType, object&gt;();        hint.Add(EncodeHintType.CHARACTER_SET, &quot;UTF-8&quot;);        hint.Add(EncodeHintType.ERROR_CORRECTION, ErrorCorrectionLevel.H);        hint.Add(EncodeHintType.MARGIN, 1);        //生成二维码         BitMatrix bitMatrix = writer.encode(strContent, BarcodeFormat.QR_CODE, iWidth, iHeigth, hint);        BarcodeWriter barcodeWriter = new BarcodeWriter();        Bitmap bitmapQRCode = barcodeWriter.Write(bitMatrix);        //获取二维码实际尺寸(去掉二维码两边空白后的实际尺寸)        int[] rectangle = bitMatrix.getEnclosingRectangle();        //将img转换成bmp格式，否则后面无法创建Graphics对象        Bitmap bitmapQRCodeBMP = new Bitmap(bitmapQRCode.Width, bitmapQRCode.Height, System.Drawing.Imaging.PixelFormat.Format32bppArgb);        using (Graphics g = Graphics.FromImage(bitmapQRCodeBMP))        &#123;            g.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;            g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.HighQuality;            g.CompositingQuality = System.Drawing.Drawing2D.CompositingQuality.HighQuality;            g.DrawImage(bitmapQRCode, 0, 0);        &#125;        return bitmapQRCodeBMP;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 生成二维码(带LOGO)/// &lt;/summary&gt;/// &lt;param name=&quot;strContent&quot;&gt;二维码文本&lt;/param&gt;/// &lt;param name=&quot;iWidth&quot;&gt;二维码宽度&lt;/param&gt;/// &lt;param name=&quot;iHeigth&quot;&gt;二维码高度&lt;/param&gt;/// &lt;param name=&quot;strLogoPath&quot;&gt;LOGO图片路径&lt;/param&gt;/// &lt;returns&gt;二维码位图&lt;/returns&gt;public static Bitmap GetQRCode_logo(string strContent, int iWidth, int iHeigth, string strLogoPath)&#123;    try    &#123;        //构造二维码写码器        MultiFormatWriter writer = new MultiFormatWriter();        Dictionary&lt;EncodeHintType, object&gt; hint = new Dictionary&lt;EncodeHintType, object&gt;();        hint.Add(EncodeHintType.CHARACTER_SET, &quot;UTF-8&quot;);        hint.Add(EncodeHintType.ERROR_CORRECTION, ErrorCorrectionLevel.H);        hint.Add(EncodeHintType.MARGIN, 1);        //生成二维码         BitMatrix bitMatrix = writer.encode(strContent, BarcodeFormat.QR_CODE, iWidth, iHeigth, hint);        BarcodeWriter barcodeWriter = new BarcodeWriter();        Bitmap bitmapQRCode = barcodeWriter.Write(bitMatrix);        //获取二维码实际尺寸(去掉二维码两边空白后的实际尺寸)        int[] rectangle = bitMatrix.getEnclosingRectangle();        //将img转换成bmp格式，否则后面无法创建Graphics对象        Bitmap bitmapQRCodeBMP = new Bitmap(bitmapQRCode.Width, bitmapQRCode.Height, System.Drawing.Imaging.PixelFormat.Format32bppArgb);        using (Graphics g = Graphics.FromImage(bitmapQRCodeBMP))        &#123;            g.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;            g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.HighQuality;            g.CompositingQuality = System.Drawing.Drawing2D.CompositingQuality.HighQuality;            g.DrawImage(bitmapQRCode, 0, 0);        &#125;        //获得LOGO位图并计算插入图片的大小和位置        Bitmap bitmapLogo = new Bitmap(strLogoPath);        int middleW = Math.Min((int)(rectangle[2] / 3.5), bitmapLogo.Width);        int middleH = Math.Min((int)(rectangle[3] / 3.5), bitmapLogo.Height);        int middleL = (bitmapQRCode.Width - middleW) / 2;        int middleT = (bitmapQRCode.Height - middleH) / 2;        //将二维码插入图片(白底)        Graphics myGraphic = Graphics.FromImage(bitmapQRCodeBMP);        myGraphic.DrawImage(bitmapLogo, middleL, middleT, middleW, middleH);        return bitmapQRCodeBMP;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 从位图获取图像源/// &lt;/summary&gt;/// &lt;param name=&quot;bitmapQRCode&quot;&gt;位图二维码&lt;/param&gt;/// &lt;returns&gt;图像源(用以显示在控件上)&lt;/returns&gt;public static ImageSource GetImageSourceFromBitmap(Bitmap bitmapQRCode)&#123;    try    &#123;        IntPtr ipQRCode = bitmapQRCode.GetHbitmap();        BitmapSource bitmapSource = System.Windows.Interop.Imaging.CreateBitmapSourceFromHBitmap(ipQRCode, IntPtr.Zero, Int32Rect.Empty, System.Windows.Media.Imaging.BitmapSizeOptions.FromEmptyOptions());        DeleteObject(ipQRCode);        return bitmapSource;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 识别二维码和条形码/// &lt;/summary&gt;/// &lt;param name=&quot;bitmapQRCode&quot;&gt;二维码和条形码位图&lt;/param&gt;/// &lt;returns&gt;成功返回二维码和条形码内容,失败返回NULL或Empty&lt;/returns&gt;public static string BarcodeReader(Bitmap bitmapQRCode)&#123;    try    &#123;        BarcodeReader barcodeReader = new BarcodeReader();        barcodeReader.Options.CharacterSet = &quot;UTF-8&quot;;        Result resultQRCode = barcodeReader.Decode(bitmapQRCode);        if (resultQRCode == null)        &#123;            return string.Empty;        &#125;        else        &#123;            return resultQRCode.Text;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 识别二维码和条形码/// &lt;/summary&gt;/// &lt;param name=&quot;strQRCodePath&quot;&gt;二维码和条形码文件路径&lt;/param&gt;/// &lt;returns&gt;成功返回二维码和条形码内容,失败返回NULL或Empty&lt;/returns&gt;public static string BarcodeReader(string strQRCodePath)&#123;    try    &#123;        BarcodeReader barcodeReader = new BarcodeReader();        barcodeReader.Options.CharacterSet = &quot;UTF-8&quot;;        Bitmap bitmapQRCode = new Bitmap(strQRCodePath);        Result resultQRCode = barcodeReader.Decode(bitmapQRCode);        if (resultQRCode == null)        &#123;            return string.Empty;        &#125;        else        &#123;            return resultQRCode.Text;        &#125;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 保存二维码和条形码位图到指定位置/// &lt;/summary&gt;/// &lt;param name=&quot;strSavePath&quot;&gt;文件保存位置&lt;/param&gt;/// &lt;param name=&quot;bitmapQRCode&quot;&gt;二维码和条形码位图&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool SaveBitmap(string strSavePath, Bitmap bitmapQRCode)&#123;    try    &#123;        ImageFormat imageFormat;        switch (System.IO.Path.GetExtension(strSavePath))        &#123;            case &quot;.bmp&quot;: imageFormat = ImageFormat.Bmp; break;            case &quot;.emf&quot;: imageFormat = ImageFormat.Emf; break;            case &quot;.exif&quot;: imageFormat = ImageFormat.Exif; break;            case &quot;.gif&quot;: imageFormat = ImageFormat.Gif; break;            case &quot;.icon&quot;: imageFormat = ImageFormat.Icon; break;            case &quot;.jpeg&quot;: imageFormat = ImageFormat.Jpeg; break;            case &quot;.jpg&quot;: imageFormat = ImageFormat.Jpeg; break;            case &quot;.memorybmp&quot;: imageFormat = ImageFormat.MemoryBmp; break;            case &quot;.png&quot;: imageFormat = ImageFormat.Png; break;            case &quot;.tiff&quot;: imageFormat = ImageFormat.Tiff; break;            case &quot;.wmf&quot;: imageFormat = ImageFormat.Wmf; break;            default: imageFormat = ImageFormat.Png; break;        &#125;        bitmapQRCode.Save(strSavePath, imageFormat);        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;

RabbitMQ 消息队列帮助类使用介绍
简介RabbitMQ Demo 写了关于 RabbitMQ 的基础介绍与官方提供的最简生产者与消费者的 Demo，平时都是直接使用公司同事写好的库，但是越用越觉得臃肿难以配置，所以接下来计划实现一系列队列相关的通讯帮助类。
核心代码RabbitMQHelper
/// &lt;summary&gt;/// RabbitMQ 消息队列帮助类/// &lt;/summary&gt;public class RabbitMQHelper&#123;    private IConnection _connection;    private IModel _channel;    private string _exchangeName;    /// &lt;summary&gt;    /// 消息回调    /// &lt;/summary&gt;    public event Action&lt;string&gt; MessageCallback;    /// &lt;summary&gt;    /// 构造函数    /// &lt;/summary&gt;    /// &lt;param name=&quot;hostName&quot;&gt;IP&lt;/param&gt;    /// &lt;param name=&quot;port&quot;&gt;端口号&lt;/param&gt;    /// &lt;param name=&quot;userName&quot;&gt;用户名&lt;/param&gt;    /// &lt;param name=&quot;password&quot;&gt;密码&lt;/param&gt;    public RabbitMQHelper(string hostName, int port = 5672, string userName = &quot;&quot;, string password = &quot;&quot;)    &#123;        var factory = new ConnectionFactory()        &#123;            HostName = hostName,            Port = port,            UserName = userName,            Password = password,            // 自动重连            AutomaticRecoveryEnabled = true,            // 恢复拓扑结构            TopologyRecoveryEnabled = true,            // 后台处理消息            UseBackgroundThreadsForIO = true,            // 心跳超时时间            RequestedHeartbeat = TimeSpan.FromMilliseconds(60)        &#125;;        _connection = factory.CreateConnection();        _channel = _connection.CreateModel();    &#125;    /// &lt;summary&gt;    /// 注册生产者    /// 仅声明一个交换机    /// 接收数据的人通过交换机和路由获取数据    /// &lt;/summary&gt;    /// &lt;param name=&quot;exchangeName&quot;&gt;交换机&lt;/param&gt;    /// &lt;param name=&quot;durable&quot;&gt;持久化&lt;/param&gt;    public void RegisterProducer(string exchangeName, bool durable = true)    &#123;        _exchangeName = exchangeName;        _channel.ExchangeDeclare(exchangeName, ExchangeType.Topic, durable);    &#125;    /// &lt;summary&gt;    /// 注册生产者    /// 声明交换机和队列    /// 接收数据的人可直接通过队列获取数据    /// &lt;/summary&gt;    /// &lt;param name=&quot;exchangeName&quot;&gt;交换机&lt;/param&gt;    /// &lt;param name=&quot;routingKey&quot;&gt;路由键&lt;/param&gt;    /// &lt;param name=&quot;queueName&quot;&gt;队列&lt;/param&gt;    /// &lt;param name=&quot;durable&quot;&gt;持久化&lt;/param&gt;    /// &lt;param name=&quot;autoDelete&quot;&gt;队列是否自动删除&lt;/param&gt;    /// &lt;param name=&quot;ttl&quot;&gt;生存时间&lt;/param&gt;    public void RegisterProducer(string exchangeName, string routingKey, string queueName, bool durable = true, bool autoDelete = true, TimeSpan? ttl = null)    &#123;        _exchangeName = exchangeName;        _channel.ExchangeDeclare(exchangeName, ExchangeType.Topic, durable);        var arguments = new Dictionary&lt;string, object&gt;();        if (ttl != null)        &#123;            arguments.Add(&quot;x-message-ttl&quot;, (int)ttl.Value.TotalMilliseconds);        &#125;        _channel.QueueDeclare(queueName, durable, false, autoDelete, arguments);        _channel.QueueBind(queueName, exchangeName, routingKey);    &#125;    /// &lt;summary&gt;    /// 注册消费者    /// 通过队列获取数据    /// &lt;/summary&gt;    /// &lt;param name=&quot;queueName&quot;&gt;队列名称&lt;/param&gt;    /// &lt;param name=&quot;durable&quot;&gt;持久化&lt;/param&gt;    /// &lt;param name=&quot;autoDelete&quot;&gt;队列是否自动删除&lt;/param&gt;    /// &lt;param name=&quot;ttl&quot;&gt;生存时间&lt;/param&gt;    public void RegisterConsumer(string queueName, bool durable = true, bool autoDelete = true, TimeSpan? ttl = null)    &#123;        var arguments = new Dictionary&lt;string, object&gt;();        if (ttl != null)        &#123;            arguments.Add(&quot;x-message-ttl&quot;, (int)ttl.Value.TotalMilliseconds);        &#125;        _channel.QueueDeclare(queueName, durable, false, autoDelete, arguments);        var consumer = new EventingBasicConsumer(_channel);        consumer.Received += (model, ea) =&gt;        &#123;            var body = ea.Body.ToArray();            var message = Encoding.UTF8.GetString(body);            MessageCallback?.Invoke(message);        &#125;;        _channel.BasicConsume(queue: queueName, autoAck: true, consumer: consumer);    &#125;    /// &lt;summary&gt;    /// 注册消费者    /// 通过交换机和路由获取数据    /// 自定义队列名，避免多个程序消费一份数据    /// &lt;/summary&gt;    /// &lt;param name=&quot;exchangeName&quot;&gt;队列名称&lt;/param&gt;    /// &lt;param name=&quot;routingKey&quot;&gt;路由键&lt;/param&gt;    /// &lt;param name=&quot;queueName&quot;&gt;队列名称&lt;/param&gt;    /// &lt;param name=&quot;durable&quot;&gt;持久化&lt;/param&gt;    /// &lt;param name=&quot;autoDelete&quot;&gt;队列是否自动删除&lt;/param&gt;    /// &lt;param name=&quot;ttl&quot;&gt;生存时间&lt;/param&gt;    public void RegisterConsumer(string exchangeName, string routingKey, string queueName, bool durable = true, bool autoDelete = true, TimeSpan? ttl = null)    &#123;        var arguments = new Dictionary&lt;string, object&gt;();        if (ttl != null)        &#123;            arguments.Add(&quot;x-message-ttl&quot;, (int)ttl.Value.TotalMilliseconds);        &#125;        _channel.QueueDeclare(queueName, durable, false, autoDelete, arguments);        _channel.QueueBind(queueName, exchangeName, routingKey);        var consumer = new EventingBasicConsumer(_channel);        consumer.Received += (model, ea) =&gt;        &#123;            var body = ea.Body.ToArray();            var message = Encoding.UTF8.GetString(body);            MessageCallback?.Invoke(message);        &#125;;        _channel.BasicConsume(queue: queueName, autoAck: true, consumer: consumer);    &#125;    /// &lt;summary&gt;    /// 发送消息    /// &lt;/summary&gt;    /// &lt;param name=&quot;routingKey&quot;&gt;路由键&lt;/param&gt;    /// &lt;param name=&quot;message&quot;&gt;消息&lt;/param&gt;    /// &lt;param name=&quot;persistent&quot;&gt;消息持久化&lt;/param&gt;    public void SendMessage(string routingKey, string message, bool persistent = true)    &#123;        var properties = _channel.CreateBasicProperties();        properties.Persistent = persistent;        var body = Encoding.UTF8.GetBytes(message);        _channel.BasicPublish(exchange: _exchangeName, routingKey: routingKey, basicProperties: properties, body: body);    &#125;    /// &lt;summary&gt;    /// 关闭连接    /// &lt;/summary&gt;    public void Close()    &#123;        _channel.Close();        _connection.Close();    &#125;&#125;

调用测试生产者// IPstring ip;// 端口int port;// 用户名string userName;// 密码string password;// 交换机string exchangeName;// 路由键string routingKey;// 队列名称string queueName;// 持久化bool durable = true;// 队列是否自动删除bool autoDelete = true;// 生存时间TimeSpan ttl = TimeSpan.FromDays(1);// 创建消费者 RabbitMQ 对象RabbitMQHelper _rabbitMQHelper = new RabbitMQHelper(ip, port, userName, password);// 创建一个仅声明交换机的生产者，接收数据的人通过交换机和路由获取数据_rabbitMQHelper.RegisterProducer(exchangeName, durable);// 创建一个声明交换机和队列的生产者，接收数据的人可直接通过队列获取数据_rabbitMQHelper.RegisterProducer(exchangeName, routingKey, queueName, durable, autoDelete, ttl);// 消息string message;// 发送消息_rabbitMQHelper.SendMessage(routingKey, message);

消费者// IPstring ip;// 端口int port;// 用户名string userName;// 密码string password;// 交换机string exchangeName;// 路由键string routingKey;// 队列名称string queueName;// 持久化bool durable = true;// 队列是否自动删除bool autoDelete = true;// 生存时间TimeSpan ttl = TimeSpan.FromDays(1);// 创建消费者 RabbitMQ 对象RabbitMQHelper _rabbitMQHelper = new RabbitMQHelper(ip, port, userName, password);_rabbitMQHelper.MessageCallback += RabbitMQHelper_MessageCallback;// 创建一个直接通过队列获取数据的消费者_rabbitMQHelper.RegisterConsumer(queueName, durable, autoDelete, ttl);// 创建一个通过交换机和路由获取数据的消费者，自定义队列名，避免多个程序消费一份数据_rabbitMQHelper.RegisterConsumer(exchangeName, routingKey, queueName, durable, autoDelete, ttl);/// &lt;summary&gt;/// 队列消息回调/// &lt;/summary&gt;/// &lt;param name=&quot;message&quot;&gt;&lt;/param&gt;private void RabbitMQHelper_MessageCallback(string message)&#123;    // 接收队列数据&#125;

通过反射动态调用方法
简介System.Reflection 命名空间包含通过检查托管代码中程序集、模块、成员、参数和其他实体的元数据来检索其相关信息的类型。 这些类型还可用于操作加载类型的实例，例如挂钩事件或调用方法。↑上边是微软 MSDN 的介绍，balabala一大堆…，总之反射调用它就对了，通过类库类名以及方法名称调用方法。
使用通过反射运行方法调用方法代码/// &lt;summary&gt;/// 运行方法/// &lt;/summary&gt;/// &lt;param name=&quot;strLibraryName&quot;&gt;库名&lt;/param&gt;/// &lt;param name=&quot;strClassName&quot;&gt;类名(带路径)&lt;/param&gt;/// &lt;param name=&quot;strMethodName&quot;&gt;方法名&lt;/param&gt;/// &lt;param name=&quot;parameters&quot;&gt;参数&lt;/param&gt;/// &lt;returns&gt;返回结果&lt;/returns&gt;public static object RunMethod(string strLibraryName, string strClassName, string strMethodName, object[] parameters)&#123;    try    &#123;        Type type = Type.GetType($&quot;&#123;strLibraryName&#125;.&#123;strClassName&#125;&quot;);        if (type != null)        &#123;            var vMethod = type.GetMethod(strMethodName);            if (vMethod != null)            &#123;                return vMethod.Invoke(Activator.CreateInstance(type), parameters);            &#125;        &#125;        return null;    &#125;    catch (Exception)    &#123;        return null;    &#125;&#125;

调用方法示例var parameters = new object[] &#123; item &#125;;RunMethod(&quot;ReflectionProject_Test&quot;, &quot;ClassName&quot;, &quot;MethodName&quot;, parameters);

通过反射接口插件式开发定义接口/// &lt;summary&gt;/// 菜单插件接口/// &lt;/summary&gt;public interface MenuPluginInterface&#123;    /// &lt;summary&gt;    /// 菜单单击事件    /// &lt;/summary&gt;    void Click();    /// &lt;summary&gt;    /// 功能名称    /// &lt;/summary&gt;    string strFunctionName &#123; get; &#125;    /// &lt;summary&gt;    /// 功能分组    /// &lt;/summary&gt;    string strFunctionGroup &#123; get; &#125;&#125;

插件继承接口/// &lt;summary&gt;/// 功能按钮测试Command/// &lt;/summary&gt;public class TestCommand : MenuPluginInterface&#123;    /// &lt;summary&gt;    /// Click Command    /// &lt;/summary&gt;    public void Click()    &#123;        // 打开插件功能    &#125;    /// &lt;summary&gt;    /// 功能名称    /// &lt;/summary&gt;    public string strFunctionName    &#123;        get &#123; return &quot;测试功能&quot;; &#125;    &#125;    /// &lt;summary&gt;    /// 功能分组    /// &lt;/summary&gt;    public string strFunctionGroup    &#123;        get &#123; return &quot;测试分组&quot;; &#125;    &#125;&#125;

反射方法/// &lt;summary&gt;/// 运行插件窗体/// &lt;/summary&gt;/// &lt;param name=&quot;strDllPath&quot;&gt;Dll路径&lt;/param&gt;/// &lt;param name=&quot;strClassName&quot;&gt;全类名&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool RunPluginClick(string strDllPath, string strClassName)&#123;    try    &#123;        //反射获得Class Type        Assembly assembly = Assembly.LoadFrom(strDllPath);        Type type = assembly.GetType(strClassName);        if (type != null)        &#123;            var container = new UnityContainer();            container.RegisterType&lt;MenuPluginInterface&gt;(new ContainerControlledLifetimeManager());            container.RegisterType(typeof(MenuPluginInterface), type);            var manager = container.Resolve&lt;MenuPluginInterface&gt;();            manager.Click();            return true;        &#125;        else        &#123;            return false;        &#125;    &#125;    catch (Exception)    &#123;        return false;    &#125;&#125;

通过反射打开插件string strProjectDll = &quot;ReflectionProject_Test.dll&quot;;RunPluginClick(strProjectDll, &quot;ReflectionProject_Test.TestCommand&quot;);

RocketMQ 消息队列使用介绍
简介Apache RocketMQ 是阿里巴巴开发的分布式消息中间件，后捐赠给 Apache 基金会维护。直接对接华为云，所以未在本地安装。测试对 C# 兼容不是很好，而且服务端都逐渐使用 docker 部署，所以最终选择使用 Golang 开发。
C# 代码调用官方库 rocketmq-client-csharp 的支持似乎并不好，调试了几次都运行不起来。引用第三方 NewLife.RocketMQ 库。测试不支持 ACL（权限控制），如开启 ACL 则无法连接。
生产者class Program&#123;    public static string namesvr = &quot;&quot;;    public static string topic = &quot;&quot;;    static void Main(string[] args)    &#123;        ThreadStart str = new ThreadStart(Producer);        Thread ConstrolStr = new Thread(str);        ConstrolStr.Start();    &#125;    /// &lt;summary&gt;    /// 生产者    /// &lt;/summary&gt;    /// &lt;param name=&quot;args&quot;&gt;&lt;/param&gt;    static void Producer()    &#123;        // MQ 对象        var mq = new Producer()        &#123;            // 主题            Topic = topic,            // 服务地址            NameServerAddress = namesvr,        &#125;;        mq.Start();        // 轮询发消息        while (true)        &#123;            try            &#123;                var content = $&quot;&#123;DateTime.Now&#125;&quot;;                var message = new NewLife.RocketMQ.Protocol.Message();                message.SetBody(content);                // 发送消息（生产消息）                var sr = mq.Publish(message);                Console.WriteLine($&quot;发送成功的消息，内容：&#123;content&#125;&quot;);                Task.Delay(TimeSpan.FromMilliseconds(500)).Wait();            &#125;            catch (Exception ex)            &#123;                //throw;            &#125;        &#125;    &#125;&#125;

