.BodyString&#125;&quot;);                    MessageCallback?.Invoke(item.BodyString);                &#125;                return isNotice;            &#125;        &#125;;        consumer.Start();    &#125;    /// &lt;summary&gt;    /// 发送消息    /// &lt;/summary&gt;    /// &lt;param name=&quot;message&quot;&gt;消息&lt;/param&gt;    public void SendMessage(string message)    &#123;        try        &#123;            var sr = producer.Publish(message);        &#125;        catch (Exception)        &#123;            //throw;        &#125;    &#125;    /// &lt;summary&gt;    /// 关闭连接    /// &lt;/summary&gt;    public void Close()    &#123;        producer?.Stop();        consumer?.Stop();    &#125;&#125;

