 aclSecretKey));        // 实例化一个生产者对象        producer = new DefaultMQProducer(producerGroup, rpcHook);        // 设置 Name Server 地址        producer.setNamesrvAddr(namesrv);        // 设置启用 TLS（传输层安全）        producer.setUseTLS(true);        try &#123;            // 启动生产者            producer.start();        &#125; catch (MQClientException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    /**     * 注册消费者     *     * @param consumerGroup 消费组     * @param namesrv       服务地址     * @param topic         主题     * @param tag           标签     */    public void RegisterConsumer(String consumerGroup, String namesrv, String topic, String tag) &#123;        // 实例化一个消费者对象        consumer = new DefaultMQPushConsumer(consumerGroup);        // 设置 Name Server 地址        consumer.setNamesrvAddr(namesrv);        // 设置消息监听器        consumer.registerMessageListener(new MessageListenerConcurrently() &#123;            public ConsumeConcurrentlyStatus consumeMessage(List&lt;MessageExt&gt; msgs, ConsumeConcurrentlyContext context) &#123;                for (MessageExt message : msgs) &#123;                    if (messageCallback != null) &#123;                        // 调用消息回调函数传递消息                        messageCallback.onMessageReceived(new String(message.getBody()));                    &#125;                &#125;                // 消费成功后返回状态                return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;            &#125;        &#125;);        try &#123;            // 订阅主题和标签            consumer.subscribe(topic, tag);            // 启动消费者            consumer.start();        &#125; catch (MQClientException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    /**     * 注册消费者 ACL 验证     *     * @param consumerGroup 消费组     * @param namesrv       服务地址     * @param topic         主题     * @param tag           标签     * @param aclAccessKey  Access 秘钥     * @param aclSecretKey  Secret 秘钥     */    public void RegisterConsumer(String consumerGroup, String namesrv, String topic, String tag, String aclAccessKey, String aclSecretKey) &#123;        RPCHook rpcHook = new AclClientRPCHook(new SessionCredentials(aclAccessKey, aclSecretKey));        // 实例化一个消费者对象，添加ACL权限认证，并开启消息轨迹（ConsumerGroupName-消费者组，rpcHook-ACL认证，true-消息轨迹开启）        consumer = new DefaultMQPushConsumer(null, consumerGroup, rpcHook, new AllocateMessageQueueAveragely(), true, null);        // 设置 Name Server 地址        consumer.setNamesrvAddr(namesrv);        // 设置启用 TLS（传输层安全）        consumer.setUseTLS(true);        // 设置消息监听器        consumer.registerMessageListener(new MessageListenerConcurrently() &#123;            public ConsumeConcurrentlyStatus consumeMessage(List&lt;MessageExt&gt; msgs, ConsumeConcurrentlyContext context) &#123;                for (MessageExt message : msgs) &#123;                    if (messageCallback != null) &#123;                        // 调用消息回调函数传递消息                        messageCallback.onMessageReceived(new String(message.getBody()));                    &#125;                &#125;                // 消费成功后返回状态                return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;            &#125;        &#125;);        try &#123;            // 订阅主题和标签            consumer.subscribe(topic, tag);            // 启动消费者            consumer.start();        &#125; catch (MQClientException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    /**     * 发送消息     *     * @param message 消息     * @param topic   主题     * @param tag     标签     */    public void SendMessage(String message, String topic, String tag) &#123;        try &#123;            // 发送消息            producer.send(new Message(                    topic,  // 主题                    tag,    // 标签                    message.getBytes(RemotingHelper.DEFAULT_CHARSET)  // 内容            ));        &#125; catch (Exception e) &#123;            e.printStackTrace();        &#125;    &#125;    /**     * 关闭连接     */    public void Close() &#123;        producer.sh