更新 RSA 帮助类解决加密文本长度
简介由于旧版本 RSA 帮助类 对加密的文字长度有限制，所以更新代码以加密更长的字符。
代码RSA 库依旧是基于 System.Security.Cryptography.RSA 库
/// &lt;summary&gt;/// RSA加密解密帮助类/// &lt;/summary&gt;public class RSAHelper&#123;    /// &lt;summary&gt;    /// Rsa 生成秘钥    /// &lt;/summary&gt;    /// &lt;param name=&quot;xmlPublicKey&quot;&gt;公钥&lt;/param&gt;    /// &lt;param name=&quot;xmlPrivateKey&quot;&gt;私钥&lt;/param&gt;    public static void GenerateRSAKeys(out string xmlPublicKey, out string xmlPrivateKey)    &#123;        try        &#123;            using RSA rsa = RSA.Create();            xmlPublicKey = rsa.ToXmlString(false);            xmlPrivateKey = rsa.ToXmlString(true);        &#125;        catch (Exception ex)        &#123;            xmlPublicKey = string.Empty;            xmlPrivateKey = string.Empty;        &#125;    &#125;    /// &lt;summary&gt;    /// RSA 加密    /// &lt;/summary&gt;    /// &lt;param name=&quot;xmlPublicKey&quot;&gt;公钥&lt;/param&gt;    /// &lt;param name=&quot;strPlaintext&quot;&gt;明文&lt;/param&gt;    /// &lt;returns&gt;RSA密文&lt;/returns&gt;    public static string RSAEncrypt(string xmlPublicKey, string strPlaintext)    &#123;        try        &#123;            byte[] originalData = Encoding.UTF8.GetBytes(strPlaintext);            using RSA rsa = RSA.Create();            rsa.FromXmlString(xmlPublicKey);            byte[] encryptedData = rsa.Encrypt(originalData, RSAEncryptionPadding.OaepSHA1);            return Convert.ToBase64String(encryptedData);        &#125;        catch (Exception ex)        &#123;            return string.Empty;        &#125;    &#125;    /// &lt;summary&gt;    /// RSA 解密    /// &lt;/summary&gt;    /// &lt;param name=&quot;xmlPrivateKey&quot;&gt;私钥&lt;/param&gt;    /// &lt;param name=&quot;strCiphertext&quot;&gt;RSA密文&lt;/param&gt;    /// &lt;returns&gt;明文&lt;/returns&gt;    public static string RSADecrypt(string xmlPrivateKey, string strCiphertext)    &#123;        try        &#123;            byte[] encryptedData = Convert.FromBase64String(strCiphertext);            using RSA rsa = RSA.Create();            rsa.FromXmlString(xmlPrivateKey);            byte[] decryptedData = rsa.Decrypt(encryptedData, RSAEncryptionPadding.OaepSHA1);            return Encoding.UTF8.GetString(decryptedData);        &#125;        catch (Exception ex)        &#123;            return string.Empty;        &#125;    &#125;&#125;

Portable.BouncyCastle 库由于 System.Security.Cryptography.RSA 库只能使用自身生成的 xml 公钥与私钥，而想使用 OpenSSL 生成的 pem 公钥与私钥，则无法读取，使用 Portable.BouncyCastle 库可以读取编解码，但是实测似乎与 C++ OpenSSL 无法互相加密解密。
/// &lt;summary&gt;/// 基于 BouncyCastle 库加密解密 RSA/// &lt;/summary&gt;public class BouncyCastleHelper&#123;    /// &lt;summary&gt;    /// 读取 OpenSSL 生成的私钥文件 private.pem 为 AsymmetricKeyParameter    /// &lt;/summary&gt;    /// &lt;param name=&quot;privateKeyFilePath&quot;&gt;OpenSSL 生成 RSA 私钥路径&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public static AsymmetricKeyParameter ReadPrivateKeyFile(string privateKeyFilePath)    &#123;        using var reader = File.OpenText(privateKeyFilePath);        var pemReader = new PemReader(reader);        var keyObject = pemReader.ReadObject();        if (keyObject is AsymmetricCipherKeyPair keyPair)        &#123;            return keyPair.Private;        &#125;        else if (keyObject is AsymmetricKeyParameter keyParam)        &#123;            return keyParam;        &#125;        else        &#123;            throw new InvalidOperationException(&quot;Invalid private key format.&quot;);        &#125;    &#125;    /// &lt;summary&gt;    /// 读取 OpenSSL 生成的公钥文件 public.pem 为 AsymmetricKeyParameter    /// &lt;/summary&gt;    /// &lt;param name=&quot;publicKeyFilePath&quot;&gt;OpenSSL 生成 RSA 公钥路径&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public static AsymmetricKeyParameter ReadPublicKeyFile(string publicKeyFilePath)    &#123;        using var reader = File.OpenText(publicKeyFilePath);        var pemReader = new PemReader(reader);        var keyObject = pemReader.ReadObject();        if (keyObject is AsymmetricKeyParameter keyParam)        &#123;            return keyParam;        &#125;        else        &#123;            throw new InvalidOperationException(&quot;Invalid public key format.&quot;);        &#125;    &#125;    /// &lt;summary&gt;    /// 读取 OpenSSL 生成的私钥文件为 AsymmetricKeyParameter    /// &lt;/summary&gt;    /// &lt;param name=&quot;privateKey&quot;&gt;OpenSSL 生成 RSA 私钥&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public static AsymmetricKeyParameter ReadPrivateKey(string privateKey)    &#123;        StringReader stringReader = new StringReader(privateKey);        var pemReader = new PemReader(stringReader);        var keyObject = pemReader.ReadObject();        if (keyObject is AsymmetricCipherKeyPair keyPair)        &#123;            return keyPair.Private;        &#125;        else if (keyObject is AsymmetricKeyParameter keyParam)        &#123;            return keyParam;        &#125;        else        &#123;            throw new InvalidOperationException(&quot;Invalid private key format.&quot;);        &#125;    &#125;    /// &lt;summary&gt;    /// 读取 OpenSSL 生成的公钥为 AsymmetricKeyParameter    /// &lt;/summary&gt;    /// &lt;param name=&quot;publicKey&quot;&gt;OpenSSL 生成 RSA 公钥&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public static AsymmetricKeyParameter ReadPublicKey(string publicKey)    &#123;        StringReader stringReader = new StringReader(publicKey);        var pemReader = new PemReader(stringReader);        var keyObject = pemReader.ReadObject();        if (keyObject is AsymmetricKeyParameter keyParam)        &#123;            return keyParam;        &#125;        else        &#123;            throw new InvalidOperationException(&quot;Invalid public key format.&quot;);        &#125;    &#125;    /// &lt;summary&gt;    /// 根据 AsymmetricKeyParameter 生成 System.Security.Cryptography.RSA 秘钥    /// &lt;/summary&gt;    /// &lt;param name=&quot;xmlPublicKey&quot;&gt;公钥&lt;/param&gt;    /// &lt;param name=&quot;xmlPrivateKey&quot;&gt;私钥&lt;/param&gt;    public static void GenerateRSAKeys(AsymmetricKeyParameter rsaKey, out string xmlPublicKey, out string xmlPrivateKey)    &#123;        try        &#123;            if (rsaKey.IsPrivate)            &#123;                using RSA rsa = RSA.Create(DotNetUtilities.ToRSAParameters((RsaPrivateCrtKeyParameters)rsaKey));                xmlPublicKey = rsa.ToXmlString(false);                xmlPrivateKey = rsa.ToXmlString(true);            &#125;            else            &#123;                using RSA rsa = RSA.Create(DotNetUtilities.ToRSAParameters((RsaKeyParameters)rsaKey));                xmlPublicKey = rsa.ToXmlString(false);                xmlPrivateKey = string.Empty;            &#125;        &#125;        catch (Exception ex)        &#123;            xmlPublicKey = string.Empty;            xmlPrivateKey = string.Empty;        &#125;    &#125;    /// &lt;summary&gt;    /// RSA 加密    /// &lt;/summary&gt;    /// &lt;param name=&quot;publicKey&quot;&gt;公钥&lt;/param&gt;    /// &lt;param name=&quot;strPlaintext&quot;&gt;明文&lt;/param&gt;    /// &lt;returns&gt;RSA密文&lt;/returns&gt;    public static string RSAEncrypt(AsymmetricKeyParameter publicKey, string strPlaintext)    &#123;        try        &#123;            byte[] inputData = Encoding.UTF8.GetBytes(strPlaintext);            IAsymmetricBlockCipher cipher = new RsaEngine();            cipher.Init(true, publicKey);            byte[] encryptedData = cipher.ProcessBlock(inputData, 0, inputData.Length);            return Convert.ToBase64String(encryptedData);        &#125;        catch (Exception ex)        &#123;            return string.Empty;        &#125;    &#125;    /// &lt;summary&gt;    /// RSA 解密    /// &lt;/summary&gt;    /// &lt;param name=&quot;privateKey&quot;&gt;私钥&lt;/param&gt;    /// &lt;param name=&quot;strCiphertext&quot;&gt;RSA密文&lt;/param&gt;    /// &lt;returns&gt;明文&lt;/returns&gt;    public static string RSADecrypt(AsymmetricKeyParameter privateKey, string strCiphertext)    &#123;        try        &#123;            byte[] encryptedData = Convert.FromBase64String(strCiphertext);            IAsymmetricBlockCipher cipher = new RsaEngine();            cipher.Init(false, privateKey);            byte[] decryptedData = cipher.ProcessBlock(encryptedData, 0, encryptedData.Length);            return Encoding.UTF8.GetString(decryptedData);        &#125;        catch (Exception ex)        &#123;            return string.Empty;        &#125;    &#125;&#125;

截取Windows屏幕全屏或指定区域帮助类
简介平时习惯于用QQ截图，但是公司一台电脑没有外网链接，登录不了QQ截图就很麻烦，通常是按PrtSc键截取全屏幕，然后在粘贴在Windows自带的画图应用中截取区域。原本计划自己实现一个仿制QQ截图（画笔、框选、编辑文字、提取颜色）的功能，但是一直也没有付诸行动，但是需要用到的技术栈都已经整理。屏幕录像的原理也是按照固定的FPS写入视频流，但是实际测试截取速度比较慢，无法稳定在30FPS以上。
帮助类ScreenshotHelper
/// &lt;summary&gt;/// 全屏幕截图/// &lt;/summary&gt;/// &lt;returns&gt;截图Bitmap&lt;/returns&gt;public static Bitmap ScreenshotFullScreen()&#123;    try    &#123;        //得到屏幕整体宽度        double dPrimaryScreenWidth = SystemParameters.PrimaryScreenWidth;        //得到屏幕整体高度        double dPrimaryScreenHeight = SystemParameters.PrimaryScreenHeight;        //初始化使用指定的大小(屏幕大小)的 System.Drawing.Bitmap 类的新实例.        Bitmap bitmapScreenshot = new Bitmap((int)dPrimaryScreenWidth, (int)dPrimaryScreenHeight);        //从指定的载入原创建新的 System.Drawing.Graphics.        Graphics graphicsScreenshot = Graphics.FromImage(bitmapScreenshot);        //获取或设置绘制到此 System.Drawing.Graphics 的渲染质量:高质量 低速度合成.        graphicsScreenshot.CompositingQuality = System.Drawing.Drawing2D.CompositingQuality.HighQuality;        //截取电脑屏幕:从屏幕到 System.Drawing.Graphics 的绘图图面.        graphicsScreenshot.CopyFromScreen((int)0, (int)0, (int)0, (int)0, new System.Drawing.Size((int)dPrimaryScreenWidth, (int)dPrimaryScreenHeight));        return bitmapScreenshot;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 截取指定位置截图/// &lt;/summary&gt;/// &lt;param name=&quot;iStartX&quot;&gt;截取起始坐标X&lt;/param&gt;/// &lt;param name=&quot;iStartY&quot;&gt;截取起始坐标Y&lt;/param&gt;/// &lt;param name=&quot;iInterceptWidth&quot;&gt;截取宽度&lt;/param&gt;/// &lt;param name=&quot;iInterceptHeight&quot;&gt;截取高度&lt;/param&gt;/// &lt;returns&gt;截图Bitmap&lt;/returns&gt;public static Bitmap ScreenshotsSpecifyLocation(int iStartX, int iStartY, int iInterceptWidth, int iInterceptHeight)&#123;    try    &#123;        //初始化使用指定的大小(屏幕大小)的 System.Drawing.Bitmap 类的新实例.        Bitmap bitmapScreenshot = new Bitmap((int)iInterceptWidth, (int)iInterceptHeight);        //从指定的载入原创建新的 System.Drawing.Graphics.        Graphics graphicsScreenshot = Graphics.FromImage(bitmapScreenshot);        //获取或设置绘制到此 System.Drawing.Graphics 的渲染质量:高质量 低速度合成.        graphicsScreenshot.CompositingQuality = System.Drawing.Drawing2D.CompositingQuality.HighQuality;        //截取电脑屏幕:从屏幕到 System.Drawing.Graphics 的绘图图面.        graphicsScreenshot.CopyFromScreen(iStartX, iStartY, (int)0, (int)0, new System.Drawing.Size((int)iInterceptWidth, (int)iInterceptHeight));        return bitmapScreenshot;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;

WPF 通过后台绑定数据
简介WPF 中的 Data binding 为应用程序呈现数据和与数据交互提供了一种简单且一致的方式。元素可以以 .NET 对象和 XML 的形式绑定到来自不同类型数据源的数据。但是有些特殊情况下只能通过后台 FrameworkElement.SetBinding 绑定数据。
示例示例为项目需要迁移到 .Net Framework 4.5.2 的 FFME 库。
SetBinding 介绍第一个参数为用户控件的 依赖属性。第二个参数为 Binding 类，同时可以设置要使用的转换器。
namespace System.Windows&#123;    //    // 摘要:    //     为 Windows Presentation Foundation (WPF) 元素提供一套 WPF 框架级别的属性、事件和方法。 此类表示所提供的 WPF    //     框架级别实现基于 System.Windows.UIElement 定义的 WPF 核心级别 APIs。    [RuntimeNameProperty(&quot;Name&quot;)]    [StyleTypedProperty(Property = &quot;FocusVisualStyle&quot;, StyleTargetType = typeof(Control))]    [UsableDuringInitialization(true)]    [XmlLangProperty(&quot;Language&quot;)]    public class FrameworkElement : UIElement, IFrameworkInputElement, IInputElement, ISupportInitialize, IHaveResources, IQueryAmbient    &#123;        //        // 摘要:        //     基于已提供的绑定对象将一个绑定附加到此元素上。        //        // 参数:        //   dp:        //     标识应在其中建立绑定的属性。        //        //   binding:        //     表示数据绑定的详细信息。        //        // 返回结果:        //     记录绑定的条件。 此返回值可用于错误检查。        public BindingExpressionBase SetBinding(DependencyProperty dp, BindingBase binding);    &#125;&#125;

公共 IValueConverter 方法用于提供将自定义逻辑应用于绑定的方法。
internal class TimeSpanToSecondsConverter : IValueConverter&#123;    /// &lt;inheritdoc /&gt;    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)    &#123;        switch (value)        &#123;            case TimeSpan span:                return span.TotalSeconds;            case Duration duration:                return duration.HasTimeSpan ? duration.TimeSpan.TotalSeconds : 0d;            default:                return 0d;        &#125;    &#125;    /// &lt;inheritdoc /&gt;    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)    &#123;        if (value is double == false) return 0d;        var result = TimeSpan.FromTicks(System.Convert.ToInt64(TimeSpan.TicksPerSecond * (double)value));        // Do the conversion from visibility to bool        if (targetType == typeof(TimeSpan)) return result;        return targetType == typeof(Duration) ?            new Duration(result) : Activator.CreateInstance(targetType);    &#125;&#125;

