Socket Tcp 与 Udp 帮助类使用介绍
简介Socket 是一种用于网络通信的编程接口，它允许不同计算机上的程序通过网络进行数据交换。
Socket 通常分为服务端与客户端：

服务端 Socket 负责监听客户端 Socket 的连接请求，并为每个连接请求创建一个新的 Socket 实例。服务端 Socket 处理客户端的请求并发送响应。
客户端 Socket 通常是由想要与服务器进行通信的应用程序创建的。客户端 Socket 负责与服务器 Socket 建立连接、发送请求和接收响应。

Socket的实现基于 TCP（传输控制协议）和 UDP（用户数据报协议）的网络通信：

TCP（传输控制协议）：TCP 是一种面向连接的协议，它提供可靠的、有序的数据传输。在使用 TCP 时，建立连接是必要的，因此客户端 Socket 需要与服务器 Socket 建立连接，然后通过这个连接来发送和接收数据。TCP 可以确保数据的可靠性，保证数据按照发送的顺序到达目的地，还具备拥塞控制和错误恢复的机制。
UDP（用户数据报协议）：UDP 是一种无连接的协议，它提供不可靠的、无序的数据传输。与 TCP 不同，使用 UDP 不需要事先建立连接，每个数据包（也称为数据报）都是独立发送的。UDP 更适合一些实时性要求较高、数据传输较少关注可靠性的应用场景，如视频流、音频传输和在线游戏。

核心代码TCP Socket基于 TCP 协议的 Socket 的实现
TCP Socket ServerTcpServerHelper
/// &lt;summary&gt;/// Socket Tcp 服务端帮助类/// &lt;/summary&gt;public class TcpServerHelper&#123;    private TcpListener listener;    private List&lt;TcpClient&gt; clients;    private Thread listenThread;    /// &lt;summary&gt;    /// 收到数据回调    /// &lt;/summary&gt;    public event Action&lt;EndPoint, string&gt; OnDataReceived;    /// &lt;summary&gt;    ///  Socket Tcp 服务端构造函数    /// &lt;/summary&gt;    /// &lt;param name=&quot;port&quot;&gt;服务端监听端口&lt;/param&gt;    public TcpServerHelper(int port)    &#123;        Console.WriteLine($&quot;Socket tcp Server listen port:&#123;port&#125;&quot;);        listener = new TcpListener(IPAddress.Any, port);        clients = new List&lt;TcpClient&gt;();    &#125;    /// &lt;summary&gt;    /// 启动    /// &lt;/summary&gt;    public void Start()    &#123;        listenThread = new Thread(ListenForClients);        listenThread.Start();    &#125;    /// &lt;summary&gt;    /// 停止    /// &lt;/summary&gt;    public void Stop()    &#123;        listenThread?.Abort();        lock (clients)        &#123;            foreach (var client in clients)            &#123;                client.Close();            &#125;            clients.Clear();        &#125;    &#125;    /// &lt;summary&gt;    /// 监听客户端连接请求线程    /// &lt;/summary&gt;    private void ListenForClients()    &#123;        listener.Start();        while (true)        &#123;            TcpClient client = listener.AcceptTcpClient();            lock (clients)            &#123;                Console.WriteLine($&quot;Add client connection:&#123;client.Client.RemoteEndPoint&#125;&quot;);                clients.Add(client);            &#125;            Thread clientThread = new Thread(HandleClientCommunication);            clientThread.Start(client);        &#125;    &#125;    /// &lt;summary&gt;    /// 处理与客户端的通信线程    /// &lt;/summary&gt;    /// &lt;param name=&quot;clientObj&quot;&gt;&lt;/param&gt;    private void HandleClientCommunication(object clientObj)    &#123;        TcpClient client = (TcpClient)clientObj;        string clientAddress = ((IPEndPoint)client.Client.RemoteEndPoint).Address.ToString();        byte[] buffer = new byte[1024];        while (true)        &#123;            try            &#123;                int bytesRead = client.GetStream().Read(buffer, 0, buffer.Length);                if (bytesRead &gt; 0)                &#123;                    string receivedData = Encoding.UTF8.GetString(buffer, 0, bytesRead);                    OnDataReceived?.Invoke(client.Client.RemoteEndPoint, receivedData);                &#125;            &#125;            catch            &#123;                break;            &#125;        &#125;        lock (clients)        &#123;            Console.WriteLine($&quot;Break client connection:&#123;client.Client.RemoteEndPoint&#125;&quot;);            clients.Remove(client);        &#125;        client.Close();    &#125;    /// &lt;summary&gt;    /// 发送消息给所有客户端    /// &lt;/summary&gt;    /// &lt;param name=&quot;data&quot;&gt;消息&lt;/param&gt;    public void SendDataToAll(string data)    &#123;        lock (clients)        &#123;            foreach (var client in clients)            &#123;                SendData(client, data);            &#125;        &#125;    &#125;    /// &lt;summary&gt;    /// 发送消息给指定客户端    /// &lt;/summary&gt;    /// &lt;param name=&quot;client&quot;&gt;客户端&lt;/param&gt;    /// &lt;param name=&quot;data&quot;&gt;消息&lt;/param&gt;    public void SendDataToClient(TcpClient client, string data)    &#123;        if (!clients.Contains(client))        &#123;            Console.WriteLine($&quot;Client not connected to the server.&quot;);            return;        &#125;        SendData(client, data);    &#125;    /// &lt;summary&gt;    /// 发送消息    /// &lt;/summary&gt;    /// &lt;param name=&quot;client&quot;&gt;客户端连接&lt;/param&gt;    /// &lt;param name=&quot;data&quot;&gt;数据&lt;/param&gt;    private void SendData(TcpClient client, string data)    &#123;        byte[] buffer = Encoding.UTF8.GetBytes(data);        client.GetStream().Write(buffer, 0, buffer.Length);    &#125;&#125;

