/// &lt;summary&gt;/// Socket Tcp 客户端帮助类/// &lt;/summary&gt;public class TcpClientHelper&#123;    private TcpClient client;    private byte[] buffer;    /// &lt;summary&gt;    /// 收到数据回调    /// &lt;/summary&gt;    public event Action&lt;string&gt; OnDataReceived;    /// &lt;summary&gt;    /// 是否连接    /// &lt;/summary&gt;    public bool IsConnected =&gt; client != null &amp;&amp; client.Connected;    /// &lt;summary&gt;    /// 连接服务端    /// &lt;/summary&gt;    /// &lt;param name=&quot;ipAddress&quot;&gt;IP&lt;/param&gt;    /// &lt;param name=&quot;port&quot;&gt;端口号&lt;/param&gt;    public void Connect(string ipAddress, int port)    &#123;        buffer = new byte[1024];        try        &#123;            Console.WriteLine($&quot;Socket tcp Client connection to &#123;ipAddress&#125;:&#123;port&#125;&quot;);            client = new TcpClient();            // 连接到服务端            client.Connect(ipAddress, port);            // 开始接收数据            client.GetStream().BeginRead(buffer, 0, buffer.Length, ReceiveCallback, null);        &#125;        catch (Exception ex)        &#123;            Console.WriteLine(ex.ToString());        &#125;    &#125;    /// &lt;summary&gt;    /// 断开连接释放资源    /// &lt;/summary&gt;    public void Disconnect()    &#123;        client?.Close();        client = null;    &#125;    /// &lt;summary&gt;    /// 接收数据回调    /// &lt;/summary&gt;    /// &lt;param name=&quot;ar&quot;&gt;&lt;/param&gt;    private void ReceiveCallback(IAsyncResult ar)    &#123;        if (!IsConnected)        &#123;            Console.WriteLine($&quot;Client is not connected to a server.&quot;);            return;        &#125;        try        &#123;            int bytesRead = client.GetStream().EndRead(ar);            if (bytesRead &gt; 0)            &#123;                string receivedData = Encoding.UTF8.GetString(buffer, 0, bytesRead);                OnDataReceived?.Invoke(receivedData);            &#125;            // 继续接收数据            client.GetStream().BeginRead(buffer, 0, buffer.Length, ReceiveCallback, null);        &#125;        catch (Exception ex)        &#123;            Console.WriteLine(ex.ToString());        &#125;    &#125;    /// &lt;summary&gt;    /// 发送消息    /// &lt;/summary&gt;    /// &lt;param name=&quot;data&quot;&gt;消息&lt;/param&gt;    public void SendData(string data)    &#123;        if (!IsConnected)        &#123;            Console.WriteLine($&quot;Client is not connected to a server.&quot;);            return;        &#125;        byte[] buffer = Encoding.UTF8.GetBytes(data);        client.GetStream().Write(buffer, 0, buffer.Length);    &#125;&#125;

