/// &lt;summary&gt;/// Socket UDP 服务端帮助类/// &lt;/summary&gt;public class UdpServerHelper&#123;    private UdpClient udpServer;    private List&lt;IPEndPoint&gt; clients;    private Thread receiveThread;    /// &lt;summary&gt;    /// 收到数据回调    /// &lt;/summary&gt;    public event Action&lt;IPEndPoint, string&gt; OnDataReceived;    /// &lt;summary&gt;    /// Socket UDP 服务端构造函数    /// &lt;/summary&gt;    /// &lt;param name=&quot;port&quot;&gt;服务端监听端口&lt;/param&gt;    public UdpServerHelper(int port)    &#123;        Console.WriteLine($&quot;Socket UDP Server listen port:&#123;port&#125;&quot;);        udpServer = new UdpClient(port);        clients = new List&lt;IPEndPoint&gt;();    &#125;    /// &lt;summary&gt;    /// 启动    /// &lt;/summary&gt;    public void Start()    &#123;        receiveThread = new Thread(ReceiveData);        receiveThread.Start();    &#125;    /// &lt;summary&gt;    /// 停止    /// &lt;/summary&gt;    public void Stop()    &#123;        receiveThread?.Abort();        udpServer?.Close();    &#125;    /// &lt;summary&gt;    /// 接收数据线程    /// &lt;/summary&gt;    private void ReceiveData()    &#123;        IPEndPoint clientEndPoint = new IPEndPoint(IPAddress.Any, 0);        while (true)        &#123;            try            &#123;                byte[] receivedBytes = udpServer.Receive(ref clientEndPoint);                string receivedData = Encoding.UTF8.GetString(receivedBytes);                OnDataReceived?.Invoke(clientEndPoint, receivedData);                if (!clients.Contains(clientEndPoint))                &#123;                    Console.WriteLine($&quot;Add client connection:&#123;clientEndPoint&#125;&quot;);                    clients.Add(clientEndPoint);                &#125;            &#125;            catch (SocketException)            &#123;                // SocketException will be thrown when the thread is aborted or the underlying socket is closed                Console.WriteLine($&quot;Break client connection:&#123;clientEndPoint&#125;&quot;);                clients.Remove(clientEndPoint);            &#125;        &#125;    &#125;    /// &lt;summary&gt;    /// 发送消息给所有客户端    /// &lt;/summary&gt;    /// &lt;param name=&quot;data&quot;&gt;消息&lt;/param&gt;    public void SendDataToAll(string data)    &#123;        lock (clients)        &#123;            foreach (var client in clients)            &#123;                SendData(client, data);            &#125;        &#125;    &#125;    /// &lt;summary&gt;    /// 发送消息给指定客户端    /// &lt;/summary&gt;    /// &lt;param name=&quot;client&quot;&gt;客户端&lt;/param&gt;    /// &lt;param name=&quot;data&quot;&gt;消息&lt;/param&gt;    /// &lt;returns&gt;发送是否成功&lt;/returns&gt;    public bool SendDataToClient(IPEndPoint client, string data)    &#123;        if (!clients.Contains(client))        &#123;            Console.WriteLine($&quot;Client not connected to the server.&quot;);            return false;        &#125;        SendData(client, data);        return true;    &#125;    /// &lt;summary&gt;    /// 发送消息    /// &lt;/summary&gt;    /// &lt;param name=&quot;client&quot;&gt;客户端连接&lt;/param&gt;    /// &lt;param name=&quot;data&quot;&gt;数据&lt;/param&gt;    private void SendData(IPEndPoint client, string data)    &#123;        byte[] sendData = Encoding.UTF8.GetBytes(data);        udpServer.Send(sendData, sendData.Length, client);    &#125;&#125;

