基于 TaskScheduler 库操作Windows任务计划帮助类
简介任务计划 可以将任何脚本、程序或文档安排在某个最方便的时间运行。常见于系统开机自启动程序，或定期运行自动更新程序或守护程序。
帮助类TaskschdHelper
/// &lt;summary&gt;/// 创建任务计划/// &lt;/summary&gt;/// &lt;param name=&quot;strCreator&quot;&gt;作者&lt;/param&gt;/// &lt;param name=&quot;strTaskName&quot;&gt;任务名称&lt;/param&gt;/// &lt;param name=&quot;strPath&quot;&gt;任务计划路径&lt;/param&gt;/// &lt;param name=&quot;strInterval&quot;&gt;任务触发时间(PT1M:1分钟,PT1H30M:90分钟)&lt;/param&gt;/// &lt;param name=&quot;strStartBoundary&quot;&gt;任务开始时间(yyyy-MM-ddTHH:mm:ss)&lt;/param&gt;/// &lt;param name=&quot;strDescription&quot;&gt;任务描述&lt;/param&gt;/// &lt;returns&gt;任务状态&lt;/returns&gt;public static bool CreateTaskschd(string strCreator, string strTaskName, string strPath, string strInterval, string strStartBoundary, string strDescription)&#123;    try    &#123;        if (IsExists(strTaskName))        &#123;            DeleteTaskschd(strTaskName);        &#125;        //new scheduler        TaskSchedulerClass scheduler = new TaskSchedulerClass();        //pc-name/ip,username,domain,password        scheduler.Connect(null, null, null, null);        //get scheduler folder        ITaskFolder folder = scheduler.GetFolder(&quot;\\&quot;);        //set base attr         ITaskDefinition task = scheduler.NewTask(0);        task.RegistrationInfo.Author = strCreator;//creator        task.RegistrationInfo.Description = strDescription;//description        //set trigger  (IDailyTrigger ITimeTrigger)        ITimeTrigger tt = (ITimeTrigger)task.Triggers.Create(_TASK_TRIGGER_TYPE2.TASK_TRIGGER_TIME);        tt.Repetition.Interval = strInterval;// format PT1H1M==1小时1分钟 设置的值最终都会转成分钟加入到触发器        tt.StartBoundary = strStartBoundary;//start time        //set action        IExecAction action = (IExecAction)task.Actions.Create(_TASK_ACTION_TYPE.TASK_ACTION_EXEC);        action.Path = strPath;//计划任务调用的程序路径        task.Settings.ExecutionTimeLimit = &quot;PT0S&quot;; //运行任务时间超时停止任务吗? PTOS 不开启超时        task.Settings.DisallowStartIfOnBatteries = false;//只有在交流电源下才执行        task.Settings.RunOnlyIfIdle = false;//仅当计算机空闲下才执行        IRegisteredTask regTask = folder.RegisterTaskDefinition(strTaskName, task,                                                            (int)_TASK_CREATION.TASK_CREATE, null, //user                                                            null, //password                                                            _TASK_LOGON_TYPE.TASK_LOGON_INTERACTIVE_TOKEN,                                                            &quot;&quot;);        IRunningTask runTask = regTask.Run(null);        //return runTask.State;        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        //return _TASK_STATE.TASK_STATE_UNKNOWN;        return false;    &#125;&#125;/// &lt;summary&gt;/// 删除任务计划/// &lt;/summary&gt;/// &lt;param name=&quot;strTaskName&quot;&gt;任务计划名称&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool DeleteTaskschd(string strTaskName)&#123;    try    &#123;        TaskSchedulerClass taskScheduler = new TaskSchedulerClass();        taskScheduler.Connect(null, null, null, null);        ITaskFolder taskFolder = taskScheduler.GetFolder(&quot;\\&quot;);        taskFolder.DeleteTask(strTaskName, 0);        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 获得所有任务计划/// &lt;/summary&gt;/// &lt;returns&gt;所有任务计划&lt;/returns&gt;public static IRegisteredTaskCollection GetAllTaskschd()&#123;    try    &#123;        TaskSchedulerClass taskScheduler = new TaskSchedulerClass();        taskScheduler.Connect(null, null, null, null);        ITaskFolder taskFolder = taskScheduler.GetFolder(&quot;\\&quot;);        IRegisteredTaskCollection tasks_exists = taskFolder.GetTasks(1);        return tasks_exists;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return null;    &#125;&#125;/// &lt;summary&gt;/// 任务计划是否存在/// &lt;/summary&gt;/// &lt;param name=&quot;strTaskName&quot;&gt;任务计划名称&lt;/param&gt;/// &lt;returns&gt;&lt;/returns&gt;public static bool IsExists(string strTaskName)&#123;    try    &#123;        bool isExists = false;        IRegisteredTaskCollection tasks_exists = GetAllTaskschd();        for (int i = 1; i &lt;= tasks_exists.Count; i++)        &#123;            IRegisteredTask registeredTask = tasks_exists[i];            if (registeredTask.Name.Equals(strTaskName))            &#123;                isExists = true;                break;            &#125;        &#125;        return isExists;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;

重写 Dictionary 达到数据超时自动删除
简介在实际应用中存在一种需求，是数据存在有效时间，只管添加，超时后需要自动删除。通过重写集合的方式达到数据集合超时自动删除数据的需求。
代码在新增数据时创建一个针对于这条数据的计时器，调用时使用重写的 Add 方法传入数据有效时间即可。
/// &lt;summary&gt;/// 重写 Dictionary/// &lt;/summary&gt;/// &lt;typeparam name=&quot;TKey&quot;&gt;&lt;/typeparam&gt;/// &lt;typeparam name=&quot;TValue&quot;&gt;&lt;/typeparam&gt;public class TimeOutDictionary&lt;TKey, TValue&gt; : Dictionary&lt;TKey, TValue&gt;&#123;    private static object locker = new object();    /// &lt;summary&gt;    /// 重写    /// &lt;/summary&gt;    /// &lt;param name=&quot;key&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;value&quot;&gt;&lt;/param&gt;    /// &lt;param name=&quot;timeSpan&quot;&gt;超时时间&lt;/param&gt;    public void Add(TKey key, TValue value, TimeSpan timeSpan)    &#123;        lock (locker)        &#123;            if (base.ContainsKey(key))            &#123;                base[key] = value;            &#125;            else            &#123;                base.Add(key, value);            &#125;            SetTimeoutDelete(timeSpan.TotalMilliseconds, key);        &#125;    &#125;    /// &lt;summary&gt;    /// 在指定时间过后删除数据    /// &lt;/summary&gt;    /// &lt;param name=&quot;interval&quot;&gt;事件之间经过的时间（以毫秒为单位）&lt;/param&gt;    /// &lt;param name=&quot;key&quot;&gt;要删除的数据Key&lt;/param&gt;    public void SetTimeoutDelete(double interval, TKey key)    &#123;        Timer timer = new Timer(interval);        timer.Elapsed += delegate (object sender, ElapsedEventArgs e)        &#123;            lock (locker)            &#123;                timer.Enabled = false;                base.Remove(key);            &#125;        &#125;;        timer.Enabled = true;    &#125;&#125;

Mercator 投影与 WGS-84坐标系互相转换
简介WGS84 坐标系 是为GPS全球定位系统使用而建立的坐标系统。Mercator (墨卡托投影) 是一种地图投影系统，用于为地球表面的位置分配坐标，可以参考别人编制的 UTM Grid，例如中国东部属于 UTM Zone 50N。


代码引用 ProjNet 库，ProjNet 是 Proj 的 .Net 版本，是一种通用坐标转换软件，可将地理空间坐标从一个坐标参考系统 (CRS) 转换到另一个坐标参考系统。
/// &lt;summary&gt;/// Transform UTM to WGS84/// &lt;/summary&gt;/// &lt;param name=&quot;points&quot;&gt;UTM Easting Northing&lt;/param&gt;/// &lt;param name=&quot;zone&quot;&gt;UTM zone&lt;/param&gt;/// &lt;param name=&quot;north&quot;&gt;true of Northern hemisphere, false if southern&lt;/param&gt;/// &lt;returns&gt;WGS84&lt;/returns&gt;private static double[] TransformUtm32ToWgs84(double[] points, int zone = 50, bool north = true)&#123;    CoordinateTransformationFactory cstFactory = new CoordinateTransformationFactory();    ICoordinateTransformation utm32ToWgs84 = cstFactory.CreateFromCoordinateSystems(        ProjectedCoordinateSystem.WGS84_UTM(zone, north),        GeographicCoordinateSystem.WGS84    );    return utm32ToWgs84.MathTransform.Transform(points);&#125;/// &lt;summary&gt;/// Transform WGS84 to UTM/// &lt;/summary&gt;/// &lt;param name=&quot;points&quot;&gt;WGS84 Longitude Latitude&lt;/param&gt;/// &lt;param name=&quot;zone&quot;&gt;UTM zone&lt;/param&gt;/// &lt;param name=&quot;north&quot;&gt;true of Northern hemisphere, false if southern&lt;/param&gt;/// &lt;returns&gt;UTM&lt;/returns&gt;private static double[] TransformWgs84ToUtm32(double[] points, int zone = 50, bool north = true)&#123;    CoordinateTransformationFactory cstFactory = new CoordinateTransformationFactory();    ICoordinateTransformation wgs84ToUtm32 = cstFactory.CreateFromCoordinateSystems(        GeographicCoordinateSystem.WGS84,        ProjectedCoordinateSystem.WGS84_UTM(zone, north)    );    return wgs84ToUtm32.MathTransform.Transform(points);&#125;static void Main(string[] args)&#123;    var output1 = TransformUtm32ToWgs84(new[] &#123; 447617.70449733676, 4429247.0759452293 &#125;);    var output2 = TransformWgs84ToUtm32(new[] &#123; 116.386231, 40.011798 &#125;);&#125;

