调用下载private async void MainWindow_Loaded(object sender, RoutedEventArgs e)&#123;    // 基于服务端示例代码的参数    string serverUrl = &quot;https://localhost:7252/&quot;;    string requestUrl = &quot;api/File/DownloadFile&quot;;    string savePath = @&quot;D:\1.png&quot;;    var vParameters = new Dictionary&lt;string, object&gt;    &#123;        &#123; &quot;FileName&quot;, &quot;1.png&quot; &#125;    &#125;;    var vDownload = await HttpClientHelper.DownloadGetAsync(new Uri(serverUrl), requestUrl, vParameters, savePath, DownloadProgressChanged);    MessageBox.Show($&quot;保存&#123;(vDownload ? &quot;成功&quot; : &quot;失败&quot;)&#125;&quot;);&#125;/// &lt;summary&gt;/// 下载进度发生改变/// 更新界面下载进度/// &lt;/summary&gt;/// &lt;param name=&quot;arg1&quot;&gt;&lt;/param&gt;/// &lt;param name=&quot;arg2&quot;&gt;&lt;/param&gt;private void DownloadProgressChanged(object? arg1, HttpProgressEventArgs arg2)&#123;    this.Dispatcher.Invoke(new Action(() =&gt;    &#123;        if (arg2.ProgressPercentage &gt;= 0 &amp;&amp; arg2.ProgressPercentage &lt;= 100)        &#123;            // 显示进度条            progressBar.Value = arg2.ProgressPercentage / 100.0;            // 显示下载文件大小            number.Content = $&quot;&#123;ByteChange(arg2.BytesTransferred)&#125;/&#123;ByteChange(arg2.TotalBytes)&#125;&quot;;            // 显示计算下载速度            CalcDownloadSpeed(DateTime.Now, arg2.BytesTransferred);        &#125;    &#125;));&#125;private DateTime lastTime = DateTime.Now;private long BytesTransferred = 0;/// &lt;summary&gt;/// 计算下载速度/// &lt;/summary&gt;/// &lt;param name=&quot;time&quot;&gt;&lt;/param&gt;/// &lt;param name=&quot;bytesTransferred&quot;&gt;&lt;/param&gt;private void CalcDownloadSpeed(DateTime time, long bytesTransferred)&#123;    if (lastTime.Second != time.Second)    &#123;        this.Dispatcher.Invoke(new Action(() =&gt;        &#123;            number2.Content = $&quot;Speed: &#123;ByteChange(bytesTransferred - BytesTransferred)&#125;/s&quot;;        &#125;));        lastTime = time;        BytesTransferred = bytesTransferred;    &#125;&#125;/// &lt;summary&gt;/// 转换下载单位/// &lt;/summary&gt;/// &lt;param name=&quot;TotalBytes&quot;&gt;数据大小比特&lt;/param&gt;/// &lt;returns&gt;&lt;/returns&gt;private string ByteChange(long? TotalBytes)&#123;    long kb = 1024;    long mb = kb * kb;    long gb = mb * kb;    long tb = gb * kb;    if (TotalBytes &gt;= tb)    &#123;        return $&quot;&#123;Math.Round((decimal)TotalBytes / tb, 2)&#125;TB&quot;;    &#125;    else if (TotalBytes &gt;= gb)    &#123;        return $&quot;&#123;Math.Round((decimal)TotalBytes / gb, 2)&#125;GB&quot;;    &#125;    else if (TotalBytes &gt;= mb)    &#123;        return $&quot;&#123;Math.Round((decimal)TotalBytes / mb, 2)&#125;MB&quot;;    &#125;    else if (TotalBytes &gt;= kb)    &#123;        return $&quot;&#123;Math.Round((decimal)TotalBytes / kb, 2)&#125;KB&quot;;    &#125;    else    &#123;        return $&quot;&#123;TotalBytes&#125;B&quot;;    &#125;&#125;

使用 HttpClient form-data 上传文件
简介用户需求，通过 multipart&#x2F;form-data 类型 HTTP 请求上传文件，原帮助类代码参考 WebApi 帮助类，修改代码发送 HttpClient 表单文件上传请求。
代码/// &lt;summary&gt;/// 创建Post请求/// &lt;/summary&gt;/// &lt;param name=&quot;url&quot;&gt;Api访问地址&lt;/param&gt;/// &lt;param name=&quot;requestUrl&quot;&gt;详细方法路径&lt;/param&gt;/// &lt;returns&gt;Api返回值&lt;/returns&gt;public static string CreatePostHttpClient(string url, string requestUrl)&#123;    try    &#123;        string filePath = &quot;1.jpg&quot;;        string savePath = &quot;/danger/reform/before/&quot;;        HttpClient httpClient = new HttpClient();        httpClient.BaseAddress = new Uri(url);        // 创建使用 multipart/form-data MIME 类型进行编码的内容提供容器。        MultipartFormDataContent form = new MultipartFormDataContent();        // 加载文件流        FileStream fs = File.OpenRead(filePath);        var streamContent = new StreamContent(fs);        // 添加到基于字节数组的 HTTP 内容        var imageContent = new ByteArrayContent(streamContent.ReadAsByteArrayAsync().Result);        // 设置 HTTP 响应上的 Content-Type 内容标头值为 multipart/form-data        imageContent.Headers.ContentType = MediaTypeHeaderValue.Parse(&quot;multipart/form-data&quot;);        // 添加文件类型数据        form.Add(imageContent, &quot;file&quot;, Path.GetFileName(filePath));        // 添加其他文本类型数据        form.Add(new StringContent(savePath), &quot;path&quot;);        var result = httpClient.PostAsync(requestUrl, form).Result;        return result.Content.ReadAsStringAsync().Result;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return &quot;&quot;;    &#125;&#125;

使用 HttpClient 与 HttpWebRequest 两种方式调用 WebApi 帮助类
简介现最常见的软件开发模式就是 服务端（B&#x2F;S、WebApi、WebServer) + 客户端(C&#x2F;S、Android、IOS)。公司有部分新项目修改为逻辑在服务端处理，所以通过两种方法封装一个C&#x2F;S端调用WebApi接口的帮助类。调试WebApi推荐使用：Postman。
帮助类HttpClientHttpClientHelper
创建Get请求/// &lt;summary&gt;/// 创建Get请求/// &lt;/summary&gt;/// &lt;param name=&quot;url&quot;&gt;Api访问地址&lt;/param&gt;/// &lt;param name=&quot;requestUrl&quot;&gt;详细方法路径&lt;/param&gt;/// &lt;param name=&quot;parameters&quot;&gt;请求参数&lt;/param&gt;/// &lt;returns&gt;Api返回值&lt;/returns&gt;public static string CreateGetHttpClient(string url, string requestUrl, IDictionary&lt;string, string&gt; parameters)&#123;    try    &#123;        StringBuilder builder = new StringBuilder();        builder.Append(url);        builder.Append(requestUrl);        if (parameters != null &amp;&amp; parameters.Count &gt;= 1)        &#123;            builder.Append(&quot;?&quot;);            int i = 0;            foreach (var item in parameters)            &#123;                if (i &gt; 0)                &#123;                    builder.Append(&quot;&amp;&quot;);                &#125;                builder.AppendFormat(&quot;&#123;0&#125;=&#123;1&#125;&quot;, item.Key, item.Value);                i++;            &#125;        &#125;        HttpClient httpClient = new HttpClient();        httpClient.BaseAddress = new Uri(url);        var result = httpClient.GetAsync(builder.ToString()).Result;        return result.Content.ReadAsStringAsync().Result;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return &quot;&quot;;    &#125;&#125;

创建Post请求/// &lt;summary&gt;/// 创建Post请求/// &lt;/summary&gt;/// &lt;param name=&quot;url&quot;&gt;Api访问地址&lt;/param&gt;/// &lt;param name=&quot;requestUrl&quot;&gt;详细方法路径&lt;/param&gt;/// &lt;param name=&quot;parameters&quot;&gt;请求参数&lt;/param&gt;/// &lt;returns&gt;Api返回值&lt;/returns&gt;public static string CreatePostHttpClient(string url, string requestUrl, IDictionary&lt;string, string&gt; parameters)&#123;    try    &#123;        HttpClient httpClient = new HttpClient();        httpClient.BaseAddress = new Uri(url);        var result = httpClient.PostAsync(requestUrl, new FormUrlEncodedContent(parameters)).Result;        return result.Content.ReadAsStringAsync().Result;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return &quot;&quot;;    &#125;&#125;

HttpWebRequest创建Get请求/// &lt;summary&gt;/// 创建Get请求/// &lt;/summary&gt;/// &lt;param name=&quot;url&quot;&gt;Api访问地址&lt;/param&gt;/// &lt;param name=&quot;requestUrl&quot;&gt;详细方法路径&lt;/param&gt;/// &lt;param name=&quot;parameters&quot;&gt;请求参数&lt;/param&gt;/// &lt;returns&gt;Api返回值&lt;/returns&gt;public static string CreateGetHttpWebRequest(string url, string requestUrl, IDictionary&lt;string, string&gt; parameters)&#123;    try    &#123;        StringBuilder builder = new StringBuilder();        builder.Append(url);        builder.Append(requestUrl);        if (parameters != null &amp;&amp; parameters.Count &gt;= 1)        &#123;            builder.Append(&quot;?&quot;);            int i = 0;            foreach (var item in parameters)            &#123;                if (i &gt; 0)                &#123;                    builder.Append(&quot;&amp;&quot;);                &#125;                builder.AppendFormat(&quot;&#123;0&#125;=&#123;1&#125;&quot;, item.Key, item.Value);                i++;            &#125;        &#125;        HttpWebRequest request = (HttpWebRequest)WebRequest.Create(builder.ToString());        request.Method = &quot;GET&quot;;        request.ContentType = &quot;application/x-www-form-urlencoded&quot;;        StreamReader reader = new StreamReader(request.GetResponse().GetResponseStream(), Encoding.UTF8);        return reader.ReadToEnd();    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return &quot;&quot;;    &#125;&#125;/// &lt;summary&gt;/// 创建Get请求/// &lt;/summary&gt;/// &lt;param name=&quot;url&quot;&gt;Api访问地址&lt;/param&gt;/// &lt;param name=&quot;requestUrl&quot;&gt;详细方法路径&lt;/param&gt;/// &lt;param name=&quot;parameters&quot;&gt;请求参数&lt;/param&gt;/// &lt;param name=&quot;encoding&quot;&gt;字符编码&lt;/param&gt;/// &lt;param name=&quot;timout &quot;&gt;请求超时前等待的毫秒数,默认值是 100,000 毫秒（100 秒）&lt;/param&gt;/// &lt;returns&gt;Api返回值&lt;/returns&gt;public static string CreateGetHttpWebRequest(string url, string requestUrl, IDictionary&lt;string, string&gt; parameters, Encoding encoding, int timout)&#123;    try    &#123;        StringBuilder builder = new StringBuilder();        builder.Append(url);        builder.Append(requestUrl);        if (parameters != null &amp;&amp; parameters.Count &gt;= 1)        &#123;            builder.Append(&quot;?&quot;);            int i = 0;            foreach (var item in parameters)            &#123;                if (i &gt; 0)                &#123;                    builder.Append(&quot;&amp;&quot;);                &#125;                builder.AppendFormat(&quot;&#123;0&#125;=&#123;1&#125;&quot;, item.Key, item.Value);                i++;            &#125;        &#125;        HttpWebRequest request = (HttpWebRequest)WebRequest.Create(builder.ToString());        request.Method = &quot;GET&quot;;        request.ContentType = &quot;application/x-www-form-urlencoded&quot;;        request.Timeout = timout;        StreamReader reader = new StreamReader(request.GetResponse().GetResponseStream(), encoding);        return reader.ReadToEnd();    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return &quot;&quot;;    &#125;&#125;

创建Post请求/// &lt;summary&gt;/// 创建Post请求/// &lt;/summary&gt;/// &lt;param name=&quot;url&quot;&gt;Api访问地址&lt;/param&gt;/// &lt;param name=&quot;requestUrl&quot;&gt;详细方法路径&lt;/param&gt;/// &lt;param name=&quot;parameters&quot;&gt;请求参数&lt;/param&gt;/// &lt;returns&gt;Api返回值&lt;/returns&gt;public static string CreatePostHttpWebRequest(string url, string requestUrl, IDictionary&lt;string, string&gt; parameters)&#123;    try    &#123;        HttpWebRequest request = WebRequest.Create(url + requestUrl) as HttpWebRequest;        request.ProtocolVersion = HttpVersion.Version10;        request.Method = &quot;POST&quot;;        request.ContentType = &quot;application/x-www-form-urlencoded&quot;;        //如果需要POST数据        if (!(parameters == null || parameters.Count == 0))        &#123;            StringBuilder buffer = new StringBuilder();            int i = 0;            foreach (string key in parameters.Keys)            &#123;                if (i &gt; 0)                &#123;                    buffer.AppendFormat(&quot;&amp;&#123;0&#125;=&#123;1&#125;&quot;, key, parameters[key]);                &#125;                else                &#123;                    buffer.AppendFormat(&quot;&#123;0&#125;=&#123;1&#125;&quot;, key, parameters[key]);                &#125;                i++;            &#125;            byte[] data = Encoding.GetEncoding(&quot;utf-8&quot;).GetBytes(buffer.ToString());            using (Stream stream = request.GetRequestStream())            &#123;                stream.Write(data, 0, data.Length);            &#125;        &#125;        StreamReader reader = new StreamReader(request.GetResponse().GetResponseStream(), Encoding.UTF8);        return reader.ReadToEnd();    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return &quot;&quot;;    &#125;&#125;/// &lt;summary&gt;/// 创建Post请求/// &lt;/summary&gt;/// &lt;param name=&quot;url&quot;&gt;Api访问地址&lt;/param&gt;/// &lt;param name=&quot;requestUrl&quot;&gt;详细方法路径&lt;/param&gt;/// &lt;param name=&quot;parameters&quot;&gt;请求参数&lt;/param&gt;/// &lt;param name=&quot;encoding&quot;&gt;字符编码&lt;/param&gt;/// &lt;param name=&quot;timout &quot;&gt;请求超时前等待的毫秒数,默认值是 100,000 毫秒（100 秒）&lt;/param&gt;/// &lt;returns&gt;Api返回值&lt;/returns&gt;public static string CreatePostHttpWebRequest(string url, string requestUrl, IDictionary&lt;string, string&gt; parameters, Encoding encoding, int timout)&#123;    try    &#123;        HttpWebRequest request = WebRequest.Create(url + requestUrl) as HttpWebRequest;        request.ProtocolVersion = HttpVersion.Version10;        request.Method = &quot;POST&quot;;        request.ContentType = &quot;application/x-www-form-urlencoded&quot;;        request.Timeout = timout;        //如果需要POST数据        if (!(parameters == null || parameters.Count == 0))        &#123;            StringBuilder buffer = new StringBuilder();            int i = 0;            foreach (string key in parameters.Keys)            &#123;                if (i &gt; 0)                &#123;                    buffer.AppendFormat(&quot;&amp;&#123;0&#125;=&#123;1&#125;&quot;, key, parameters[key]);                &#125;                else                &#123;                    buffer.AppendFormat(&quot;&#123;0&#125;=&#123;1&#125;&quot;, key, parameters[key]);                &#125;                i++;            &#125;            byte[] data = encoding.GetBytes(buffer.ToString());            using (Stream stream = request.GetRequestStream())            &#123;                stream.Write(data, 0, data.Length);            &#125;        &#125;        StreamReader reader = new StreamReader(request.GetResponse().GetResponseStream(), Encoding.UTF8);        return reader.ReadToEnd();    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return &quot;&quot;;    &#125;&#125;

