/// &lt;summary&gt;/// 上传文件/// &lt;/summary&gt;/// &lt;param name=&quot;formData&quot;&gt;表单数据&lt;/param&gt;/// &lt;returns&gt;&lt;/returns&gt;[HttpPost]public async Task&lt;ActionResult&gt; UploadFile([FromForm] IFormCollection formData)&#123;    try    &#123;        // 打印 Text        var vKeys = formData.Keys;        foreach (var key in vKeys)        &#123;            Console.WriteLine($&quot;Text &#123;key&#125;:&#123;formData[key]&#125;&quot;);        &#125;        // 下载 File        var vFiles = formData.Files;        foreach (var file in vFiles)        &#123;            var vFileCompletePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, file.FileName);            Console.WriteLine($&quot;File &#123;file.Name&#125;:&#123;file.FileName&#125;&quot;);            using var stream = new FileStream(vFileCompletePath, FileMode.Create);            await file.CopyToAsync(stream);        &#125;        return Ok();    &#125;    catch (Exception ex)    &#123;        return BadRequest($&quot;Execute error! &#123;ex.Message&#125;&quot;);    &#125;&#125;

帮助类代码/// &lt;summary&gt;/// 文件上传/// &lt;/summary&gt;/// &lt;param name=&quot;baseAddress&quot;&gt;Api访问地址&lt;/param&gt;/// &lt;param name=&quot;requestUrl&quot;&gt;请求地址&lt;/param&gt;/// &lt;param name=&quot;parameters&quot;&gt;请求参数&lt;/param&gt;/// &lt;param name=&quot;parameterFiles&quot;&gt;请求文件参数&lt;/param&gt;/// &lt;param name=&quot;progressAction&quot;&gt;进度回调&lt;/param&gt;/// &lt;param name=&quot;token&quot;&gt;Token认证&lt;/param&gt;/// &lt;returns&gt;&lt;/returns&gt;public static async Task&lt;T?&gt; UploadPostAsync&lt;T&gt;(Uri baseAddress, string? requestUrl, IDictionary&lt;string, object&gt;? parameters, IDictionary&lt;string, string&gt;? parameterFiles, Action&lt;object?, HttpProgressEventArgs&gt;? progressAction = null, string? token = null)&#123;    ProgressMessageHandler progress = new ProgressMessageHandler();    progress.HttpSendProgress += (s, e) =&gt;    &#123;        progressAction?.Invoke(s, e);    &#125;;    var vHttpClient = HttpClientFactory.Create(progress);    vHttpClient.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue(&quot;application/json&quot;));    // 缓存文件流，finally 时释放    List&lt;FileStream&gt; files = new();    List&lt;StreamContent&gt; streams = new();    try    &#123;        if (!string.IsNullOrEmpty(token))        &#123;            vHttpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue(&quot;Bearer&quot;, token);        &#125;        vHttpClient.Timeout = TimeSpan.FromMinutes(20);        //拼接参数        var vBuilder = new StringBuilder();        vBuilder.Append(baseAddress);        vBuilder.Append(requestUrl);        // 创建使用 multipart/form-data MIME 类型进行编码的内容提供容器。        var vMultipartForm = new MultipartFormDataContent();        // 添加文本参数        if (parameters != null &amp;&amp; parameters.Count &gt;= 1)        &#123;            foreach (var parameter in parameters)            &#123;                vMultipartForm.Add(new StringContent(parameter.Value?.ToString() ?? string.Empty), parameter.Key);            &#125;        &#125;        // 添加文件参数        if (parameterFiles != null &amp;&amp; parameterFiles.Count &gt;= 1)        &#123;            foreach (var parameterFile in parameterFiles)            &#123;                string filePath = parameterFile.Value;                var fileName = Path.GetFileName(filePath);                var fileStream = File.OpenRead(filePath);                files.Add(fileStream);                var streamContent = new StreamContent(fileStream);                streams.Add(streamContent);                vMultipartForm.Add(streamContent, parameterFile.Key, fileName);            &#125;        &#125;        using var vResponse = await vHttpClient.PostAsync(vBuilder.ToString(), vMultipartForm);        if (vResponse.StatusCode == HttpStatusCode.OK)        &#123;            return typeof(T).FullName.Equals(&quot;System.String&quot;) || typeof(T).FullName.Equals(&quot;System.Boolean&quot;)                ? (T)Convert.ChangeType(await vResponse.Content.ReadAsStringAsync(), typeof(T))                : JsonConvert.DeserializeObject&lt;T&gt;(await vResponse.Content.ReadAsStringAsync());        &#125;        else        &#123;            return default;        &#125;    &#125;    catch (Exception)    &#123;        return default;    &#125;    finally    &#123;        foreach (var item in files)        &#123;            item.Dispose();        &#125;        files.Clear();        foreach (var item in streams)        &#123;            item.Dispose();        &#125;        streams.Clear();        vHttpClient.Dispose();        vHttpClient = null;        GC.Collect();    &#125;&#125;

