WebSocket 帮助类使用介绍
简介WebSocket 是一种在 Web 应用程序中实现双向通信的通信协议。传统的 Web 通信方式是基于 HTTP（超文本传输协议）的请求-响应模式，即客户端发送请求，服务器返回响应。在这种模式下，服务器通常不能主动向客户端发送数据，而是需要客户端定期发送请求来获取最新数据。这对于实时性要求较高的应用场景（如聊天室、实时数据更新）并不是很高效。WebSocket 解决了这个问题。WebSocket 建立在 HTTP 协议之上，但它是一种全双工通信协议，使得服务器和客户端可以在同一个持久连接上实时地交换数据，而不需要额外的请求和响应。WebSocket 是基于 TCP（传输控制协议）作为传输层协议，通常分为服务端与客户端。
核心代码WebSocket ServerWebSocketServerHelper
/// &lt;summary&gt;/// WebSocket 服务端帮助类/// &lt;/summary&gt;public class WebSocketServerHelper&#123;    private HttpListener listener;    private CancellationTokenSource cancellationTokenSource;    private List&lt;WebSocket&gt; webSockets;    /// &lt;summary&gt;    /// 收到数据回调    /// &lt;/summary&gt;    public event Action&lt;WebSocket, string&gt; OnDataReceived;    /// &lt;summary&gt;    /// 启动    /// 监听所有 IP 上的端口需要以管理员权限运行    /// &lt;/summary&gt;    /// &lt;param name=&quot;port&quot;&gt;&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public async Task Start(int port)    &#123;        Console.WriteLine($&quot;WebSocket Server listen port:&#123;port&#125;&quot;);        listener = new HttpListener();        listener.Prefixes.Add($&quot;http://*:&#123;port&#125;/&quot;);        listener.Start();        cancellationTokenSource = new CancellationTokenSource();        webSockets = new List&lt;WebSocket&gt;();        while (!cancellationTokenSource.IsCancellationRequested)        &#123;            HttpListenerContext context = await listener.GetContextAsync();            if (context.Request.IsWebSocketRequest)            &#123;                ProcessWebSocketRequest(context);            &#125;            else            &#123;                context.Response.StatusCode = 400;                context.Response.Close();            &#125;        &#125;    &#125;    /// &lt;summary&gt;    /// 停止    /// &lt;/summary&gt;    public void Stop()    &#123;        cancellationTokenSource.Cancel();        listener.Stop();    &#125;    /// &lt;summary&gt;    /// 处理 WebSocket 请求    /// &lt;/summary&gt;    /// &lt;param name=&quot;context&quot;&gt;&lt;/param&gt;    private async void ProcessWebSocketRequest(HttpListenerContext context)    &#123;        WebSocketContext webSocketContext = await context.AcceptWebSocketAsync(subProtocol: null);        WebSocket webSocket = webSocketContext.WebSocket;        webSockets.Add(webSocket);        Console.WriteLine($&quot;Add client connection:&#123;context.Request.RemoteEndPoint&#125;&quot;);        try        &#123;            while (webSocket.State == WebSocketState.Open)            &#123;                byte[] buffer = new byte[1024];                WebSocketReceiveResult result = await webSocket.ReceiveAsync(new ArraySegment&lt;byte&gt;(buffer), cancellationTokenSource.Token);                if (result.MessageType == WebSocketMessageType.Text)                &#123;                    string message = Encoding.UTF8.GetString(buffer, 0, result.Count);                    OnDataReceived.Invoke(webSocket, message);                &#125;                else if (result.MessageType == WebSocketMessageType.Close)                &#123;                    webSockets.Remove(webSocket);                    Console.WriteLine($&quot;Break client connection:&#123;context.Request.RemoteEndPoint&#125;&quot;);                    await webSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, &quot;&quot;, cancellationTokenSource.Token);                &#125;            &#125;        &#125;        catch (Exception ex)        &#123;            webSockets.Remove(webSocket);            Console.WriteLine($&quot;Break client connection:&#123;context.Request.RemoteEndPoint&#125;&quot;);        &#125;    &#125;    /// &lt;summary&gt;    /// 发送消息给所有客户端    /// &lt;/summary&gt;    /// &lt;param name=&quot;data&quot;&gt;消息&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public async Task SendToAllAsync(string data)    &#123;        List&lt;Task&gt; tasks = new List&lt;Task&gt;();        if (webSockets != null &amp;&amp; webSockets.Count &gt;= 1)        &#123;            foreach (WebSocket webSocket in webSockets)            &#123;                tasks.Add(webSocket.SendAsync(new ArraySegment&lt;byte&gt;(Encoding.UTF8.GetBytes(data)), WebSocketMessageType.Text, true, cancellationTokenSource.Token));            &#125;            await Task.WhenAll(tasks);        &#125;    &#125;    /// &lt;summary&gt;    /// 发送消息给指定客户端    /// &lt;/summary&gt;    /// &lt;param name=&quot;client&quot;&gt;客户端&lt;/param&gt;    /// &lt;param name=&quot;data&quot;&gt;消息&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public async Task SendToClientAsync(WebSocket client, string data)    &#123;        try        &#123;            await client.SendAsync(new ArraySegment&lt;byte&gt;(Encoding.UTF8.GetBytes(data)), WebSocketMessageType.Text, true, cancellationTokenSource.Token);        &#125;        catch (Exception)        &#123;            // 客户端已断开连接        &#125;    &#125;&#125;

WebSocket ClientWebSocketClientHelper
/// &lt;summary&gt;/// WebSocket 客户端帮助类/// &lt;/summary&gt;public class WebSocketClientHelper&#123;    private ClientWebSocket clientWebSocket;    private CancellationTokenSource cancellationTokenSource;    /// &lt;summary&gt;    /// 收到数据回调    /// &lt;/summary&gt;    public event Action&lt;string&gt; OnDataReceived;    /// &lt;summary&gt;    /// 连接服务端    /// &lt;/summary&gt;    /// &lt;param name=&quot;url&quot;&gt;ws://localhost:8080/&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public async Task Connect(string url)    &#123;        clientWebSocket = new ClientWebSocket();        cancellationTokenSource = new CancellationTokenSource();        await clientWebSocket.ConnectAsync(new Uri(url), cancellationTokenSource.Token);        await Task.Factory.StartNew(async () =&gt;        &#123;            while (clientWebSocket.State == WebSocketState.Open)            &#123;                byte[] buffer = new byte[1024];                WebSocketReceiveResult result = await clientWebSocket.ReceiveAsync(new ArraySegment&lt;byte&gt;(buffer), cancellationTokenSource.Token);                if (result.MessageType == WebSocketMessageType.Text)                &#123;                    string message = Encoding.UTF8.GetString(buffer, 0, result.Count);                    OnDataReceived?.Invoke(message);                &#125;                else if (result.MessageType == WebSocketMessageType.Close)                &#123;                    await clientWebSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, &quot;&quot;, cancellationTokenSource.Token);                &#125;            &#125;        &#125;, cancellationTokenSource.Token);    &#125;    /// &lt;summary&gt;    /// 发送消息    /// &lt;/summary&gt;    /// &lt;param name=&quot;message&quot;&gt;消息&lt;/param&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public async Task Send(string message)    &#123;        byte[] buffer = Encoding.UTF8.GetBytes(message);        await clientWebSocket.SendAsync(new ArraySegment&lt;byte&gt;(buffer), WebSocketMessageType.Text, true, cancellationTokenSource.Token);    &#125;    /// &lt;summary&gt;    /// 关闭    /// &lt;/summary&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public async Task Close()    &#123;        cancellationTokenSource.Cancel();        await clientWebSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, &quot;&quot;, cancellationTokenSource.Token);    &#125;&#125;

调用测试WebSocket Server// 监听端口int listenPort;// 启动 WebSocket Server 监听客户端连接WebSocketServerHelper _webSocketServerHelper = new WebSocketServerHelper();_webSocketServerHelper.OnDataReceived += WebSocketServer_OnDataReceived;Task.Run(async () =&gt;&#123;    await _webSocketServerHelper.Start(listenPort);    Console.WriteLine($&quot;启动 WebSocket Server 监听：&#123;listenPort&#125;&quot;);&#125;);// 客户端WebSocket client;// 发送数据string data;Task.Run(async () =&gt;&#123;    // 发送消息给指定客户端    await _webSocketServerHelper.SendToClientAsync(client, data);    // 发送消息给所有客户端    await _webSocketServerHelper.SendToAllAsync(data);&#125;);/// &lt;summary&gt;/// 消息回调/// &lt;/summary&gt;/// &lt;param name=&quot;arg1&quot;&gt;&lt;/param&gt;/// &lt;param name=&quot;arg2&quot;&gt;&lt;/param&gt;/// &lt;exception cref=&quot;NotImplementedException&quot;&gt;&lt;/exception&gt;private static void WebSocketServer_OnDataReceived(System.Net.WebSockets.WebSocket arg1, string arg2)&#123;    // 接收数据&#125;

