Change;    /// &lt;summary&gt;    /// 右摇杆 Y 变化事件    /// &lt;/summary&gt;    public event Action&lt;short&gt; RightThumbYChange;    /// &lt;summary&gt;    /// 连接控制器    /// &lt;/summary&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public bool ConnectGamepad()    &#123;        if (!isGetJoystick &amp;&amp; _timer == null)        &#123;            controller = new Controller(UserIndex.One);            if (controller != null)            &#123;                isGetJoystick = true;                _timer = new Timer(obj =&gt; Update());                _timer.Change(0, 1000 / 60);            &#125;        &#125;        return isGetJoystick;    &#125;    /// &lt;summary&gt;    /// 断开控制器    /// &lt;/summary&gt;    /// &lt;returns&gt;&lt;/returns&gt;    public void BreakOffGamepad()    &#123;        if (_timer != null)        &#123;            _timer.Dispose();            _timer = null;        &#125;        if (isGetJoystick)        &#123;            isGetJoystick = false;        &#125;    &#125;    /// &lt;summary&gt;    /// 捕获控制器数据    /// &lt;/summary&gt;    private void Update()    &#123;        try        &#123;            #region 其他功能            //// 获取电池电量和电池类型            //var vGetBatteryInformation = controller.GetBatteryInformation(BatteryDeviceType.Gamepad);            //// 获取功能按钮和震动马达信息(1)            //var vGetCapabilities = controller.GetCapabilities(DeviceQueryType.Any);            //// 获取功能按钮和震动马达信息(2)             //Capabilities vCapabilities;            //var vIsGetCapabilities = controller.GetCapabilities(DeviceQueryType.Any, out vCapabilities);            //// 获取按键信息            //Keystroke vKeystroke;            //var vGetKeystroke = controller.GetKeystroke(DeviceQueryType.Any, out vKeystroke);            //// 获取状态(1)            //var vGetState = controller.GetState();            //// 获取状态(2)            //State vState;            //var vIsGetState = controller.GetState(out vState);            //// 设置震动马达            ////var vVibration = vGetCapabilities.Vibration;            ////var vSetVibration = controller.SetVibration(vGetCapabilities.Vibration);            #endregion            // 获取状态            var vGetState = controller.GetState();            // 按钮            var vButtons = vGetState.Gamepad.Buttons;            if (ButtonsData != vButtons)            &#123;                ButtonsData = vButtons;                ButtonsChange?.Invoke(ButtonsData);            &#125;            // LT 按键 0-255            var vLeftTrigger = vGetState.Gamepad.LeftTrigger;            if (LeftTriggerData != vLeftTrigger)            &#123;                LeftTriggerData = vLeftTrigger;                LeftTriggerChange?.Invoke(LeftTriggerData);            &#125;            // RT 按键 0-255            var vRightTrigger = vGetState.Gamepad.RightTrigger;            if (RightTriggerData != vRightTrigger)            &#123;                RightTriggerData = vRightTrigger;                RightTriggerChange?.Invoke(RightTriggerData);            &#125;            // 左摇杆 X            var vLeftThumbX = vGetState.Gamepad.LeftThumbX;            if (!LeftThumbXData.Equals(vLeftThumbX))            &#123;                LeftThumbXData = vLeftThumbX;                LeftThumbXChange?.Invoke(LeftThumbXData);            &#125;            // 左摇杆 Y            var vLeftThumbY = vGetState.Gamepad.LeftThumbY;            if (!LeftThumbYData.Equals(vLeftThumbY))            &#123;                LeftThumbYData = vLeftThumbY;                LeftThumbYChange?.Invoke(LeftThumbYData);            &#125;            // 右摇杆 X            var vRightThumbX = vGetState.Gamepad.RightThumbX;            if (!RightThumbXData.Equals(vRightThumbX))            &#123;                RightThumbXData = vRightThumbX;                RightThumbXChange?.Invoke(RightThumbXData);            &#125;            // 右摇杆 Y            var vRightThumbY = vGetState.Gamepad.RightThumbY;            if (!RightThumbYData.Equals(vRightThumbY))            &#123;                RightThumbYData = vRightThumbY;     