操作 ZIP&#x2F;7z 压缩文件帮助类，以及压缩数据文本的 GZIP 帮助类
简介工作中会有需求把数据集打包成压缩文件，封装一个帮助以方便调用。ZIP 通用且最为常见的压缩格式。7-ZIP 自由开源的压缩格式，压缩效果要比普通的ZIP效果要好。GZIP 用于压缩数据流或文本。
帮助类代码及引用ZIP：ZIPHelper 引用 ICSharpCode.SharpZipLib.Zip 库
/// &lt;summary&gt;/// 压缩ZIP文件/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件保存位置&lt;/param&gt;/// &lt;param name=&quot;listFolderOrFilePath&quot;&gt;需要压缩的文件夹或文件&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool CompressionZip(string strZipPath, List&lt;string&gt; listFolderOrFilePath)&#123;    return CompressionZip(strZipPath, listFolderOrFilePath, string.Empty);&#125;/// &lt;summary&gt;/// 压缩ZIP文件(加密)/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件保存位置&lt;/param&gt;/// &lt;param name=&quot;listFolderOrFilePath&quot;&gt;需要压缩的文件夹或文件&lt;/param&gt;/// &lt;param name=&quot;strPassword&quot;&gt;压缩文件密码&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool CompressionZip(string strZipPath, List&lt;string&gt; listFolderOrFilePath, string strPassword)&#123;    try    &#123;        ZipOutputStream ComStream = new ZipOutputStream(File.Create(strZipPath));        //压缩等级(0-9)        ComStream.SetLevel(9);        //压缩文件加密        if (!string.IsNullOrEmpty(strPassword))        &#123;            ComStream.Password = strPassword;        &#125;        foreach (string strFolderOrFilePath in listFolderOrFilePath)        &#123;            if (Directory.Exists(strFolderOrFilePath))            &#123;                //如果路径是文件目录                CompressionZipDirectory(strFolderOrFilePath, ComStream, string.Empty);            &#125;            else if (File.Exists(strFolderOrFilePath))            &#123;                //如果路径是文件路径                FileStream fileStream = File.OpenRead(strFolderOrFilePath);                byte[] btsLength = new byte[fileStream.Length];                fileStream.Read(btsLength, 0, btsLength.Length);                ZipEntry zipEntry = new ZipEntry(new FileInfo(strFolderOrFilePath).Name);                ComStream.PutNextEntry(zipEntry);                ComStream.Write(btsLength, 0, btsLength.Length);            &#125;        &#125;        ComStream.Finish();        ComStream.Close();        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 压缩ZIP文件夹/// &lt;/summary&gt;/// &lt;param name=&quot;strRootPath&quot;&gt;根目录路径&lt;/param&gt;/// &lt;param name=&quot;ComStream&quot;&gt;ZIP文件输出流&lt;/param&gt;/// &lt;param name=&quot;strSubPath&quot;&gt;子目录路径&lt;/param&gt;private static void CompressionZipDirectory(string strRootPath, ZipOutputStream ComStream, string strSubPath)&#123;    try    &#123;        //创建当前文件夹        ZipEntry zipEntry = new ZipEntry(Path.Combine(strSubPath, Path.GetFileName(strRootPath) + &quot;/&quot;));        ComStream.PutNextEntry(zipEntry);        ComStream.Flush();        //遍历压缩目录        foreach (string strFolder in Directory.GetDirectories(strRootPath))        &#123;            CompressionZipDirectory(strFolder, ComStream, Path.Combine(strSubPath, Path.GetFileName(strRootPath)));        &#125;        //遍历压缩文件        foreach (string strFileName in Directory.GetFiles(strRootPath))        &#123;            FileStream fileStream = File.OpenRead(strFileName);            byte[] btsLength = new byte[fileStream.Length];            fileStream.Read(btsLength, 0, btsLength.Length);            zipEntry = new ZipEntry(Path.Combine(strSubPath, Path.GetFileName(strRootPath) + &quot;/&quot; + Path.GetFileName(strFileName)));            ComStream.PutNextEntry(zipEntry);            ComStream.Write(btsLength, 0, btsLength.Length);            if (fileStream != null)            &#123;                fileStream.Close();                fileStream.Dispose();            &#125;        &#125;        if (zipEntry != null)        &#123;            zipEntry = null;        &#125;        GC.Collect();        GC.Collect(1);    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());    &#125;&#125;/// &lt;summary&gt;/// 解压缩ZIP文件/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件保存位置&lt;/param&gt;/// &lt;param name=&quot;strDeCompressionPath&quot;&gt;需要解压到的指定位置&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool DeCompressionZip(string strZipPath, string strDeCompressionPath)&#123;    return DeCompressionZip(strZipPath, strDeCompressionPath, string.Empty);&#125;/// &lt;summary&gt;/// 解压缩ZIP文件(加密)/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件保存位置&lt;/param&gt;/// &lt;param name=&quot;strDeCompressionPath&quot;&gt;需要解压到的指定位置&lt;/param&gt;/// &lt;param name=&quot;strPassword&quot;&gt;压缩文件密码&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool DeCompressionZip(string strZipPath, string strDeCompressionPath, string strPassword)&#123;    try    &#123;        if (string.IsNullOrEmpty(strZipPath) || !File.Exists(strZipPath))        &#123;            return false;        &#125;        ZipInputStream inputStream = new ZipInputStream(File.OpenRead(strZipPath));        //压缩文件解密        if (!string.IsNullOrEmpty(strPassword))        &#123;            inputStream.Password = strPassword;        &#125;        ZipEntry zipEntry = null;        while ((zipEntry = inputStream.GetNextEntry()) != null)        &#123;            if (!string.IsNullOrEmpty(zipEntry.Name))            &#123;                string strFileName = Path.Combine(strDeCompressionPath, zipEntry.Name);                strFileName = strFileName.Replace(&#x27;/&#x27;, &#x27;\\&#x27;);                if (strFileName.EndsWith(&quot;\\&quot;))                &#123;                    Directory.CreateDirectory(strFileName);                &#125;                else                &#123;                    FileStream fileStream = null;                    int intSize = 2048;                    byte[] btsData = new byte[intSize];                    while (true)                    &#123;                        intSize = inputStream.Read(btsData, 0, btsData.Length);                        if (fileStream == null)                        &#123;                            fileStream = File.Create(strFileName);                        &#125;                        if (intSize &gt; 0)                        &#123;                            fileStream.Write(btsData, 0, btsData.Length);                        &#125;                        else                        &#123;                            break;                        &#125;                    &#125;                    if (fileStream != null)                    &#123;                        fileStream.Close();                        fileStream.Dispose();                    &#125;                &#125;            &#125;        &#125;        if (zipEntry != null)        &#123;            zipEntry = null;        &#125;        if (inputStream != null)        &#123;            inputStream.Close();            inputStream.Dispose();        &#125;        GC.Collect();        GC.Collect(1);        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;

