/// &lt;summary&gt;/// 获得当前系统X86架构7ZIP类库路径/// &lt;/summary&gt;public static string strX86_DllPath&#123;    get    &#123;        return string.Format(@&quot;&#123;0&#125;\x86\7z.dll&quot;, System.Environment.CurrentDirectory);    &#125;&#125;/// &lt;summary&gt;/// 获得当前系统X64架构7ZIP类库路径/// &lt;/summary&gt;public static string strX64_DllPath&#123;    get    &#123;        return string.Format(@&quot;&#123;0&#125;\x64\7z.dll&quot;, System.Environment.CurrentDirectory);    &#125;&#125;/// &lt;summary&gt;/// 动态链接7ZIP类库/// &lt;/summary&gt;private static void SetLibraryPath7z()&#123;    //动态链接7ZIP类库    if (IntPtr.Size == 8)    &#123;        SevenZipExtractor.SetLibraryPath(strX64_DllPath);    &#125;    else    &#123;        SevenZipExtractor.SetLibraryPath(strX86_DllPath);    &#125;&#125;/// &lt;summary&gt;/// 压缩7-ZIP文件/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件保存位置&lt;/param&gt;/// &lt;param name=&quot;fileFullNames&quot;&gt;需要压缩的文件&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool Compression7Zip(string strZipPath, params string[] fileFullNames)&#123;    try    &#123;        //动态链接7ZIP类库        SetLibraryPath7z();        //默认格式为(*.7z)        strZipPath = Path.ChangeExtension(strZipPath, &quot;7z&quot;);        //压缩7-ZIP文件        SevenZipCompressor sevenZipCompressor = new SevenZipCompressor();        //压缩等级(默认正常值)        sevenZipCompressor.CompressionLevel = CompressionLevel.Normal;        //压缩格式(默认7z压缩)        sevenZipCompressor.ArchiveFormat = OutArchiveFormat.SevenZip;        //是否保持目录结构(默认为true)        sevenZipCompressor.DirectoryStructure = true;        //是否包含空目录(默认true)          sevenZipCompressor.IncludeEmptyDirectories = true;        //压缩目录时是否使用顶层目录(默认false)          sevenZipCompressor.PreserveDirectoryRoot = false;        //加密7z头(默认false)          sevenZipCompressor.EncryptHeaders = false;        //文件加密算法        sevenZipCompressor.ZipEncryptionMethod = ZipEncryptionMethod.ZipCrypto;        //尽快压缩(不会触发*Started事件,仅触发*Finished事件)          sevenZipCompressor.FastCompression = false;        //压缩文件        sevenZipCompressor.CompressFiles(strZipPath, fileFullNames);        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 压缩7-ZIP文件(加密)/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件保存位置&lt;/param&gt;/// &lt;param name=&quot;strPassword&quot;&gt;压缩文件密码&lt;/param&gt;/// &lt;param name=&quot;fileFullNames&quot;&gt;需要压缩的文件&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool Compression7Zip(string strZipPath, string strPassword, params string[] fileFullNames)&#123;    try    &#123;        //动态链接7ZIP类库        SetLibraryPath7z();        //默认格式为(*.7z)        strZipPath = Path.ChangeExtension(strZipPath, &quot;7z&quot;);        //压缩7-ZIP文件        SevenZipCompressor sevenZipCompressor = new SevenZipCompressor();        //压缩等级(默认正常值)        sevenZipCompressor.CompressionLevel = CompressionLevel.Normal;        //压缩格式(默认7z压缩)        sevenZipCompressor.ArchiveFormat = OutArchiveFormat.SevenZip;        //是否保持目录结构(默认为true)        sevenZipCompressor.DirectoryStructure = true;        //是否包含空目录(默认true)          sevenZipCompressor.IncludeEmptyDirectories = true;        //压缩目录时是否使用顶层目录(默认false)          sevenZipCompressor.PreserveDirectoryRoot = false;        //加密7z头(默认false)          sevenZipCompressor.EncryptHeaders = true;        //文件加密算法        sevenZipCompressor.ZipEncryptionMethod = ZipEncryptionMethod.ZipCrypto;        //尽快压缩(不会触发*Started事件,仅触发*Finished事件)          sevenZipCompressor.FastCompression = false;        //压缩文件        sevenZipCompressor.CompressFilesEncrypted(strZipPath, strPassword, fileFullNames);        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 压缩7-ZIP文件夹/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件夹&lt;/param&gt;/// &lt;param name=&quot;strDirectory&quot;&gt;需要压缩的文件夹&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool Compression7ZipDirectory(string strZipPath, string strDirectory)&#123;    try    &#123;        //动态链接7ZIP类库        SetLibraryPath7z();        //默认格式为(*.7z)        strZipPath = Path.ChangeExtension(strZipPath, &quot;7z&quot;);        //压缩7-ZIP文件        SevenZipCompressor sevenZipCompressor = new SevenZipCompressor();        //压缩等级(默认正常值)        sevenZipCompressor.CompressionLevel = CompressionLevel.Normal;        //压缩格式(默认7z压缩)        sevenZipCompressor.ArchiveFormat = OutArchiveFormat.SevenZip;        //是否保持目录结构(默认为true)        sevenZipCompressor.DirectoryStructure = true;        //是否包含空目录(默认true)          sevenZipCompressor.IncludeEmptyDirectories = true;        //压缩目录时是否使用顶层目录(默认false)          sevenZipCompressor.PreserveDirectoryRoot = false;        //加密7z头(默认false)          sevenZipCompressor.EncryptHeaders = false;        //文件加密算法        sevenZipCompressor.ZipEncryptionMethod = ZipEncryptionMethod.ZipCrypto;        //尽快压缩(不会触发*Started事件,仅触发*Finished事件)          sevenZipCompressor.FastCompression = false;        //压缩文件        sevenZipCompressor.CompressDirectory(strDirectory, strZipPath);        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 压缩7-ZIP文件夹(加密)/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件夹&lt;/param&gt;/// &lt;param name=&quot;strPassword&quot;&gt;压缩文件密码&lt;/param&gt;/// &lt;param name=&quot;strDirectory&quot;&gt;需要压缩的文件夹&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool Compression7ZipDirectory(string strZipPath, string strPassword, string strDirectory)&#123;    try    &#123;        //动态链接7ZIP类库        SetLibraryPath7z();        //默认格式为(*.7z)        strZipPath = Path.ChangeExtension(strZipPath, &quot;7z&quot;);        //压缩7-ZIP文件        SevenZipCompressor sevenZipCompressor = new SevenZipCompressor();        //压缩等级(默认正常值)        sevenZipCompressor.CompressionLevel = CompressionLevel.Normal;        //压缩格式(默认7z压缩)        sevenZipCompressor.ArchiveFormat = OutArchiveFormat.SevenZip;        //是否保持目录结构(默认为true)        sevenZipCompressor.DirectoryStructure = true;        //是否包含空目录(默认true)          sevenZipCompressor.IncludeEmptyDirectories = true;        //压缩目录时是否使用顶层目录(默认false)          sevenZipCompressor.PreserveDirectoryRoot = false;        //加密7z头(默认false)          sevenZipCompressor.EncryptHeaders = true;        //文件加密算法        sevenZipCompressor.ZipEncryptionMethod = ZipEncryptionMethod.ZipCrypto;        //尽快压缩(不会触发*Started事件,仅触发*Finished事件)          sevenZipCompressor.FastCompression = false;        //压缩文件        sevenZipCompressor.CompressDirectory(strDirectory, strZipPath, strPassword);        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 解压缩7-ZIP文件/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件保存位置&lt;/param&gt;/// &lt;param name=&quot;strDeCompressionPath&quot;&gt;需要解压到的指定位置&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool DeCompression7Zip(string strZipPath, string strDeCompressionPath)&#123;    try    &#123;        if (string.IsNullOrEmpty(strZipPath) || !File.Exists(strZipPath))        &#123;            return false;        &#125;        //动态链接7ZIP类库        SetLibraryPath7z();        //创建目录        if (!Directory.Exists(strDeCompressionPath))        &#123;            Directory.CreateDirectory(strDeCompressionPath);        &#125;        //解压数据        SevenZipExtractor sevenZipExtractor = new SevenZipExtractor(strZipPath);        foreach (ArchiveFileInfo itemArchiveFileInfo in sevenZipExtractor.ArchiveFileData)        &#123;            sevenZipExtractor.ExtractFiles(strDeCompressionPath, itemArchiveFileInfo.Index);        &#125;        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;/// &lt;summary&gt;/// 解压缩7-ZIP文件(加密)/// &lt;/summary&gt;/// &lt;param name=&quot;strZipPath&quot;&gt;ZIP压缩文件保存位置&lt;/param&gt;/// &lt;param name=&quot;strDeCompressionPath&quot;&gt;需要解压到的指定位置&lt;/param&gt;/// &lt;param name=&quot;strPassword&quot;&gt;压缩文件密码&lt;/param&gt;/// &lt;returns&gt;成功返回true,失败返回false&lt;/returns&gt;public static bool DeCompression7Zip(string strZipPath, string strDeCompressionPath, string strPassword)&#123;    try    &#123;        if (string.IsNullOrEmpty(strZipPath) || !File.Exists(strZipPath))        &#123;            return false;        &#125;        //动态链接7ZIP类库        SetLibraryPath7z();        //创建目录        if (!Directory.Exists(strDeCompressionPath))        &#123;            Directory.CreateDirectory(strDeCompressionPath);        &#125;        //解压数据        SevenZipExtractor sevenZipExtractor = new SevenZipExtractor(strZipPath, strPassword);        foreach (ArchiveFileInfo itemArchiveFileInfo in sevenZipExtractor.ArchiveFileData)        &#123;            sevenZipExtractor.ExtractFiles(strDeCompressionPath, itemArchiveFileInfo.Index);        &#125;        return true;    &#125;    catch (Exception ex)    &#123;        TXTHelper.Logs(ex.ToString());        return false;    &#125;&#125;
