鼠标滚轮缩放核心代码var scaleBy = 1.04;stageZoom.on(&#x27;wheel&#x27;, e =&gt; &#123;  e.evt.preventDefault();  var oldScale = stageZoom.scaleX();  var mousePointTo = &#123;    x: stageZoom.getPointerPosition().x / oldScale - stageZoom.x() / oldScale,    y: stageZoom.getPointerPosition().y / oldScale - stageZoom.y() / oldScale  &#125;;  var newScale =    e.evt.deltaY &lt; 0 ? oldScale * scaleBy : oldScale / scaleBy;  stageZoom.scale(&#123; x: newScale, y: newScale &#125;);  var newPos = &#123;    x:      -(mousePointTo.x - stageZoom.getPointerPosition().x / newScale) *      newScale,    y:      -(mousePointTo.y - stageZoom.getPointerPosition().y / newScale) *      newScale  &#125;;  stageZoom.position(newPos);  stageZoom.batchDraw();&#125;);

